def _phase4_live_layers(channels_pre: Dict[str,int], floors: Dict[str,int]) -> List[str]:
    """
    Return whitelist layers that are still eligible to prune
    (i.e., current channels > floor).
    """
    out = []
    for k in PHASE4_WHITELIST:
        c_now = int(channels_pre.get(k, 0))
        floor = int(floors.get(k, 0))
        if c_now > floor:
            out.append(k)
    return out

