@dataclass
class RollbackSnapshot:
    """
    Structured snapshot for rollback with validation.

    Attributes:
        model_state: Complete model state dict
        channel_counts: Dict mapping conv_path to out_channels count
        trajectory_length: Length of trajectory at snapshot time
        timestamp: Time when snapshot was created
        round_idx: Round index when snapshot was created
        chunk_idx: Chunk index when snapshot was created
    """
    model_state: Dict[str, torch.Tensor]
    channel_counts: Dict[str, int]
    trajectory_length: int
    timestamp: float
    round_idx: int
    chunk_idx: int

    def validate(self) -> bool:
        """
        Validates snapshot integrity.

        Returns:
            True if snapshot is valid, False otherwise

        Checks:
        - model_state is not empty
        - channel_counts is not empty
        - channel counts match actual tensor shapes in model_state
        """
        if not self.model_state:
            print("⚠️ [Snapshot] Validation failed: model_state is empty")
            return False

        if not self.channel_counts:
            print("⚠️ [Snapshot] Validation failed: channel_counts is empty")
            return False

        # Validate channel counts match model state
        for conv_path, expected_channels in self.channel_counts.items():
            # Check if conv weight exists in model state
            weight_key = f"{conv_path}.weight" if not conv_path.endswith(".weight") else conv_path
            if weight_key in self.model_state:
                actual_channels = self.model_state[weight_key].shape[0]
                if actual_channels != expected_channels:
                    print(f"⚠️ [Snapshot] Validation failed: {conv_path} has {actual_channels} channels, expected {expected_channels}")
                    return False

        return True

@dataclass
class ChannelTracker:
    """
    Single source of truth for channel counts with floor enforcement.

    Prevents floor violations by maintaining authoritative channel counts
    and validating all pruning operations against minimum thresholds.

    Attributes:
        current: Current channel counts per layer (conv_path -> count)
        floors: Minimum allowed channels per layer (conv_path -> count)
        initial: Starting channel counts for reporting (conv_path -> count)
    """
    current: Dict[str, int]
    floors: Dict[str, int]
    initial: Dict[str, int]

    def can_prune(self, conv_path: str, count: int = 1) -> bool:
        """
        Checks if pruning count filters is allowed without violating floor.

        Args:
            conv_path: Path to conv layer (e.g., "features.0")
            count: Number of filters to prune (default: 1)

        Returns:
            True if pruning is allowed, False if it would violate floor
        """
        if conv_path not in self.current:
            print(f"⚠️ [ChannelTracker] Unknown layer: {conv_path}")
            return False

        if conv_path not in self.floors:
            print(f"⚠️ [ChannelTracker] No floor defined for: {conv_path}")
            return True  # No floor = allow pruning

        return self.current[conv_path] - count >= self.floors[conv_path]

    def prune(self, conv_path: str, count: int = 1) -> None:
        """
        Decrements channel count with validation.

        Args:
            conv_path: Path to conv layer
            count: Number of filters to prune

        Raises:
            KeyError: If conv_path is not tracked
            ValueError: If pruning would violate floor constraint
        """
        # Validate conv_path exists before accessing
        if conv_path not in self.current:
            raise KeyError(
                f"Cannot prune from unknown layer: {conv_path}\n"
                f"  Tracked layers: {list(self.current.keys())}"
            )

        if not self.can_prune(conv_path, count):
            raise ValueError(
                f"Cannot prune {count} filter(s) from {conv_path}: "
                f"would violate floor constraint.\n"
                f"  Current: {self.current.get(conv_path, 'unknown')}\n"
                f"  Floor: {self.floors.get(conv_path, 'unknown')}\n"
                f"  After pruning: {self.current.get(conv_path, 0) - count}"
            )

        self.current[conv_path] -= count

    def sync_with_model(self, model, layer_specs: List[Dict]) -> None:
        """
        Syncs tracker with actual model state.

        Args:
            model: PyTorch model
            layer_specs: List of layer specifications with "conv" keys

        Updates current counts to match actual model out_channels.
        Use after rollback or any direct model modification.
        """
        for spec in layer_specs:
            conv_path = spec["conv"]
            try:
                conv = get_conv_module(model, conv_path)
                self.current[conv_path] = conv.out_channels
            except Exception as e:
                print(f"⚠️ [ChannelTracker] Failed to sync {conv_path}: {e}")

    def get_remaining(self, conv_path: str) -> int:
        """Returns number of filters that can still be pruned."""
        if conv_path not in self.current or conv_path not in self.floors:
            return 0
        return max(0, self.current[conv_path] - self.floors[conv_path])

    def snapshot(self) -> Dict[str, int]:
        """Returns a copy of current state for rollback."""
        return self.current.copy()

    def restore(self, snapshot: Dict[str, int]) -> None:
        """Restores state from a snapshot."""
        self.current = snapshot.copy()

    def print_status(self) -> None:
        """Prints current status for all layers."""
        print("  [ChannelTracker] Status:")
        for conv_path in sorted(self.current.keys()):
            current = self.current[conv_path]
            floor = self.floors.get(conv_path, 0)
            initial = self.initial.get(conv_path, current)
            remaining = self.get_remaining(conv_path)
            pruned_pct = ((initial - current) / initial * 100) if initial > 0 else 0
            print(f"    {conv_path}: {current}/{initial} ({pruned_pct:.1f}% pruned), "
                  f"floor={floor}, can_prune={remaining}")

class ErrorHandler:
    """
    Provides graceful error handling and recovery mechanisms.

    Handles failures in pruning operations, rollbacks, cache building,
    and scoring with appropriate fallback strategies.
    """

    def __init__(self, checkpoint_mgr=None, logger=None):
        """
        Initialize ErrorHandler.

        Args:
            checkpoint_mgr: Optional CheckpointManager for recovery
            logger: Optional LoggingManager for structured logging
        """
        self.checkpoint_mgr = checkpoint_mgr
        self.logger = logger
        self.error_count = 0
        self.recovery_count = 0

    @contextmanager
    def safe_operation(self, operation_name: str, fallback=None):
        """
        Context manager that wraps operations with error handling.

        Args:
            operation_name: Name of the operation for logging
            fallback: Optional callable to execute on failure

        Yields:
            None

        Example:
            with error_handler.safe_operation("cache_building", fallback=lambda: None):
                build_cache()
        """
        try:
            yield
        except Exception as e:
            self.error_count += 1
            error_msg = f"[ErrorHandler] {operation_name} failed: {e}"

            if self.logger:
                self.logger.error(error_msg)
                self.logger.error(f"Traceback: {traceback.format_exc()}")
            else:
                print(f"❌ {error_msg}")
                print(f"   Traceback: {traceback.format_exc()}")

            if fallback is not None:
                try:
                    if self.logger:
                        self.logger.info(f"[ErrorHandler] Attempting fallback for {operation_name}")
                    else:
                        print(f"   [ErrorHandler] Attempting fallback...")

                    result = fallback()
                    self.recovery_count += 1

                    if self.logger:
                        self.logger.info(f"[ErrorHandler] Fallback succeeded for {operation_name}")
                    else:
                        print(f"   ✓ Fallback succeeded")

                    return result
                except Exception as fallback_error:
                    if self.logger:
                        self.logger.error(f"[ErrorHandler] Fallback failed for {operation_name}: {fallback_error}")
                    else:
                        print(f"   ❌ Fallback also failed: {fallback_error}")
                    raise
            else:
                raise

    def handle_rollback_failure(self, model, last_good_state: Dict) -> bool:
        """
        Attempts recovery from rollback failure.

        Fallback hierarchy:
        1. Load with strict=False (allows missing/extra keys)
        2. Load from latest checkpoint (if CheckpointManager available)
        3. Fail and return False

        Args:
            model: PyTorch model to restore
            last_good_state: Last known-good state dict

        Returns:
            True if recovery succeeded, False otherwise
        """
        if self.logger:
            self.logger.warning("[ErrorHandler] Attempting rollback failure recovery")
        else:
            print("⚠️ [ErrorHandler] Attempting rollback failure recovery...")

        try:
            # Strategy 1: Try loading with strict=False
            model.load_state_dict(last_good_state, strict=False)

            if self.logger:
                self.logger.info("[ErrorHandler] Partial recovery successful (strict=False)")
            else:
                print("   ✓ Partial recovery successful (strict=False)")

            self.recovery_count += 1
            return True

        except Exception as e:
            if self.logger:
                self.logger.error(f"[ErrorHandler] Partial recovery failed: {e}")
            else:
                print(f"   ❌ Partial recovery failed: {e}")

            # Strategy 2: Try loading from checkpoint if available
            if self.checkpoint_mgr:
                try:
                    if self.logger:
                        self.logger.info("[ErrorHandler] Attempting checkpoint recovery")
                    else:
                        print("   [ErrorHandler] Attempting checkpoint recovery...")

                    checkpoints = self.checkpoint_mgr.list_checkpoints()
                    if checkpoints:
                        latest_checkpoint = checkpoints[-1]
                        checkpoint_data = self.checkpoint_mgr.load_checkpoint(latest_checkpoint)
                        model.load_state_dict(checkpoint_data['model_state_dict'], strict=True)

                        if self.logger:
                            self.logger.info(f"[ErrorHandler] Checkpoint recovery successful from {latest_checkpoint}")
                        else:
                            print(f"   ✓ Checkpoint recovery successful from {latest_checkpoint}")

                        self.recovery_count += 1
                        return True
                    else:
                        if self.logger:
                            self.logger.error("[ErrorHandler] No checkpoints available")
                        else:
                            print("   ❌ No checkpoints available")
                        return False

                except Exception as checkpoint_error:
                    if self.logger:
                        self.logger.error(f"[ErrorHandler] Checkpoint recovery failed: {checkpoint_error}")
                    else:
                        print(f"   ❌ Checkpoint recovery failed: {checkpoint_error}")
                    return False
            else:
                return False

    def handle_cache_failure(self, cache_type: str, cache_builder_fn,
                           retry_with_smaller_batch: bool = True,
                           current_batch_size: int = None) -> Any:
        """
        Handles cache building failures with retry logic.

        Args:
            cache_type: Type of cache being built (for logging)
            cache_builder_fn: Function to call to build cache
            retry_with_smaller_batch: Whether to retry with reduced batch size
            current_batch_size: Current batch size (for reduction)

        Returns:
            Cache data if successful, None otherwise
        """
        if self.logger:
            self.logger.warning(f"[ErrorHandler] Cache failure detected for {cache_type}")
        else:
            print(f"⚠️ [ErrorHandler] Cache failure detected for {cache_type}")

        if retry_with_smaller_batch and current_batch_size and current_batch_size > 1:
            try:
                reduced_batch_size = max(1, current_batch_size // 2)

                if self.logger:
                    self.logger.info(f"[ErrorHandler] Retrying {cache_type} with batch size {reduced_batch_size}")
                else:
                    print(f"   [ErrorHandler] Retrying with batch size {reduced_batch_size}...")

                result = cache_builder_fn(batch_size=reduced_batch_size)

                if self.logger:
                    self.logger.info(f"[ErrorHandler] {cache_type} retry succeeded")
                else:
                    print(f"   ✓ Retry succeeded")

                self.recovery_count += 1
                return result

            except Exception as retry_error:
                if self.logger:
                    self.logger.error(f"[ErrorHandler] {cache_type} retry failed: {retry_error}")
                else:
                    print(f"   ❌ Retry failed: {retry_error}")
                return None
        else:
            if self.logger:
                self.logger.error(f"[ErrorHandler] Cannot retry {cache_type} (batch size too small or retry disabled)")
            else:
                print(f"   ❌ Cannot retry (batch size too small or retry disabled)")
            return None

    def print_stats(self):
        """Prints error handling statistics."""
        print(f"[ErrorHandler] Statistics:")
        print(f"  Total errors handled: {self.error_count}")
        print(f"  Successful recoveries: {self.recovery_count}")
        if self.error_count > 0:
            recovery_rate = (self.recovery_count / self.error_count) * 100
            print(f"  Recovery rate: {recovery_rate:.1f}%")

# CheckpointManager class for save/load/cleanup of checkpoints
class CheckpointManager:
    """
    Manages checkpoints for pruning experiments.

    Provides save, load, list, and cleanup functionality for model checkpoints
    with validation and integrity checking.
    """

    def __init__(self, checkpoint_dir: str = "./checkpoints"):
        """
        Initialize CheckpointManager.

        Args:
            checkpoint_dir: Directory to store checkpoints

        Raises:
            PermissionError: If directory is not writable
        """
        self.checkpoint_dir = checkpoint_dir
        import os
        os.makedirs(checkpoint_dir, exist_ok=True)

        test_file = os.path.join(checkpoint_dir, ".write_test")
        try:
            with open(test_file, 'w') as f:
                f.write("test")
            os.remove(test_file)
        except Exception as e:
            raise PermissionError(
                f"Cannot write to checkpoint directory: {checkpoint_dir}\n"
                f"  Error: {e}\n"
                f"  Please ensure the directory exists and has write permissions."
            )

    def save_checkpoint(self, round_idx: int, model, trajectory: List,
                       floors: Dict, config: Dict = None) -> str:
        """
        Saves a checkpoint with model state and metadata.

        Args:
            round_idx: Current round index
            model: PyTorch model to save
            trajectory: Accuracy trajectory history
            floors: Layer floor constraints
            config: Optional configuration dict

        Returns:
            Path to saved checkpoint file
        """
        import os
        from datetime import datetime
        import hashlib

        timestamp = datetime.now().isoformat()
        checkpoint_name = f"checkpoint_round_{round_idx:03d}_{timestamp.replace(':', '-')}.pt"
        checkpoint_path = os.path.join(self.checkpoint_dir, checkpoint_name)

        # Build checkpoint data
        checkpoint_data = {
            "version": "1.0",
            "round_idx": round_idx,
            "model_state_dict": model.state_dict(),
            "trajectory": trajectory,
            "floors": floors,
            "config": config if config else {},
            "timestamp": timestamp
        }

        # Save checkpoint
        torch.save(checkpoint_data, checkpoint_path)

        # Calculate checksum for integrity
        with open(checkpoint_path, 'rb') as f:
            file_hash = hashlib.sha256(f.read()).hexdigest()

        # Save checksum separately
        checksum_path = checkpoint_path + ".sha256"
        with open(checksum_path, 'w') as f:
            f.write(file_hash)

        print(f"[CheckpointManager] Saved checkpoint: {checkpoint_name}")
        print(f"  Round: {round_idx}, Trajectory length: {len(trajectory)}")
        print(f"  Checksum: {file_hash[:16]}...")

        return checkpoint_path

    def load_checkpoint(self, path: str) -> Dict:
        """
        Loads and validates a checkpoint.

        Args:
            path: Path to checkpoint file

        Returns:
            Checkpoint data dictionary

        Raises:
            ValueError: If checkpoint is corrupted or invalid
        """
        import os
        import hashlib

        if not os.path.exists(path):
            raise ValueError(f"Checkpoint not found: {path}")

        # Verify checksum if available (optional for backward compatibility with old checkpoints)
        checksum_path = path + ".sha256"
        if os.path.exists(checksum_path):
            with open(checksum_path, 'r') as f:
                expected_hash = f.read().strip()

            with open(path, 'rb') as f:
                actual_hash = hashlib.sha256(f.read()).hexdigest()

            if actual_hash != expected_hash:
                raise ValueError(f"Checkpoint corrupted: checksum mismatch\n"
                               f"  Expected: {expected_hash[:16]}...\n"
                               f"  Actual: {actual_hash[:16]}...")

        # Load checkpoint
        checkpoint_data = torch.load(path, map_location='cpu')

        # Validate required keys
        required_keys = ["version", "round_idx", "model_state_dict", "trajectory", "floors"]
        missing_keys = [k for k in required_keys if k not in checkpoint_data]
        if missing_keys:
            raise ValueError(f"Checkpoint missing required keys: {missing_keys}")

        print(f"[CheckpointManager] Loaded checkpoint: {os.path.basename(path)}")
        print(f"  Round: {checkpoint_data['round_idx']}, "
              f"Trajectory length: {len(checkpoint_data['trajectory'])}")

        return checkpoint_data

    def list_checkpoints(self) -> List[str]:
        """
        Lists all available checkpoints sorted by creation time.

        Returns:
            List of checkpoint file paths
        """
        import os
        import glob

        pattern = os.path.join(self.checkpoint_dir, "checkpoint_round_*.pt")
        checkpoints = glob.glob(pattern)

        # Sort by modification time (oldest first)
        checkpoints.sort(key=lambda x: os.path.getmtime(x))

        return checkpoints

    def cleanup_old_checkpoints(self, keep_last_n: int = 3) -> None:
        """
        Deletes old checkpoints, keeping only the most recent N.

        Args:
            keep_last_n: Number of recent checkpoints to keep
        """
        import os

        checkpoints = self.list_checkpoints()

        if len(checkpoints) <= keep_last_n:
            print(f"[CheckpointManager] No cleanup needed ({len(checkpoints)} checkpoints)")
            return

        # Delete oldest checkpoints
        to_delete = checkpoints[:-keep_last_n]
        deleted_count = 0

        for checkpoint_path in to_delete:
            try:
                os.remove(checkpoint_path)
                # Also remove checksum file if it exists
                checksum_path = checkpoint_path + ".sha256"
                if os.path.exists(checksum_path):
                    os.remove(checksum_path)
                deleted_count += 1
            except Exception as e:
                print(f"⚠️ [CheckpointManager] Failed to delete {checkpoint_path}: {e}")

        print(f"[CheckpointManager] Cleaned up {deleted_count} old checkpoints "
              f"(kept last {keep_last_n})")

    def auto_save_on_failure(self, round_idx: int, model, trajectory: List,
                            floors: Dict, error: Exception) -> str:
        """
        Automatically save checkpoint on catastrophic failure.

        Args:
            round_idx: Current round index
            model: PyTorch model
            trajectory: Accuracy trajectory
            floors: Floor constraints
            error: Exception that caused the failure

        Returns:
            Path to emergency checkpoint
        """
        import os
        from datetime import datetime

        timestamp = datetime.now().isoformat()
        emergency_name = f"emergency_round_{round_idx:03d}_{timestamp.replace(':', '-')}.pt"
        emergency_path = os.path.join(self.checkpoint_dir, emergency_name)

        checkpoint_data = {
            "version": "1.0",
            "round_idx": round_idx,
            "model_state_dict": model.state_dict(),
            "trajectory": trajectory,
            "floors": floors,
            "timestamp": timestamp,
            "emergency": True,
            "error": str(error),
            "error_type": type(error).__name__
        }

        torch.save(checkpoint_data, emergency_path)

        print(f"🚨 [CheckpointManager] Emergency checkpoint saved: {emergency_name}")
        print(f"  Error: {type(error).__name__}: {error}")
        print(f"  Round: {round_idx}, Trajectory length: {len(trajectory)}")

        return emergency_path

    def find_latest_checkpoint(self) -> Optional[str]:
        """
        Find the most recent checkpoint for auto-resume.

        Returns:
            Path to latest checkpoint or None if no checkpoints exist
        """
        checkpoints = self.list_checkpoints()
        if not checkpoints:
            return None
        return checkpoints[-1]

    def can_resume(self) -> bool:
        """
         Check if there's a checkpoint available for resuming.

        Returns:
            True if checkpoint exists, False otherwise
        """
        return self.find_latest_checkpoint() is not None

class LoggingManager:
    """
    Provides structured logging with multiple levels and specialized methods.

    Supports DEBUG, INFO, WARNING, ERROR levels with context and specialized
    logging for pruning decisions and gate failures.
    """

    LEVELS = {"DEBUG": 0, "INFO": 1, "WARNING": 2, "ERROR": 3}

    def __init__(self, level: str = "INFO", log_file: str = None):
        """
        Initialize LoggingManager.

        Args:
            level: Logging level (DEBUG/INFO/WARNING/ERROR)
            log_file: Optional file path for logging output
        """
        self.level = level.upper()
        if self.level not in self.LEVELS:
            raise ValueError(f"Invalid log level: {level}. Must be one of {list(self.LEVELS.keys())}")

        self.level_value = self.LEVELS[self.level]
        self.log_file = log_file
        self.log_count = {level: 0 for level in self.LEVELS.keys()}

        if self.log_file:
            import os
            os.makedirs(os.path.dirname(self.log_file) if os.path.dirname(self.log_file) else ".", exist_ok=True)

    def _should_log(self, level: str) -> bool:
        """Check if message at given level should be logged."""
        return self.LEVELS[level] >= self.level_value

    def _format_message(self, level: str, msg: str, context: Dict = None) -> str:
        """Format log message with timestamp and context."""
        from datetime import datetime
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        formatted = f"[{timestamp}] [{level}] {msg}"

        if context:
            context_str = ", ".join(f"{k}={v}" for k, v in context.items())
            formatted += f" | {context_str}"

        return formatted

    def _write_log(self, formatted_msg: str):
        """Write log message to console and file if configured."""
        print(formatted_msg)

        if self.log_file:
            try:
                with open(self.log_file, 'a') as f:
                    f.write(formatted_msg + "\n")
            except Exception as e:
                print(f"⚠️ [LoggingManager] Failed to write to log file: {e}")

    def debug(self, msg: str, context: Dict = None) -> None:
        """Log debug message."""
        if self._should_log("DEBUG"):
            self.log_count["DEBUG"] += 1
            formatted = self._format_message("DEBUG", msg, context)
            self._write_log(formatted)

    def info(self, msg: str, context: Dict = None) -> None:
        """Log info message."""
        if self._should_log("INFO"):
            self.log_count["INFO"] += 1
            formatted = self._format_message("INFO", msg, context)
            self._write_log(formatted)

    def warning(self, msg: str, context: Dict = None) -> None:
        """Log warning message."""
        if self._should_log("WARNING"):
            self.log_count["WARNING"] += 1
            formatted = self._format_message("WARNING", msg, context)
            self._write_log(formatted)

    def error(self, msg: str, context: Dict = None, exc_info: bool = False) -> None:
        """
        Log error message.

        Args:
            msg: Error message
            context: Optional context dictionary
            exc_info: If True, include exception traceback
        """
        if self._should_log("ERROR"):
            self.log_count["ERROR"] += 1
            formatted = self._format_message("ERROR", msg, context)

            if exc_info:
                formatted += f"\n{traceback.format_exc()}"

            self._write_log(formatted)

    def log_pruning_decision(self, conv_path: str, filter_idx: int,
                            score: float, benefit: float) -> None:
        """
        Specialized logging for pruning decisions.

        Args:
            conv_path: Path to conv layer
            filter_idx: Index of filter being pruned
            score: Importance score
            benefit: Economic benefit
        """
        context = {
            "layer": conv_path,
            "filter": filter_idx,
            "score": f"{score:.6f}",
            "benefit": f"{benefit:.6f}"
        }
        self.info(f"Pruning decision: {conv_path} filter {filter_idx}", context)

    def log_gate_failure(self, gate_type: str, threshold: float,
                        actual: float, details: Dict = None) -> None:
        """
        Specialized logging for gate failures.

        Args:
            gate_type: Type of gate (step/cumulative/latency)
            threshold: Threshold value
            actual: Actual measured value
            details: Optional additional details
        """
        context = {
            "gate": gate_type,
            "threshold": f"{threshold:.4f}",
            "actual": f"{actual:.4f}",
            "exceeded": actual > threshold
        }

        if details:
            context.update(details)

        self.warning(f"Gate failure: {gate_type}", context)

    def print_stats(self):
        """Print logging statistics."""
        print(f"[LoggingManager] Statistics:")
        total = sum(self.log_count.values())
        print(f"  Total messages: {total}")
        for level, count in self.log_count.items():
            if count > 0:
                pct = (count / total * 100) if total > 0 else 0
                print(f"  {level}: {count} ({pct:.1f}%)")

class ValidationFramework:
    """
    Provides centralized validation methods for inputs and state.

    Validates tensors, module paths, numeric values, and provides
    decorators for automatic input validation.
    """

    @staticmethod
    def validate_tensor(t, name: str,
                       expected_device = None,
                       expected_shape: Tuple = None,
                       min_dims: int = 0,
                       max_dims: int = 10,
                       allow_empty: bool = False) -> None:
        """
        Validates tensor properties.

        Args:
            t: Tensor to validate
            name: Name of tensor for error messages
            expected_device: Expected device (e.g., torch.device('cuda:0'))
            expected_shape: Expected shape tuple (None for any dimension)
            min_dims: Minimum number of dimensions
            max_dims: Maximum number of dimensions
            allow_empty: Whether to allow empty tensors

        Raises:
            ValueError: If validation fails
        """
        if not isinstance(t, torch.Tensor):
            raise ValueError(f"{name} must be a torch.Tensor, got {type(t)}")

        # Check dimensions
        if t.ndim < min_dims:
            raise ValueError(f"{name} must have at least {min_dims} dimensions, got {t.ndim}")

        if t.ndim > max_dims:
            raise ValueError(f"{name} must have at most {max_dims} dimensions, got {t.ndim}")

        # Check empty
        if not allow_empty and t.numel() == 0:
            raise ValueError(f"{name} cannot be empty (shape: {t.shape})")

        # Check device
        if expected_device is not None:
            if t.device != expected_device:
                raise ValueError(f"{name} must be on {expected_device}, got {t.device}")

        # Check shape
        if expected_shape is not None:
            if len(expected_shape) != t.ndim:
                raise ValueError(f"{name} shape mismatch: expected {len(expected_shape)} dims, got {t.ndim}")

            for i, (expected, actual) in enumerate(zip(expected_shape, t.shape)):
                if expected is not None and expected != actual:
                    raise ValueError(f"{name} shape mismatch at dim {i}: expected {expected}, got {actual}")

    @staticmethod
    def validate_module_path(model, path: str) -> None:
        """
        Validates that a module path exists in the model.

        Args:
            model: PyTorch model
            path: Module path (e.g., "features.0")

        Raises:
            ValueError: If path doesn't exist
        """
        try:
            module = model
            for part in path.split('.'):
                if part.isdigit():
                    module = module[int(part)]
                else:
                    module = getattr(module, part)
        except (AttributeError, IndexError, KeyError) as e:
            raise ValueError(f"Module path '{path}' not found in model: {e}")

    @staticmethod
    def validate_numeric(value: float, name: str,
                        min_val: float = None,
                        max_val: float = None,
                        allow_nan: bool = False,
                        allow_inf: bool = False) -> None:
        """
        Validates numeric value is within bounds.

        Args:
            value: Value to validate
            name: Name for error messages
            min_val: Minimum allowed value (inclusive)
            max_val: Maximum allowed value (inclusive)
            allow_nan: Whether to allow NaN values
            allow_inf: Whether to allow infinite values

        Raises:
            ValueError: If validation fails
        """
        if not isinstance(value, (int, float)):
            raise ValueError(f"{name} must be numeric, got {type(value)}")

        if not allow_nan and math.isnan(value):
            raise ValueError(f"{name} cannot be NaN")

        if not allow_inf and math.isinf(value):
            raise ValueError(f"{name} cannot be infinite")

        if min_val is not None and value < min_val:
            raise ValueError(f"{name} must be >= {min_val}, got {value}")

        if max_val is not None and value > max_val:
            raise ValueError(f"{name} must be <= {max_val}, got {value}")

    @staticmethod
    def validate_inputs(func):
        """
        Decorator placeholder for automatic input validation based on type hints.

        Currently a pass-through decorator. Can be extended to parse type hints
        and automatically validate function arguments.

        Example:
            @ValidationFramework.validate_inputs
            def my_function(x: torch.Tensor, y: int):
                pass
        """
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

    @staticmethod
    def format_error_message(param_name: str, expected: str, actual: str,
                            suggestion: str = None) -> str:
        """
        Formats a clear validation error message.

        Args:
            param_name: Name of parameter that failed validation
            expected: Expected value/type
            actual: Actual value/type
            suggestion: Optional suggestion for fixing

        Returns:
            Formatted error message
        """
        msg = f"Validation failed for '{param_name}':\n"
        msg += f"  Expected: {expected}\n"
        msg += f"  Actual: {actual}"

        if suggestion:
            msg += f"\n  Suggestion: {suggestion}"

        return msg

class CacheManager:
    """
    Manages caching of expensive computations like shape probes and scores.

    Provides caching with invalidation for shapes and scores to avoid
    redundant computations during pruning.
    """

    def __init__(self):
        """Initialize CacheManager with empty caches."""
        self.shape_cache: Dict[str, Tuple[int, int]] = {}
        self.score_cache: Dict[str, torch.Tensor] = {}
        self.cache_timestamps: Dict[str, float] = {}
        self.hit_count = 0
        self.miss_count = 0

    def get_shape(self, conv_path: str) -> Optional[Tuple[int, int]]:
        """
        Returns cached shape or None if not cached.

        Args:
            conv_path: Path to conv layer

        Returns:
            Tuple of (H, W) if cached, None otherwise
        """
        if conv_path in self.shape_cache:
            self.hit_count += 1
            return self.shape_cache[conv_path]
        else:
            self.miss_count += 1
            return None

    def set_shape(self, conv_path: str, shape: Tuple[int, int]) -> None:
        """
        Caches shape with timestamp.

        Args:
            conv_path: Path to conv layer
            shape: Tuple of (H, W)
        """
        self.shape_cache[conv_path] = shape
        self.cache_timestamps[conv_path] = time.time()

    def get_score(self, conv_path: str) -> Optional[torch.Tensor]:
        """
        Returns cached score tensor or None if not cached.

        Args:
            conv_path: Path to conv layer

        Returns:
            Score tensor if cached, None otherwise
        """
        if conv_path in self.score_cache:
            self.hit_count += 1
            return self.score_cache[conv_path]
        else:
            self.miss_count += 1
            return None

    def set_score(self, conv_path: str, score: torch.Tensor) -> None:
        """
        Caches score tensor with timestamp.

        Args:
            conv_path: Path to conv layer
            score: Score tensor
        """
        self.score_cache[conv_path] = score.detach().clone()
        self.cache_timestamps[conv_path] = time.time()

    def invalidate_layer(self, conv_path: str, layer_specs: List = None) -> None:
        """
        Invalidates cache for layer and downstream layers.

        Downstream invalidation is necessary because pruning a layer changes
        the input shape for all subsequent layers, making cached shapes and
        scores invalid.

        Args:
            conv_path: Path to conv layer that was modified
            layer_specs: Optional list of layer specs to determine downstream layers
        """
        # Invalidate the layer itself
        if conv_path in self.shape_cache:
            del self.shape_cache[conv_path]
        if conv_path in self.score_cache:
            del self.score_cache[conv_path]
        if conv_path in self.cache_timestamps:
            del self.cache_timestamps[conv_path]

        # Invalidate downstream layers (shape changes propagate forward)
        if layer_specs:
            layer_paths = [spec["conv"] for spec in layer_specs]
            if conv_path in layer_paths:
                current_idx = layer_paths.index(conv_path)
                for downstream_path in layer_paths[current_idx + 1:]:
                    if downstream_path in self.shape_cache:
                        del self.shape_cache[downstream_path]
                    if downstream_path in self.score_cache:
                        del self.score_cache[downstream_path]
                    if downstream_path in self.cache_timestamps:
                        del self.cache_timestamps[downstream_path]

    def invalidate_all(self) -> None:
        """Clears entire cache (shapes + scores)."""
        self.shape_cache.clear()
        self.score_cache.clear()
        self.cache_timestamps.clear()

    def invalidate_scores(self) -> None:
        """
        Clears only score-related cache entries.

        H×W shapes for conv outputs do not change when pruning channels, so we
        keep shape_cache warm across rounds and only clear score_cache.
        """
        self.score_cache.clear()
        # Leave shape_cache and timestamps intact so shape probes remain cached.

    def print_stats(self):
        """Prints cache statistics."""
        total_requests = self.hit_count + self.miss_count
        if total_requests > 0:
            hit_rate = (self.hit_count / total_requests) * 100
            print(f"[CacheManager] Statistics:")
            print(f"  Total requests: {total_requests}")
            print(f"  Cache hits: {self.hit_count} ({hit_rate:.1f}%)")
            print(f"  Cache misses: {self.miss_count}")
            print(f"  Cached shapes: {len(self.shape_cache)}")
            print(f"  Cached scores: {len(self.score_cache)}")
        else:
            print(f"[CacheManager] No cache requests yet")

