class DeferredBNRecalibrator:
    """
    Defers BN recalibration until N chunks or round end.

    Reduces overhead by batching BN recalibration operations instead
    of running after every chunk.
    """

    def __init__(self, defer_until_chunks: int = 5):
        """
        Initialize DeferredBNRecalibrator.

        Args:
            defer_until_chunks: Number of chunks to defer before recalibrating
        """
        self.defer_until_chunks = defer_until_chunks
        self.chunks_since_recal = 0
        self.total_recals = 0
        self.deferred_count = 0

    def should_recalibrate(self) -> bool:
        """
        Check if BN recalibration should be performed.

        Returns:
            True if recalibration should happen, False to defer
        """
        self.chunks_since_recal += 1

        if self.chunks_since_recal >= self.defer_until_chunks:
            return True
        else:
            self.deferred_count += 1
            return False

    def mark_recalibrated(self):
        """Mark that recalibration was performed."""
        self.chunks_since_recal = 0
        self.total_recals += 1

    def force_recalibrate(self):
        """
        Force immediate recalibration (e.g., after rollback).

        Returns:
            True to indicate recalibration should happen
        """
        return True

    def reset_for_round(self):
        """Reset counter at round end."""
        self.chunks_since_recal = 0

    def print_stats(self):
        """Print recalibration statistics."""
        if self.total_recals > 0:
            avg_chunks_per_recal = (self.total_recals * self.defer_until_chunks + self.deferred_count) / self.total_recals
            print(f"[DeferredBNRecalibrator] Statistics:")
            print(f"  Total recalibrations: {self.total_recals}")
            print(f"  Deferred operations: {self.deferred_count}")
            print(f"  Avg chunks per recal: {avg_chunks_per_recal:.1f}")
            reduction_pct = (self.deferred_count / (self.total_recals + self.deferred_count)) * 100
            print(f"  Overhead reduction: {reduction_pct:.1f}%")
        else:
            print(f"[DeferredBNRecalibrator] No recalibrations yet")

class MixedPrecisionManager:
    """
    Manages mixed precision (FP16) evaluation for 2x speedup.

    Automatically detects GPU support and validates accuracy.
    """

    def __init__(self, enabled: bool = True, validate_accuracy: bool = True):
        """
        Initialize MixedPrecisionManager.

        Args:
            enabled: Whether to enable mixed precision
            validate_accuracy: Whether to validate FP16 vs FP32 accuracy
        """
        self.enabled = enabled
        self.validate_accuracy = validate_accuracy
        self.supported = self._check_support()
        self.validation_passed = False

        if self.enabled and not self.supported:
            print("⚠️ [MixedPrecision] FP16 not supported on this GPU, disabling")
            self.enabled = False

    def _check_support(self) -> bool:
        """Check if GPU supports FP16."""
        if not torch.cuda.is_available():
            return False

        # Check for Tensor Cores (compute capability >= 7.0)
        try:
            capability = torch.cuda.get_device_capability()
            major, minor = capability
            # Volta (7.0) and newer support Tensor Cores
            return major >= 7
        except Exception:
            return False

    @contextmanager
    def autocast_context(self):
        """
        Context manager for mixed precision evaluation.

        Usage:
            with mixed_precision.autocast_context():
                output = model(input)
        """
        if self.enabled and self.supported:
            with torch.amp.autocast(device_type='cuda', dtype=torch.float16):
                yield
        else:
            yield

    def validate_fp16_accuracy(self, model, X, y, batch_size: int,
                              tolerance: float = 0.001) -> bool:
        """
        Validate that FP16 accuracy is within tolerance of FP32.

        Args:
            model: PyTorch model
            X: Input tensor
            y: Labels
            batch_size: Batch size for evaluation
            tolerance: Maximum allowed accuracy difference

        Returns:
            True if validation passed, False otherwise
        """
        if not self.enabled or not self.supported:
            return True

        print("[MixedPrecision] Validating FP16 vs FP32 accuracy...")

        model.eval()

        # FP32 accuracy
        correct_fp32 = 0
        total = 0
        with torch.no_grad():
            for i in range(0, X.size(0), batch_size):
                batch_X = X[i:i+batch_size]
                batch_y = y[i:i+batch_size]
                outputs = model(batch_X)
                _, predicted = torch.max(outputs, 1)
                correct_fp32 += (predicted == batch_y).sum().item()
                total += batch_y.size(0)

        acc_fp32 = correct_fp32 / total

        # FP16 accuracy
        correct_fp16 = 0
        total = 0
        with torch.no_grad():
            with torch.amp.autocast(device_type='cuda', dtype=torch.float16):
                for i in range(0, X.size(0), batch_size):
                    batch_X = X[i:i+batch_size]
                    batch_y = y[i:i+batch_size]
                    outputs = model(batch_X)
                    _, predicted = torch.max(outputs, 1)
                    correct_fp16 += (predicted == batch_y).sum().item()
                    total += batch_y.size(0)

        acc_fp16 = correct_fp16 / total

        diff = abs(acc_fp32 - acc_fp16)
        passed = diff <= tolerance

        print(f"  FP32 accuracy: {acc_fp32:.4f}")
        print(f"  FP16 accuracy: {acc_fp16:.4f}")
        print(f"  Difference: {diff:.4f} (tolerance: {tolerance:.4f})")

        if passed:
            print(f"  ✓ Validation passed")
            self.validation_passed = True
        else:
            print(f"  ❌ Validation failed, disabling FP16")
            self.enabled = False
            self.validation_passed = False

        return passed

    def print_stats(self):
        """Print mixed precision statistics."""
        print(f"[MixedPrecision] Configuration:")
        print(f"  Enabled: {self.enabled}")
        print(f"  GPU supported: {self.supported}")
        print(f"  Validation passed: {self.validation_passed}")
        if self.enabled and self.supported:
            print(f"  Expected speedup: ~2x")

class ProfilerManager:
    """
    Tracks performance metrics including time, memory, and operation counts.

    Provides profiling for all major phases of the pruning process.
    """

    def __init__(self):
        """Initialize ProfilerManager with empty metrics."""
        self.timings = {}
        self.memory_snapshots = {}
        self.operation_counts = {}
        self.phase_stack = []
        self.start_times = {}

    def start_phase(self, phase_name: str):
        """
        Start timing a phase.

        Args:
            phase_name: Name of the phase to profile
        """
        self.phase_stack.append(phase_name)
        self.start_times[phase_name] = time.time()

        # Record memory if CUDA available
        if torch.cuda.is_available():
            self.memory_snapshots[f"{phase_name}_start"] = torch.cuda.memory_allocated() / 1024**2  # MB

    def end_phase(self, phase_name: str):
        """
        End timing a phase and record metrics.

        Args:
            phase_name: Name of the phase to end
        """
        if phase_name not in self.start_times:
            print(f"⚠️ [ProfilerManager] Phase '{phase_name}' was not started")
            return

        elapsed = time.time() - self.start_times[phase_name]

        if phase_name not in self.timings:
            self.timings[phase_name] = []
        self.timings[phase_name].append(elapsed)

        # Record memory if CUDA available
        if torch.cuda.is_available():
            self.memory_snapshots[f"{phase_name}_end"] = torch.cuda.memory_allocated() / 1024**2  # MB

        # Remove from stack
        if self.phase_stack and self.phase_stack[-1] == phase_name:
            self.phase_stack.pop()

        del self.start_times[phase_name]

    @contextmanager
    def profile_phase(self, phase_name: str):
        """
        Context manager for profiling a phase.

        Args:
            phase_name: Name of the phase to profile

        Usage:
            with profiler.profile_phase("scoring"):
                compute_scores()
        """
        self.start_phase(phase_name)
        try:
            yield
        finally:
            self.end_phase(phase_name)

    def count_operation(self, operation_name: str, count: int = 1):
        """
        Count an operation occurrence.

        Args:
            operation_name: Name of the operation
            count: Number of occurrences to add
        """
        if operation_name not in self.operation_counts:
            self.operation_counts[operation_name] = 0
        self.operation_counts[operation_name] += count

    def get_phase_stats(self, phase_name: str) -> Dict:
        """
        Get statistics for a phase.

        Args:
            phase_name: Name of the phase

        Returns:
            Dictionary with min, max, mean, total time
        """
        if phase_name not in self.timings or not self.timings[phase_name]:
            return {}

        times = self.timings[phase_name]
        return {
            "count": len(times),
            "total": sum(times),
            "mean": sum(times) / len(times),
            "min": min(times),
            "max": max(times)
        }

    def print_summary(self):
        """Print profiling summary."""
        print(f"\n[ProfilerManager] Performance Summary:")
        print(f"=" * 70)

        # Timing summary
        if self.timings:
            print(f"\nPhase Timings:")
            total_time = 0
            phase_times = []

            for phase_name, times in sorted(self.timings.items()):
                stats = self.get_phase_stats(phase_name)
                phase_times.append((phase_name, stats["total"]))
                total_time += stats["total"]

            # Sort by total time descending
            phase_times.sort(key=lambda x: x[1], reverse=True)

            for phase_name, phase_total in phase_times:
                stats = self.get_phase_stats(phase_name)
                pct = (phase_total / total_time * 100) if total_time > 0 else 0
                print(f"  {phase_name:30s}: {phase_total:8.2f}s ({pct:5.1f}%) "
                      f"[{stats['count']:3d} calls, avg: {stats['mean']:.3f}s]")

            print(f"  {'TOTAL':30s}: {total_time:8.2f}s")

        # Operation counts
        if self.operation_counts:
            print(f"\nOperation Counts:")
            for op_name, count in sorted(self.operation_counts.items(), key=lambda x: x[1], reverse=True):
                print(f"  {op_name:30s}: {count:,}")

        # Memory summary
        if self.memory_snapshots:
            print(f"\nMemory Snapshots (MB):")
            for snapshot_name, mem_mb in sorted(self.memory_snapshots.items()):
                print(f"  {snapshot_name:30s}: {mem_mb:8.1f} MB")

            # Peak memory
            if torch.cuda.is_available():
                peak_mb = torch.cuda.max_memory_allocated() / 1024**2
                print(f"  {'Peak GPU Memory':30s}: {peak_mb:8.1f} MB")

        print(f"=" * 70)

