# Profiling utilities: Stopwatch for timing, HCProfiler for Hierarchical Clustering metrics

class Stopwatch:
    def __init__(self): self.t = {}
    def go(self, key): self.t.setdefault(key, 0.0); self._s = time.perf_counter(); self._k = key
    def stop(self):    self.t[self._k] += (time.perf_counter()-self._s)
    def add(self, key, dt): self.t[key] = self.t.get(key, 0.0) + dt

class HCProfiler:
    def __init__(self, enabled=True):
        self.enabled = enabled
        self.counters = {"heap_pops":0, "heap_pushes":0, "pairs_sim_recomputed":0,
                         "benefit_evals":0, "benefit_eval_s":0.0, "sim_update_s":0.0, "heap_ops_s":0.0}
    def inc(self, k, v=1):  self.enabled and self.counters.__setitem__(k, self.counters.get(k,0)+v)
    def add_time(self, k, dt):
        if self.enabled:
            self.counters[k] = self.counters.get(k, 0.0) + dt

prof = HCProfiler(T.PROFILE_HC); sw = Stopwatch()

# Heartbeat function: Prints periodic progress messages
# Uses closure pattern (heartbeat.last) to maintain state between calls
def heartbeat(msg, every=T.PRINT_TIMING_EVERY):
    now = time.perf_counter()
    if (now - heartbeat.last) >= every:
        print(f"[hb] {msg} | +{now - heartbeat.last:.1f}s elapsed"); heartbeat.last = now
heartbeat.last = time.perf_counter()

def _sync():
    if torch.cuda.is_available(): torch.cuda.synchronize()

# Utility functions

@torch.no_grad()
def _median_latency_ms_on_tensor(X_sample: torch.Tensor, batch_size: int) -> float:
    """Return *per-sample* median latency in milliseconds on X_sample."""
    if not isinstance(X_sample, torch.Tensor):
        raise TypeError(f"X_sample must be a torch.Tensor, got {type(X_sample)}")
    validate_numeric(batch_size, "batch_size", min_val=1)
    if X_sample.numel() == 0:
        raise ValueError("X_sample cannot be empty")

    model.eval()
    device = next(model.parameters()).device
    n = int(X_sample.size(0))

    # Warmup pass to initialize kernels (not timed)
    if torch.cuda.is_available():
        torch.cuda.synchronize()

    for i in range(0, min(n, batch_size), batch_size):
        xb = X_sample[i:i+batch_size].to(device, non_blocking=True)
        _ = FWD_EVAL(xb)
    if torch.cuda.is_available():
        torch.cuda.synchronize()

    # Timed pass
    t0 = time.perf_counter()
    # Single pass over X_sample (no repeats): amortized per-sample latency
    for i in range(0, n, batch_size):
        xb = X_sample[i:i+batch_size].to(device, non_blocking=True)
        _ = FWD_EVAL(xb)
    if torch.cuda.is_available():
        torch.cuda.synchronize()
    dt = time.perf_counter() - t0
    return (dt * 1000.0) / max(1, n)

def _recompile_eval_and_warmup(loader, warm_batches: int = 2):
    """Recompile FWD_EVAL and warm up a couple of batches to lock kernels."""
    global FWD_EVAL
    if hasattr(torch, "compile") and torch.cuda.is_available() and T.ENABLE_COMPILE:
        try:
            if hasattr(torch, "_dynamo"):
                torch._dynamo.reset()
            FWD_EVAL = torch.compile(_raw_forward, mode="default", dynamic=True, fullgraph=False)
            w = 0
            for x,_ in loader:
                _ = FWD_EVAL(x.to(DEVICE)); w += 1
                if w >= warm_batches: break
            print("✅ plateau commit: recompiled eval graph + warm-up")
        except Exception as e:
            print("⚠️ plateau commit: skipped recompile:", e)
            FWD_EVAL = _raw_forward

def _invalidate_layer_and_dependents(conv_path, layer_specs, cache_manager):
    """
    Invalidate caches for a layer and ALL its downstream dependents.

    Called after pruning operations to ensure cached shapes and scores are refreshed.

    Dependency chain when pruning a conv layer:
    1. The conv itself (shape/score changed)
    2. Its BN (depends on conv out_channels)
    3. Its pool (depends on BN output)
    4. Next conv (in_channels depends on this conv's out_channels)
    5. Next conv's BN (depends on next conv)
    6. Linear1 (if this is the last conv, Linear1 input depends on it)

    Args:
        conv_path: Path to the pruned conv layer
        layer_specs: List of layer specifications
        cache_manager: Cache manager instance
    """
    # Invalidate the pruned layer itself
    cache_manager.invalidate_layer(conv_path, layer_specs)

    # Find this layer's position and dependents
    for i, spec in enumerate(layer_specs):
        if spec["conv"] == conv_path:
            # Invalidate next conv (its in_channels changed)
            if spec.get("next_conv"):
                cache_manager.invalidate_layer(spec["next_conv"], layer_specs)

            # If this is the last conv, Linear1 depends on it
            if i == len(layer_specs) - 1:
                # Linear1's input dimension = last_conv.out_channels * H * W
                # Shape changed, so Linear1 needs rebuild (handled elsewhere)
                pass

            break

def _maybe_plateau_commit(prev_counts: Dict[str,int], layer_specs, loader):
    """If any layer landed exactly on a plateau, recompile+warm to stabilize kernels."""
    if not T.PLATEAUS or not T.PLATEAU_COMMIT:
        return
    triggered = False
    for spec in layer_specs:
        k = spec["conv"]
        try:
            before = int(prev_counts.get(k, -1))
            after  = int(get_conv_module(model, k).out_channels)
            if (after in T.PLATEAUS) and (after != before):
                triggered = True
        except Exception:
            pass
    if triggered:
        _recompile_eval_and_warmup(sequential_loader, warm_batches=2)

def _chunked(seq, n: int):
    """Yield chunks of seq with size n. If n <= 0, yield entire seq as single chunk."""
    if not n or n <= 0:
        yield list(seq); return
    for i in range(0, len(seq), n):
        yield list(seq[i:i+n])

def validate_numeric(value, name: str, min_val=None, max_val=None, allow_none=False):
    """Validates numeric value is within bounds."""
    if value is None:
        if allow_none:
            return
        raise ValueError(f"{name} cannot be None")

    if not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be numeric, got {type(value)}")

    if min_val is not None and value < min_val:
        raise ValueError(f"{name}={value} is below minimum {min_val}")

    if max_val is not None and value > max_val:
        raise ValueError(f"{name}={value} exceeds maximum {max_val}")

    if isinstance(value, float):
        if not (-1e308 < value < 1e308):  # Check for overflow
            raise ValueError(f"{name}={value} is out of valid float range")
        if value != value:  # NaN check
            raise ValueError(f"{name} is NaN")

def get_conv_module(model, conv_path: str):
    """
    Retrieves Conv2d module from model by path.

    Handles both direct Conv2d modules and Sequential containers.

    Args:
        model: PyTorch model
        conv_path: Dotted path to conv layer (e.g., "features.0")

    Returns:
        nn.Conv2d module
    """
    m = get_module(model, conv_path)
    if isinstance(m, nn.Sequential):
        m0 = m[0]
        assert isinstance(m0, nn.Conv2d), f"Expected Conv2d at {conv_path}[0], got {type(m0)}"
        return m0
    assert isinstance(m, nn.Conv2d), f"Expected Conv2d at {conv_path}, got {type(m)}"
    return m

@dataclass
class PruneReporter:
    """
    Generates detailed pruning reports and summaries.

    Tracks pruning decisions, channel counts, and generates comprehensive
    reports for each round and final summary.
    """
    layer_specs: List[Dict[str, str]]
    layer_order: List[str] = field(default_factory=list)          # conv paths in order
    floors: Dict[str, int] = field(default_factory=dict)          # survivor floors
    rounds_ledger: List[Dict] = field(default_factory=list)       # round snapshots
    cum_picked: Dict[str, int] = field(default_factory=dict)      # filters selected for pruning (intent)
    cum_removed: Dict[str, int] = field(default_factory=dict)     # filters actually removed (may differ due to rollbacks/alignment)
    ch0: Dict[str, int] = field(default_factory=dict)             # channels at start of whole run

    def init_from_model(self, layer_floors: Dict[str, int]):
        self.layer_order = [s["conv"] for s in self.layer_specs]
        self.floors = {k: int(layer_floors.get(k, 0)) for k in self.layer_order}
        self.cum_picked = {k: 0 for k in self.layer_order}
        self.cum_removed = {k: 0 for k in self.layer_order}
        self.ch0 = {k: int(get_conv_module(model, k).out_channels) for k in self.layer_order}

    def begin_round(self, round_idx: int):
        snap = {
            "round": round_idx,
            "picked": {k: 0 for k in self.layer_order},     # intent: how many indices we plan to drop
            "before": {k: int(get_conv_module(model, k).out_channels) for k in self.layer_order},
            "after":  {},                                   # filled post-surgery
            "removed": {k: 0 for k in self.layer_order},    # realized removals (after surgery)
        }
        self.rounds_ledger.append(snap)

    def note_pick(self, conv_path: str, count: int = 1):
        if not self.rounds_ledger: return
        self.rounds_ledger[-1]["picked"][conv_path] += count

    def finish_round_after_surgery(self):
        if not self.rounds_ledger: return
        snap = self.rounds_ledger[-1]
        # Fill AFTER and REMOVED
        for k in self.layer_order:
            ch_after = int(get_conv_module(model, k).out_channels)
            ch_before = int(snap["before"][k])
            removed = max(0, ch_before - ch_after)
            snap["after"][k] = ch_after
            snap["removed"][k] = removed

            #  Reconcile picked intent with actual removed count
            # Handle odd numbers that can't divide evenly into chunks
            picked_intent = int(snap["picked"][k])
            if removed != picked_intent and removed > 0:
                # Adjust picked to match actual removed for accurate accounting
                snap["picked"][k] = removed

            self.cum_picked[k] += int(snap["picked"][k])
            self.cum_removed[k] += removed

    def print_round(self):
        if not self.rounds_ledger: return
        snap = self.rounds_ledger[-1]
        r = snap["round"]
        _bar(f"GLOBAL — ROUND {r} CHECKPOINT", width=70)
        rows = []
        for k in self.layer_order:
            b = snap["before"][k]
            a = snap["after"].get(k, b)
            rem = snap["removed"][k]
            pick = snap["picked"][k]
            floor = self.floors.get(k, 0)
            pct = (rem / max(1, b)) * 100.0
            rows.append([
                k, f"{_fmt_int(b)} → {_fmt_int(a)}",
                f"−{_fmt_int(rem)}", f"{pct:.2f}%",
                _fmt_int(pick), _fmt_int(floor),
            ])
        _print_table(
            rows,
            header=["Layer(conv)", "OutCh Before → After", "Removed", "%", "Picked", "Floor"],
            colw=[22, 22, 10, 8, 8, 6]
        )
        _rule(width=70)
        # Cumulative so far
        rows2 = []
        for k in self.layer_order:
            rows2.append([k, _fmt_int(self.cum_removed[k]), _fmt_int(self.cum_picked[k])])
        print("Cumulative (removed vs picked intent)")
        _print_table(rows2, header=["Layer(conv)", "Removed", "Picked"], colw=[22, 12, 12])
        _rule(width=70)

    def print_final_summary(self):
        _bar("PRUNING COMPLETE — SUMMARY (Global/Hybrid)", width=70)
        rows = []
        for k in self.layer_order:
            b = self.ch0[k]
            a = int(get_conv_module(model, k).out_channels)
            rem = max(0, b - a)
            pct = (rem / max(1, b)) * 100.0
            rows.append([k, f"{_fmt_int(b)} → {_fmt_int(a)}", f"−{_fmt_int(rem)}", f"{pct:.2f}%"])
        _print_table(rows, header=["Layer(conv)", "OutCh Before → After", "Δ", "%"], colw=[22, 22, 10, 8])
        _rule(width=70)

        tot_b = sum(self.ch0.values())
        tot_a = sum(int(get_conv_module(model, k).out_channels) for k in self.layer_order)
        tot_rem = max(0, tot_b - tot_a)
        _print_kv_block([
            ("Total channels (all pruned layers)", f"{_fmt_int(tot_b)} → {_fmt_int(tot_a)}  (−{_fmt_int(tot_rem)})"),
        ], width=70)

        # Optional: show every round's delta compactly
        print("Round-by-round deltas (removed / layer):")
        for snap in self.rounds_ledger:
            msg = [f"R{snap['round']}:"]
            for k in self.layer_order:
                if snap["removed"][k] > 0:
                    msg.append(f"{k}={snap['removed'][k]}")
            print("  " + " ".join(msg) if len(msg) > 1 else f"  R{snap['round']}: —")
        _rule(width=70)


