def validate_device_consistency(*tensors, expected_device=None, names=None):
    """
    Validates that multiple tensors are on the same device.

    Args:
        *tensors: Variable number of tensors to validate
        expected_device: Optional expected device (torch.device or str)
        names: Optional list of tensor names for error messages

    Raises:
        RuntimeError: If tensors are on different devices or don't match expected device

    Example:
        validate_device_consistency(X, y, model_params,
                                   expected_device=DEVICE,
                                   names=['X', 'y', 'model'])
    """
    if not tensors:
        return

    # Filter out None tensors
    valid_tensors = [(i, t) for i, t in enumerate(tensors) if t is not None]
    if not valid_tensors:
        return

    # Get device from first tensor
    first_idx, first_tensor = valid_tensors[0]
    if isinstance(first_tensor, torch.Tensor):
        reference_device = first_tensor.device
    elif isinstance(first_tensor, torch.nn.Module):
        reference_device = next(first_tensor.parameters()).device
    else:
        raise TypeError(f"Expected torch.Tensor or nn.Module, got {type(first_tensor)}")

    # Check all tensors match reference device
    for idx, tensor in valid_tensors[1:]:
        if isinstance(tensor, torch.Tensor):
            tensor_device = tensor.device
        elif isinstance(tensor, torch.nn.Module):
            tensor_device = next(tensor.parameters()).device
        else:
            continue

        if tensor_device != reference_device:
            name1 = names[first_idx] if names and first_idx < len(names) else f"tensor[{first_idx}]"
            name2 = names[idx] if names and idx < len(names) else f"tensor[{idx}]"
            raise RuntimeError(
                f"Device mismatch: {name1} on {reference_device}, "
                f"{name2} on {tensor_device}"
            )

    # Check against expected device if provided
    if expected_device is not None:
        if isinstance(expected_device, str):
            expected_device = torch.device(expected_device)

        if reference_device != expected_device:
            name = names[first_idx] if names and first_idx < len(names) else f"tensor[{first_idx}]"
            raise RuntimeError(
                f"Device mismatch: {name} on {reference_device}, "
                f"expected {expected_device}"
            )

def check_gpu_utilization(phase_name: str = "", warn_threshold: float = 0.10):
    """
    Checks GPU memory utilization (not compute utilization).

    Low memory usage is normal for small models on large GPUs (e.g., 2GB on 40GB A100).

    Returns:
        Tuple of (memory_used_gb, memory_total_gb, utilization_pct)
    """
    if not torch.cuda.is_available():
        return None, None, None

    try:
        # Get memory stats
        memory_allocated = torch.cuda.memory_allocated() / (1024**3)  # GB
        memory_reserved = torch.cuda.memory_reserved() / (1024**3)  # GB
        memory_total = torch.cuda.get_device_properties(0).total_memory / (1024**3)  # GB

        # Calculate utilization as percentage of total memory
        utilization = memory_allocated / memory_total if memory_total > 0 else 0.0

        # Only log if memory usage is extremely low (< 10%) on large GPUs
        # Note: Low memory usage is NORMAL for small models and does NOT indicate poor performance
        if utilization < warn_threshold and phase_name and memory_total > 20:  # Only warn on large GPUs (>20GB)
            print(f"ℹ️ [GPU] Memory usage in {phase_name}: {utilization*100:.1f}% "
                  f"({memory_allocated:.2f}GB / {memory_total:.2f}GB)")
            print(f"    Note: Low memory usage is normal for small models. This does NOT indicate slow performance.")

        return memory_allocated, memory_total, utilization
    except Exception as e:
        print(f"⚠️ [GPU] Could not check memory stats: {e}")
        return None, None, None

def count_params_module(m: nn.Module):
    """Count total parameters in a module (including submodules)."""
    return sum(p.numel() for p in m.parameters(recurse=True))

def conv_macs_per_image(conv: nn.Conv2d, C_in, H_out, W_out):
    """
    Calculate MACs (Multiply-Accumulate operations) for a Conv2d layer per image.

    Returns float to prevent integer overflow in large layers.
    """
    kH,kW = conv.kernel_size if isinstance(conv.kernel_size, tuple) else (conv.kernel_size, conv.kernel_size)
    groups = conv.groups
    return float(conv.out_channels * H_out * W_out * (C_in//groups) * kH * kW)

def linear_macs_per_image(l: nn.Linear):
    """
    Calculate MACs (Multiply-Accumulate operations) for a Linear layer per image.

    Returns float to prevent integer overflow.
    """
    return float(l.in_features * l.out_features)

def build_eval_cache(loader, device, limit):
    """
    Build tensor cache from dataloader for faster evaluation.

    Loads up to 'limit' samples into GPU memory to avoid repeated dataloader overhead.

    Args:
        loader: DataLoader to sample from
        device: Target device for tensors
        limit: Maximum number of samples to cache

    Returns:
        Tuple of (X, y) tensors on device
    """
    xs, ys, seen = [], [], 0
    pbar = tqdm(total=limit, desc="[Build Eval Cache]")
    for imgs, y in loader:
        if seen >= limit: break
        take = min(imgs.size(0), limit - seen)
        xs.append(imgs[:take]); ys.append(y[:take]); seen += take; pbar.update(take)
    pbar.close()
    X = torch.cat(xs, 0)[:limit].to(device)
    y = torch.cat(ys, 0)[:limit].to(device)
    return X, y

@torch.no_grad()
def layer_shapes_prepool(model, device, conv_path, pool_path, loader):
    """
    Probe output shapes of conv and pool layers using forward hooks.

    Uses a single forward pass to capture intermediate tensor shapes without
    modifying the model structure.

    Args:
        model: PyTorch model
        device: Device to run probe on
        conv_path: Path to conv layer (e.g., "features.0")
        pool_path: Path to pool layer (e.g., "features.1")
        loader: DataLoader to sample from

    Returns:
        Dict with keys "conv" and "pool" containing shape tuples
    """
    shapes = {}
    conv = get_conv_module(model, conv_path)
    pool = get_module(model, pool_path)
    def h_conv(_, __, out): shapes.setdefault("conv", out.shape); return out
    def h_pool(_, __, out): shapes.setdefault("pool", out.shape); return out
    h1 = conv.register_forward_hook(h_conv); h2 = pool.register_forward_hook(h_pool)
    # Use single-worker loader to avoid multiprocessing issues with forward hooks
    probe_loader = DataLoader(loader.dataset, batch_size=loader.batch_size,
                              shuffle=False, num_workers=0, pin_memory=False)
    imgs,_ = next(iter(probe_loader));
    with _temporarily_uncompiled_eval():
        _ = MODEL_REF.features(imgs.to(device))
    h1.remove(); h2.remove()
    return shapes

