# Phase 4 Cell 3B.2 — PROXIMITY & ACTIVE SET
# Lines: ~250 lines
# Dependencies: Cell 3A.2 (uses prof, FWD_EVAL, T toggles)
# Exports: 1 class + 5 functions + 2 constants
# Contents:
#   - _normalize_cols(), _center_cols(), cosine_sim()
#   - HCProximity (class) - hierarchical clustering with lazy deletion
#   - proximity_diagnostics() (placeholder)
#   - pick_active_indices_strict_equal(), pick_active_indices_stratified()
