# Hierarchical Clustering (HC) for channel proximity and merging

def _normalize_cols(X: torch.Tensor) -> torch.Tensor: return F.normalize(X.float(), p=2, dim=0)
def _center_cols(X: torch.Tensor) -> torch.Tensor:    return X - X.mean(dim=0, keepdim=True)
def cosine_sim(u: torch.Tensor, v: torch.Tensor) -> float:
    return float(F.normalize(u, p=2, dim=0).mul(F.normalize(v, p=2, dim=0)).sum().item())

class HCProximity:
    """
    Hierarchical Clustering for identifying similar channels to merge.

    Uses lazy deletion with version tracking to efficiently maintain a heap
    of channel pairs sorted by similarity. When channels are merged, old
    heap entries become stale but aren't removed until accessed.

    Attributes:
        metric: Similarity metric ("cosine" or "pearson")
        linkage: Linkage strategy ("single", "complete", or "centroid")
        live: Set of active (not-yet-merged) channel indices
        heap: Min-heap of (-similarity, i, j, version_i, version_j) tuples
        versions: Version counter per cluster for lazy deletion
    """
    def __init__(self, X_gap: torch.Tensor, metric: str = "cosine", linkage: str = "centroid"):
        self.metric = metric.lower(); self.linkage = linkage.lower()
        # Pearson correlation requires centering (removes mean) before computing similarity
        Xp = _center_cols(X_gap) if self.metric=="pearson" else X_gap
        self.base = Xp; self.N, self.C = Xp.shape
        self.members: Dict[int, List[int]] = {c: [c] for c in range(self.C)}
        self.vecs: Dict[int, torch.Tensor] = {c: _normalize_cols(Xp[:, c:c+1]).squeeze(1) for c in range(self.C)}
        self.live: Set[int] = set(range(self.C))
        self.heap: List[Tuple[float,int,int]] = []; self.S: Dict[Tuple[int,int], float] = {}
        self.versions: Dict[int, int] = {c: 0 for c in range(self.C)}
        self.stale_count = 0
        self.valid_count = 0
        self._build_heap()

    def _pair_sim(self, i: int, j: int) -> float:
        """
        Compute similarity between two clusters using specified linkage.

        Linkage strategies:
        - "centroid": Similarity between cluster centroids (fastest)
        - "single": Maximum similarity between any pair of members (optimistic)
        - "complete": Minimum similarity between any pair of members (pessimistic)
        - "average": Mean similarity across all member pairs
        """
        if self.linkage == "centroid":
            return cosine_sim(self.vecs[i], self.vecs[j])
        sims=[]
        for a in self.members[i]:
            va = _normalize_cols(self.base[:, a:a+1]).squeeze(1)
            for b in self.members[j]:
                vb = _normalize_cols(self.base[:, b:b+1]).squeeze(1)
                sims.append(float((va*vb).sum().item()))
        if self.linkage == "single":   return max(sims)
        if self.linkage == "complete": return min(sims)
        return sum(sims)/len(sims)

    def _build_heap(self):
        """
        Build initial similarity heap for all channel pairs.

        Computes pairwise similarities and stores them in a min-heap (negated
        for max-heap behavior). Each entry includes version numbers for lazy deletion.
        """
        idx = sorted(self.live)
        total_pairs = (len(idx)*(len(idx)-1))//2
        pbar = tqdm(total=total_pairs, desc="[Proximity Build]")
        for a in range(len(idx)):
            i = idx[a]
            for b in range(a+1, len(idx)):
                j = idx[b]
                t0 = time.perf_counter(); sim = self._pair_sim(i, j); prof.add_time("sim_update_s", time.perf_counter()-t0)
                self.S[(i,j)] = sim
                heapq.heappush(self.heap, (-sim, i, j, self.versions[i], self.versions[j]))
                prof.inc("heap_pushes"); pbar.update(1)
                self.valid_count += 1
        pbar.close()

    def pop_best(self) -> Optional[Tuple[int,int,float]]:
        """
        Pop the most similar channel pair from the heap.

        Uses lazy deletion: skips stale entries (from merged clusters) until
        finding a valid pair. Triggers heap rebuild if >50% entries are stale.

        Returns:
            Tuple of (i, j, similarity) or None if heap is empty
        """
        t0 = time.perf_counter()
        max_pops = len(self.heap) + 1000  # Prevent infinite loop if heap is corrupted
        pops = 0
        skipped_stale = 0

        if self.stale_count > 0 and self.valid_count > 0:
            stale_ratio = self.stale_count / (self.stale_count + self.valid_count)
            if stale_ratio > 0.5:
                print(f"[HCProximity] Rebuilding heap: {stale_ratio*100:.1f}% stale ({self.stale_count}/{self.stale_count + self.valid_count})")
                self._rebuild_heap()
                prof.add_time("heap_ops_s", time.perf_counter()-t0)

        while self.heap and pops < max_pops:
            entry = heapq.heappop(self.heap); prof.inc("heap_pops")
            pops += 1

            # Backward compatibility: handle old checkpoints without version tracking
            if len(entry) == 5:
                neg, i, j, ver_i, ver_j = entry
                if ver_i != self.versions.get(i, -1) or ver_j != self.versions.get(j, -1):
                    skipped_stale += 1
                    self.stale_count += 1
                    continue
            else:
                # Old format compatibility
                neg, i, j = entry

            sim = -neg
            cur = self.S.get((min(i,j), max(i,j)), None)
            if (i in self.live) and (j in self.live) and (cur is not None) and (abs(cur - sim) < 1e-6):
                if skipped_stale > 0:
                    prof.inc("stale_entries_skipped", skipped_stale)
                prof.add_time("heap_ops_s", time.perf_counter()-t0)
                return i, j, sim

        if pops >= max_pops:
            print(f"⚠️ [pop_best] Hit safety limit ({max_pops} pops) with stale heap entries")

        prof.add_time("heap_ops_s", time.perf_counter()-t0)
        return None

    def update_after_merge(self, keep: int, drop: int, op: str = "avg"):
        """
        Update proximity structure after merging two clusters.

        Increments version numbers to invalidate old heap entries (lazy deletion),
        then recomputes similarities for the merged cluster.

        Args:
            keep: Cluster index to keep
            drop: Cluster index to drop (merged into keep)
            op: Merge operation ("avg" for centroid update)
        """
        assert keep in self.live and drop in self.live
        self.live.remove(drop)

        self.versions[keep] = self.versions.get(keep, 0) + 1
        self.versions[drop] = self.versions.get(drop, 0) + 1

        if op == "avg":
            self.members[keep].extend(self.members[drop])
            cols = [self.base[:, c:c+1] for c in self.members[keep]]
            v = torch.mean(torch.cat(cols, 1), dim=1)
            self.vecs[keep] = F.normalize(v, p=2, dim=0)
        else:
            self.members[keep].extend(self.members[drop])
        # Invalidate cached similarities involving merged clusters
        for (a,b) in list(self.S.keys()):
            if (a==drop) or (b==drop) or (a==keep) or (b==keep):
                if (a,b) in self.S: del self.S[(a,b)]
        # Recompute similarities for merged cluster vs all remaining clusters
        for k in list(self.live):
            if k == keep: continue
            i,j = (k, keep) if k < keep else (keep, k)
            t0 = time.perf_counter(); sim = self._pair_sim(i, j); dt = time.perf_counter()-t0
            prof.add_time("sim_update_s", dt); prof.inc("pairs_sim_recomputed")
            self.S[(i,j)] = sim
            heapq.heappush(self.heap, (-sim, i, j, self.versions[i], self.versions[j]))
            prof.inc("heap_pushes")
            self.valid_count += 1

    def _rebuild_heap(self):
        """
        Rebuild heap from scratch, removing all stale entries.

        Called automatically when >50% of heap entries are stale (from merged clusters).
        Rebuilds with only currently valid cluster pairs.
        """
        self.heap.clear()
        self.stale_count = 0
        self.valid_count = 0

        for (i, j), sim in self.S.items():
            if i in self.live and j in self.live:
                heapq.heappush(self.heap, (-sim, i, j, self.versions[i], self.versions[j]))
                self.valid_count += 1

        print(f"  Rebuilt heap with {self.valid_count} valid entries")

    def partial_refresh(self, topk: int = 10000):
        """
        Refresh similarities for top-k most similar pairs.

        Recomputes similarities for the most promising pairs without full rebuild.
        Useful for adapting to model changes without expensive full recomputation.

        Args:
            topk: Number of top pairs to refresh

        Returns:
            Number of pairs refreshed
        """
        if topk <= 0 or not self.heap: return 0
        cand = []; seen = set()
        for entry in self.heap:
            if len(entry) == 5:
                neg, i, j, ver_i, ver_j = entry
            else:
                neg, i, j = entry
            a,b = (i,j) if i<j else (j,i)
            if (a,b) in seen: continue
            if (i in self.live) and (j in self.live):
                cand.append((i,j)); seen.add((a,b))
                if len(cand) >= topk: break
        refreshed = 0
        for (i,j) in cand:
            ii,jj = (i,j) if i<j else (j,i)
            t0 = time.perf_counter(); sim = self._pair_sim(ii, jj); dt = time.perf_counter()-t0
            prof.add_time("sim_update_s", dt); prof.inc("pairs_sim_recomputed")
            self.S[(ii,jj)] = sim
            heapq.heappush(self.heap, (-sim, ii, jj, self.versions[ii], self.versions[jj]))
            prof.inc("heap_pushes")
            self.valid_count += 1
            refreshed += 1
        return refreshed

