# Active set selection: class-balanced sampling for faster evaluation

@torch.no_grad()
def pick_active_indices_strict_equal(X, y, per_class: int):
    """
    Select strictly equal number of samples per class (class-balanced).

    Prioritizes ambiguous samples (small margin between top-2 predictions)
    to focus evaluation on difficult examples.

    Args:
        X: Input tensor
        y: Labels
        per_class: Number of samples to select per class

    Returns:
        Tensor of selected indices
    """
    classes = torch.unique(y).tolist()
    logits = []
    for i in range(0, X.size(0), T.BATCH_SIZE_EVAL):
        logits.append(FWD_EVAL(X[i:i+T.BATCH_SIZE_EVAL]).detach())
    L = torch.cat(logits, 0)
    top2 = torch.topk(L, k=2, dim=1).values
    margin = (top2[:,0] - top2[:,1]).abs()

    buckets = []
    for c in classes:
        idx_c = (y==c).nonzero(as_tuple=False).squeeze(1)
        order = torch.argsort(margin[idx_c])  # most ambiguous first
        take = min(per_class, idx_c.numel())
        buckets.append(idx_c[order[:take]])
    return torch.cat(buckets, 0).to(X.device)

@torch.no_grad()
def pick_active_indices_stratified(X, y, max_total=T.ACTIVE_MAX_SAMPLES, per_class=getattr(T, "ACTIVE_PER_CLASS", 512)):
    """
    Select samples using stratified sampling (proportional to class distribution).

    Falls back to strict equal sampling if T.ACTIVE_STRICT_EQUAL is enabled.
    Stratified mode is unused in v2 but retained for compatibility.

    Args:
        X: Input tensor
        y: Labels
        max_total: Maximum total samples
        per_class: Target samples per class

    Returns:
        Tensor of selected indices
    """
    if T.ACTIVE_STRICT_EQUAL:
        per = min(T.ACTIVE_STRICT_PER_CLASS, max_total // max(1, len(torch.unique(y))))
        return pick_active_indices_strict_equal(X, y, per)
    raise NotImplementedError("pick_active_indices_stratified is unused in this run")

