# Phase 4 Cell 3B.3 — EARLY-EXIT BENEFITS (WILSON CI)
# Lines: ~100 lines
# Dependencies: Cell 3A.2 (uses FWD_EVAL, get_conv_module, set_drop_mask)
# Exports: 4 constants + 4 functions
# Contents:
#   - Z_WILSON, MIN_USED_ACCEPT, MIN_USED_REJECT, MIN_FLIPS_FRAC (constants)
#   - _wilson_ci()
#   - benefit_pair_early() (Wilson CI early-exit)
#   - gate_decision_ratio_only() (placeholder)
#   - measure_channel_contributions() (placeholder)
# ═══════════════════════════════════════════════════════════════════════════

# Wilson Confidence Interval for early-exit benefit evaluation
# Uses statistical confidence intervals to stop evaluation early when we're
# confident about whether merging two channels will help or hurt accuracy

# Wilson CI thresholds for early exit:
# - Z_WILSON: Z-score for confidence level (2.0 ≈ 95% confidence)
# - MIN_USED_ACCEPT: Minimum samples before accepting a merge (confident it's good)
# - MIN_USED_REJECT: Minimum samples before rejecting a merge (confident it's bad)
# - MIN_FLIPS_FRAC: Minimum fraction of samples that must flip predictions
Z_WILSON        = T.Z_WILSON
MIN_USED_ACCEPT = T.MIN_USED_ACCEPT
MIN_USED_REJECT = T.MIN_USED_REJECT
MIN_FLIPS_FRAC  = T.MIN_FLIPS_FRAC

def _wilson_ci(phat: float, n: int, z: float = 2.0):
    """
    Compute Wilson Confidence Interval for a proportion.

    More accurate than normal approximation for small sample sizes.
    Returns lower and upper bounds of the confidence interval.

    Args:
        phat: Observed proportion (0 to 1)
        n: Sample size
        z: Z-score for desired confidence level (2.0 ≈ 95%)

    Returns:
        Tuple of (lower_bound, upper_bound)
    """
    if n <= 0: return 0.0, 1.0
    denom = 1.0 + (z*z)/n
    center = (phat + (z*z)/(2*n)) / denom
    margin = (z/denom) * math.sqrt(max(0.0, phat*(1.0-phat)/n + (z*z)/(4*n*n)))
    return center - margin, center + margin

@torch.no_grad()
def benefit_pair_early(i: int, j: int, S: Set[int],
                       conv_path: str, X: torch.Tensor, y: torch.Tensor,
                       batch_size: int, ratio_min: float, class_mask: Optional[torch.Tensor]=None):
    """
    Evaluate benefit of merging channels i and j using Wilson CI early-exit.

    Compares accuracy when dropping channel i vs dropping channel j. If one is
    clearly better (or they're similar enough), exits early without evaluating
    all samples. This saves computation during channel selection.

    Returns flip counts:
    - n01: Samples that flip from wrong→correct when switching from i to j
    - n10: Samples that flip from correct→wrong when switching from i to j
    - used: Total samples evaluated before early exit

    Early exit conditions:
    1. Accept merge: If ratio confidence interval lower bound ≥ ratio_min
       (confident channels are similar enough)
    2. Reject merge: If ratio confidence interval upper bound < ratio_min
       (confident one channel is clearly better)

    Args:
        i, j: Channel indices to compare
        S: Set of currently active (not dropped) channels
        conv_path: Path to conv layer
        X, y: Evaluation data
        batch_size: Batch size for evaluation
        ratio_min: Minimum acceptable benefit ratio
        class_mask: Optional mask for class-specific evaluation

    Returns:
        Tuple of (n01, n10, used) flip counts
    """
    if class_mask is not None:
        if class_mask.size(0) != X.size(0):
            raise ValueError(
                f"class_mask validation failed in benefit_pair_early(): "
                f"mask length ({class_mask.size(0)}) does not match X.size(0) ({X.size(0)}). "
                f"This may indicate stale mask after active-set refresh. "
                f"Ensure class_mask is refreshed when X is updated."
            )

    C = get_conv_module(model, conv_path).out_channels
    dropped_base = sorted(set(range(C)) - set(S))
    dropped_vec = torch.as_tensor(dropped_base, dtype=torch.long, device=X.device)

    n01 = n10 = used = 0
    z = Z_WILSON
    # Require minimum number of prediction flips to ensure meaningful comparison
    min_abs_flips = max(2, int(MIN_FLIPS_FRAC * (class_mask.sum().item() if class_mask is not None else X.size(0))))

    set_drop_mask(model, conv_path, dropped_vec)

    for s in range(0, X.size(0), batch_size):
        xb = X[s:s+batch_size]; yb = y[s:s+batch_size]
        if class_mask is not None:
            keep = class_mask[s:s+batch_size]
            xb = xb[keep]; yb = yb[keep]
            if xb.numel() == 0: continue

        set_drop_mask(model, conv_path, torch.cat([dropped_vec, torch.tensor([int(i)], device=xb.device)]))
        pi = FWD_EVAL(xb).argmax(1)
        set_drop_mask(model, conv_path, torch.cat([dropped_vec, torch.tensor([int(j)], device=xb.device)]))
        pj = FWD_EVAL(xb).argmax(1)

        Ai = (pi == yb); Aj = (pj == yb)
        n01 += int((~Ai &  Aj).sum().item())  # wrong→correct flips (i→j)
        n10 += int(( Ai & ~Aj).sum().item())  # correct→wrong flips (i→j)
        used += int(yb.numel())

        bi = n10/max(1,used); bj = n01/max(1,used)
        big, sml = (bi,bj) if bi>=bj else (bj,bi)
        rhat = (sml / big) if big > 0 else 0.0
        lo, hi = _wilson_ci(rhat, used, z=z)

        # Early exit: accept if confident channels are similar enough
        if (lo >= ratio_min) and (used >= MIN_USED_ACCEPT) and ((n01+n10) >= min_abs_flips): break
        # Early exit: reject if confident one channel is clearly better
        if (hi <  ratio_min) and (used >= MIN_USED_REJECT): break

    set_drop_mask(model, conv_path, dropped_vec)
    return n01, n10, used

