# Validation functions

def validate_linear_dimensions(lin1, H, W, C_new, conv_path):
    """
    Validates that Linear layer dimensions are compatible with feature map dimensions.
    Provides detailed diagnostics and recovery suggestions.

    Args:
        lin1: Linear layer to validate
        H: Height of feature maps
        W: Width of feature maps
        C_new: Number of channels after pruning
        conv_path: Path to conv layer for error messages

    Returns:
        tuple: (old_C, new_in_features, is_valid, error_msg)
            - old_C: Number of channels before pruning (or None if invalid)
            - new_in_features: Expected input features for new layer
            - is_valid: Boolean indicating if dimensions are valid
            - error_msg: Detailed error message if invalid, None otherwise
    """
    new_in_features = C_new * H * W

    # Pre-validation: Check spatial dimensions
    if H <= 0 or W <= 0:
        return None, new_in_features, False, (
            f"[validate_linear] Invalid spatial dimensions at {conv_path}\n"
            f"  H={H}, W={W} (both must be > 0)\n"
            f"  This indicates collapsed spatial dimensions"
        )

    # Pre-validation: Check alignment
    if lin1.in_features % (H * W) != 0:
        orphaned = lin1.in_features % (H * W)
        return None, new_in_features, False, (
            f"[validate_linear] Linear1 input alignment failed at {conv_path}\n"
            f"  lin1.in_features ({lin1.in_features}) not divisible by (H*W) ({H}*{W}={H*W})\n"
            f"  Orphaned columns: {orphaned}\n"
            f"  This indicates misalignment between feature map and Linear layer\n"
            f"  Recovery options:\n"
            f"    1. Run sync_all_channelgates() before pruning\n"
            f"    2. Rebuild Linear layer with correct dimensions\n"
            f"    3. Check model architecture for inconsistencies"
        )

    # Calculate old channel count
    old_C = lin1.in_features // (H * W)

    # Validate old_C is reasonable
    if old_C <= 0:
        return old_C, new_in_features, False, (
            f"[validate_linear] Invalid old channel count at {conv_path}\n"
            f"  old_C={old_C} (must be > 0)\n"
            f"  lin1.in_features={lin1.in_features}, H={H}, W={W}"
        )

    # All validations passed
    return old_C, new_in_features, True, None


def validate_snapshot(snapshot_state, context=""):
    """
    Validates snapshot before rollback.

    Args:
        snapshot_state: The snapshot state dict to validate
        context: Optional context string for error messages

    Raises:
        RuntimeError: If snapshot is invalid
    """
    if snapshot_state is None:
        raise RuntimeError(f"Snapshot is None - cannot rollback{' (' + context + ')' if context else ''}")
    if not isinstance(snapshot_state, dict):
        raise RuntimeError(f"Snapshot is not a dict - cannot rollback{' (' + context + ')' if context else ''}")
    if len(snapshot_state) == 0:
        raise RuntimeError(f"Snapshot is empty - cannot rollback{' (' + context + ')' if context else ''}")

    # Basic validation passed
    return True

def check_per_class_guard(per_before, per_after, N_per_class,
                          rel_max=0.04, N_min=300, err_budget_pct=0.005):
    """
    Check per-class guard with relative threshold for large classes and error budget for small classes.

    Handles class imbalance fairly by using different thresholds based on sample size:
    - Large classes: Relative drop threshold (prevents unfair penalties on weak classes)
    - Small classes: Error count budget (prevents noise from dominating)

    CLASS-AWARE ENHANCEMENTS:
    - Large classes (N >= N_min): Use relative drop threshold (e.g., 4%)
    - Small classes (N < N_min): Use error count budget (e.g., max 3 errors or 0.5% of N)
    - Fair to weak classes: 4% relative drop on 87% baseline = 3.5 points (vs 2% absolute = unfair)

    Args:
        per_before: Dict[class_id, accuracy_before]
        per_after: Dict[class_id, accuracy_after]
        N_per_class: Dict[class_id, sample_count]
        rel_max: Max relative drop for large classes (default 4%)
        N_min: Threshold for small-N fallback (default 300)
        err_budget_pct: Error budget as fraction of N for small classes (default 0.5%)

    Returns:
        fail: Boolean - True if any class violates guard
        worst_class: Class ID with max violation (or None)
        details: String with diagnostic info
    """
    fail = False
    worst_class = None
    max_violation = 0.0
    details_list = []

    for c in per_before.keys():
        acc_before = per_before[c]
        acc_after = per_after.get(c, 0.0)
        N_c = N_per_class.get(c, 0)

        if N_c < N_min:
            # Small-N: Use error budget (noise-proof)
            errors_added = (acc_before - acc_after) * N_c
            max_errors = max(3, err_budget_pct * N_c)
            violation = errors_added - max_errors

            if errors_added > max_errors:
                fail = True
                details_list.append(
                    f"Class {c}: {errors_added:.1f} errors > {max_errors:.1f} budget (N={N_c}, small-N mode)"
                )

            if violation > max_violation:
                max_violation = violation
                worst_class = c
        else:
            # Large-N: Use relative drop (fair to weak classes)
            drop_rel = (acc_before - acc_after) / max(acc_before, 1e-6)

            if drop_rel > rel_max:
                fail = True
                drop_abs = acc_before - acc_after
                details_list.append(
                    f"Class {c}: {drop_rel*100:.2f}% rel drop ({drop_abs*100:.2f} pts) > {rel_max*100:.2f}% max (N={N_c})"
                )

            if drop_rel > max_violation:
                max_violation = drop_rel
                worst_class = c

    details = "; ".join(details_list) if details_list else "All classes passed"
    return fail, worst_class, details

def eval_top1_and_perclass(model, loader, device):
    """
    Evaluate top-1 accuracy and per-class accuracy on a dataloader.

    Args:
        model: PyTorch model to evaluate
        loader: DataLoader with evaluation data
        device: Device to run evaluation on

    Returns:
        Tuple of (overall_accuracy, per_class_list)
        - overall_accuracy: Float accuracy across all samples
        - per_class_list: List of (class_id, accuracy, sample_count) tuples
    """
    model.eval()
    ys, yh = [], []
    pbar = tqdm(total=len(loader.dataset), desc="[Eval Top1]")
    for x,y in loader:
        x = x.to(device)
        out = FWD_EVAL(x)
        yh.append(out.argmax(1).detach().clone().cpu())
        ys.append(y.cpu())
        pbar.update(x.size(0))
    pbar.close()
    y = torch.cat(ys); yh = torch.cat(yh)
    acc = (y==yh).float().mean().item()
    classes = torch.unique(y).tolist()
    per=[]
    for c in classes:
        m = (y==c)
        per.append((c, (yh[m]==c).float().mean().item() if m.any() else float('nan'), int(m.sum())))
    return acc, sorted(per, key=lambda t: t[0])

@torch.no_grad()
def safe_eval_top1_and_perclass(model, loader, device):
    """
    Evaluate with automatic retry on OSError (handles dataloader multiprocessing issues).

    Falls back to single-sample evaluation if batch evaluation fails due to
    file descriptor or multiprocessing errors.

    Args:
        model: PyTorch model to evaluate
        loader: DataLoader with evaluation data
        device: Device to run evaluation on

    Returns:
        Tuple of (overall_accuracy, per_class_list)
    """
    try:
        return eval_top1_and_perclass(model, loader, device)
    except OSError as e:
        print(f"[eval] retry after OSError: {e}")
        _sync()
        ys, yh = [], []
        pbar = tqdm(total=len(loader.dataset), desc="[Eval Top1]")
        for i in range(len(loader.dataset)):
            x, y = loader.dataset[i]
            x = x.unsqueeze(0).to(device)
            out = FWD_EVAL(x)
            yh.append(out.argmax(1).detach().cpu())
            ys.append(torch.tensor([y]))
            pbar.update(1)
        pbar.close()
        y = torch.cat(ys); yh = torch.cat(yh)
        acc = (y==yh).float().mean().item()
        classes = torch.unique(y).tolist()
        per=[]
        for c in classes:
            m = (y==c)
            per.append((c, (yh[m]==c).float().mean().item() if m.any() else float('nan'), int(m.sum())))
        return acc, sorted(per, key=lambda t: t[0])


@torch.no_grad()
def quick_acc_and_perclass_on_cache(X_eval, y_eval, unique_mask, bs):
    """
    Compute both overall accuracy and per-class accuracy in a single pass (OPTIMIZATION).

    This merged function eliminates redundant forward passes by computing both metrics
    in one loop, reducing evaluation time by ~50% during guard checks.

    Args:
        X_eval: Evaluation features tensor
        y_eval: Evaluation labels tensor
        unique_mask: Boolean mask for unique samples (CLASS-AWARE FIX)
        bs: Batch size for evaluation

    Returns:
        Tuple[float, Dict[int, float], Dict[int, int]]:
            - overall_accuracy: Overall accuracy as float
            - per_class_acc: Dict[class_id -> accuracy]
            - N_per_class: Dict[class_id -> sample_count]

    Performance: Saves ~210s per 5-round run by eliminating duplicate forward passes.
    """
    model.eval()
    device = next(model.parameters()).device

    # # Use only unique samples for eval
    # X_unique = X_eval[unique_mask]
    # y_unique = y_eval[unique_mask]

    # Use only unique samples for eval
    # Avoid boolean indexing on CUDA; use integer indices instead.
    if unique_mask.dtype != torch.bool:
        raise TypeError(f"unique_mask must be bool, got {unique_mask.dtype}")
    if unique_mask.ndim != 1:
        raise ValueError(f"unique_mask must be 1-D, got shape {tuple(unique_mask.shape)}")
    if unique_mask.shape[0] != X_eval.shape[0]:
        raise ValueError(f"unique_mask length {unique_mask.shape[0]} != X_eval {X_eval.shape[0]}")

    # Build index vector of unique positions
    # idx = unique_mask.nonzero(as_tuple=True)[0]  # 1-D LongTensor

    mask_cpu = unique_mask.detach().to("cpu")
    idx = mask_cpu.nonzero(as_tuple=True)[0]  # 1-D LongTensor on CPU


    X_unique = X_eval.index_select(0, idx.to(X_eval.device))
    y_unique = y_eval.index_select(0, idx.to(y_eval.device))


    n = X_unique.size(0)
    if n == 0:
        return 0.0, {}, {}

    # Single pass: collect predictions and compute overall accuracy
    correct = 0
    yh_batches, ys_batches = [], []

    for i in range(0, n, bs):
        xb = X_unique[i:i+bs].to(device, non_blocking=True)
        yb = y_unique[i:i+bs].to(device, non_blocking=True)

        # Single forward pass (reused for both metrics)
        pred = FWD_EVAL(xb).argmax(1)

        # Accumulate overall accuracy
        correct += int((pred == yb).sum())

        # Store for per-class computation
        yh_batches.append(pred.detach().cpu())
        ys_batches.append(yb.detach().cpu())

    # Overall accuracy
    overall_acc = correct / max(1, n)

    # Per-class accuracy computation
    yh = torch.cat(yh_batches)
    y = torch.cat(ys_batches)

    per_class_acc = {}
    N_per_class = {}
    for c in torch.unique(y).tolist():
        m = (y == c)
        N_per_class[c] = m.sum().item()
        if m.any():
            per_class_acc[c] = float((yh[m] == c).float().mean().item())

    return overall_acc, per_class_acc, N_per_class


def quick_acc_on_cache(X_eval, y_eval, unique_mask, bs):
    """
    Compute accuracy on unique samples only (CLASS-AWARE FIX).

    DEPRECATED: Use quick_acc_and_perclass_on_cache() for better performance.
    This function is kept for backwards compatibility only.

    Duplicates are excluded to avoid inflating accuracy metrics.
    """
    model.eval()
    device = next(model.parameters()).device

    # Use only unique samples for eval
    X_unique = X_eval[unique_mask]
    y_unique = y_eval[unique_mask]

    n = X_unique.size(0)
    correct = 0
    for i in range(0, n, bs):
        xb = X_unique[i:i+bs].to(device, non_blocking=True)
        yb = y_unique[i:i+bs].to(device, non_blocking=True)
        pred = FWD_EVAL(xb).argmax(1)
        correct += int((pred == yb).sum())
    return correct / max(1, n)

@torch.no_grad()
def quick_perclass_on_cache(X_eval, y_eval, unique_mask, bs):
    """
    Compute per-class accuracy on unique samples only (CLASS-AWARE FIX).

    DEPRECATED: Use quick_acc_and_perclass_on_cache() for better performance.
    This function is kept for backwards compatibility only.

    Returns both per-class accuracy and sample counts for guard checks.
    """
    model.eval()
    device = next(model.parameters()).device

    # Use only unique samples for eval
    X_unique = X_eval[unique_mask]
    y_unique = y_eval[unique_mask]

    n = X_unique.size(0)
    yh, ys = [], []
    for i in range(0, n, bs):
        xb = X_unique[i:i+bs].to(device, non_blocking=True)
        yb = y_unique[i:i+bs].to(device, non_blocking=True)
        yh.append(FWD_EVAL(xb).argmax(1).detach().cpu())
        ys.append(yb.detach().cpu())

    yh = torch.cat(yh)
    y = torch.cat(ys)

    out = {}
    N_per_class = {}
    for c in torch.unique(y).tolist():
        m = (y == c)
        N_per_class[c] = m.sum().item()
        if m.any():
            out[c] = float((yh[m] == c).float().mean().item())

    return out, N_per_class

# Configuration constants for BN recalibration, evaluation, and rollback
# BN recalibration controls:
# - BN_REFRESH_EVERY_MERGES: How often to recalibrate BN statistics
# - BN_MINI_ITERS, BN_ROUND_ITERS: Iteration counts for BN updates
# - BN_MOMENTUM: Momentum for BN running statistics
# Evaluation controls:
# - MID_EVAL_DRIFT_THRESH: Threshold for detecting accuracy drift
# - MID_EVAL_SAMPLE: Sample size for mid-round evaluation
# Rollback controls:
# - ROLLBACK_MAX_UNDO: Maximum rollback steps
# - ROLLBACK_ACC_DROP, ROLLBACK_PERCLASS_DROP: Accuracy drop thresholds
BN_REFRESH_EVERY_MERGES = T.BN_REFRESH_EVERY_MERGES
BN_MINI_ITERS           = T.BN_MINI_ITERS
BN_ROUND_ITERS          = T.BN_ROUND_ITERS
MID_EVAL_DRIFT_THRESH   = T.MID_EVAL_DRIFT_THRESH
MID_EVAL_SAMPLE         = T.MID_EVAL_SAMPLE
BN_MAX_MINI_PER_LAYER   = T.BN_MAX_MINI_PER_LAYER
BN_MOMENTUM             = T.BN_MOMENTUM

TAIL_LAST_FRAC         = T.TAIL_LAST_FRAC
RATIO_MIN_TAIL_DELTA   = T.RATIO_MIN_TAIL_DELTA
IC_Z_TAIL_DELTA        = T.IC_Z_TAIL_DELTA
IC_Z_MIN_FLOOR         = T.IC_Z_MIN_FLOOR
ROLLBACK_MAX_UNDO      = T.ROLLBACK_MAX_UNDO
ROLLBACK_ACC_DROP      = T.ROLLBACK_ACC_DROP
ROLLBACK_PERCLASS_DROP = T.ROLLBACK_PERCLASS_DROP

@torch.no_grad()
def build_eval_and_bn_caches(X_full, y_full, n_total, n_hard_pct=0.25, seed=None):
    """
    Builds a stratified, class-balanced cache with per-class floor and duplicate tracking.

    Handles class imbalance by ensuring each class gets fair representation:
    - Per-class floor prevents minority class collapse
    - Duplicate tracking allows duplicates for scoring but uses unique samples for eval
    - Quota redistribution gives unused quota from small classes to larger classes

    CLASS-AWARE ENHANCEMENTS:
    - Per-class floor (20% of quota or 200 samples minimum) prevents minority class collapse
    - Duplicate tracking: duplicates OK for scoring, but eval uses unique samples only
    - Quota redistribution: unused quota from small classes goes to larger classes

    Returns:
        X_cache: Tensor with possible duplicates (for scoring)
        y_cache: Labels with possible duplicates
        unique_mask: Boolean mask for unique samples (for eval)
        drawn_per_class: Dict of samples drawn per class (with duplicates)
        unique_per_class: Dict of unique samples per class (for eval)
    """
    if seed is None:
        seed = CONFIG.get('SEED', 42)
    torch.manual_seed(seed)

    if not isinstance(X_full, torch.Tensor):
        raise TypeError(f"X_full must be a torch.Tensor, got {type(X_full)}")
    if not isinstance(y_full, torch.Tensor):
        raise TypeError(f"y_full must be a torch.Tensor, got {type(y_full)}")
    if X_full.numel() == 0:
        raise ValueError("X_full cannot be empty")
    if y_full.numel() == 0:
        raise ValueError("y_full cannot be empty")
    if X_full.size(0) != y_full.size(0):
        raise ValueError(f"X_full and y_full must have same batch size: {X_full.size(0)} != {y_full.size(0)}")
    if X_full.ndim < 2:
        raise ValueError(f"X_full must have at least 2 dimensions, got {X_full.ndim}")

    validate_numeric(n_total, "n_total", min_val=1)
    validate_numeric(n_hard_pct, "n_hard_pct", min_val=0.0, max_val=1.0)

    n_total = min(n_total, X_full.size(0))
    n_hard_pct = float(max(0.0, min(1.0, n_hard_pct)))

    device = next(model.parameters()).device
    X_full = X_full.to(device)
    y_full = y_full.to(device)

    if X_full.device != device:
        raise RuntimeError(f"X_full device mismatch: expected {device}, got {X_full.device}")
    if y_full.device != device:
        raise RuntimeError(f"y_full device mismatch: expected {device}, got {y_full.device}")

    # Get classes
    classes = torch.unique(y_full)
    if classes.device != device:
        classes = classes.to(device)
    classes = classes.tolist()
    C = len(classes)

    if C < 2:
        print(f"⚠️ [Cache] Single-class dataset detected (classes={classes}). "
              f"Falling back to random sampling (no stratification).")
        indices = torch.randperm(X_full.size(0), device=device)[:n_total]
        X_cache = X_full[indices]
        y_cache = y_full[indices]
        unique_mask = torch.ones(len(X_cache), dtype=torch.bool, device=device)
        drawn_per_class = {classes[0]: len(X_cache)}
        unique_per_class = {classes[0]: len(X_cache)}
        return X_cache, y_cache, unique_mask, drawn_per_class, unique_per_class

    target_per_class = n_total // C
    floor_min = max(int(0.2 * n_total / C), 200)

    print(f"[Cache] Building {n_total}-sample stratified active set (hard_pct={n_hard_pct})...")
    print(f"  Target per class: {target_per_class}, Floor: {floor_min}")

    # Step 1: Compute hardness scores (entropy) for all samples
    logits = []
    bs = T.BATCH_SIZE_EVAL
    for i in range(0, X_full.size(0), bs):
        logits.append(FWD_EVAL(X_full[i:i+bs]).detach())
    L = torch.cat(logits, 0)

    #  Monitor GPU utilization
    check_gpu_utilization("Cache Building", warn_threshold=0.90)

    probs = F.softmax(L, dim=1)
    entropy = -(probs * torch.log(probs + 1e-9)).sum(dim=1)  # Higher = harder

    # --- 2. step 1: Determine take per class with floor ---
    take_per_class = {}
    available_per_class = {}

    for c in classes:
        class_mask = (y_full == c)
        available = class_mask.sum().item()
        available_per_class[c] = available

        take = min(target_per_class, available)
        if take < floor_min:
            print(f"⚠️ Class {c}: {available} available < floor {floor_min}, using all")
            take = available
        take_per_class[c] = take

    # --- 3. step 2: Redistribute unused quota ---
    total_taken = sum(take_per_class.values())
    if total_taken < n_total:
        print(f"  Redistributing {n_total - total_taken} unused samples...")
        for c in classes:
            if available_per_class[c] > take_per_class[c]:
                extra = min(n_total - total_taken, available_per_class[c] - take_per_class[c])
                take_per_class[c] += extra
                total_taken += extra
                if total_taken >= n_total:
                    break

    # --- 4. step 3: Sample with duplicate tracking ---
    X_list, y_list, unique_flags = [], [], []
    drawn_per_class = {}
    unique_per_class = {}

    for c in classes:
        class_mask = (y_full == c)
        class_indices = class_mask.nonzero(as_tuple=False).squeeze(1)
        class_entropy = entropy[class_mask]

        n_take = take_per_class[c]
        n_available = len(class_indices)

        # Split into hard and random
        n_hard = int(n_take * n_hard_pct)
        n_rand = n_take - n_hard

        # Sort by hardness
        hard_order = torch.argsort(class_entropy, descending=True)

        if n_take <= n_available:
            # No duplicates needed
            hard_indices = class_indices[hard_order[:n_hard]]
            remaining_indices = class_indices[hard_order[n_hard:]]
            rand_indices = remaining_indices[torch.randperm(remaining_indices.numel(), device=device)[:n_rand]]

            selected_indices = torch.cat([hard_indices, rand_indices])
            X_list.append(X_full[selected_indices])
            y_list.append(y_full[selected_indices])
            unique_flags.extend([True] * n_take)

            drawn_per_class[c] = n_take
            unique_per_class[c] = n_take
        else:
            # Need duplicates - sample with replacement
            print(f"⚠️ Class {c}: Need {n_take} samples but only {n_available} available (will use duplicates)")

            # Sample with replacement
            sample_indices = torch.randint(0, n_available, (n_take,), device=device)
            selected_indices = class_indices[sample_indices]

            X_list.append(X_full[selected_indices])
            y_list.append(y_full[selected_indices])

            # Track unique samples
            seen = set()
            for idx in sample_indices.tolist():
                unique_flags.append(idx not in seen)
                seen.add(idx)

            drawn_per_class[c] = n_take
            unique_per_class[c] = len(seen)
            print(f"  Class {c}: Drew {n_take} samples (only {len(seen)} unique)")

    # --- 5. Concatenate and shuffle ---
    X_cache = torch.cat(X_list, 0)
    y_cache = torch.cat(y_list, 0)
    unique_mask = torch.tensor(unique_flags, dtype=torch.bool, device=device)

    # Shuffle while preserving unique_mask alignment
    shuffle_idx = torch.randperm(len(X_cache), device=device)
    X_cache = X_cache[shuffle_idx]
    y_cache = y_cache[shuffle_idx]
    unique_mask = unique_mask[shuffle_idx]

    # --- 6. Log composition ---
    total_unique = unique_mask.sum().item()
    print(f"[Cache] Stratified active set created: {len(X_cache)} samples ({total_unique} unique)")
    print(f"  Drawn per class: {drawn_per_class}")
    print(f"  Unique per class: {unique_per_class}")
    if total_unique < len(X_cache):
        print(f"  ⚠️ {len(X_cache) - total_unique} duplicate samples (OK for scoring, excluded from eval)")

    #  Final validation
    if X_cache.numel() == 0:
        raise RuntimeError("Cache building produced empty X_cache")
    if y_cache.numel() == 0:
        raise RuntimeError("Cache building produced empty y_cache")
    if X_cache.size(0) != y_cache.size(0):
        raise RuntimeError(f"Cache size mismatch: X_cache={X_cache.size(0)}, y_cache={y_cache.size(0)}")
    if X_cache.device != device:
        raise RuntimeError(f"X_cache device mismatch: expected {device}, got {X_cache.device}")
    if y_cache.device != device:
        raise RuntimeError(f"y_cache device mismatch: expected {device}, got {y_cache.device}")
    if torch.isnan(X_cache).any():
        raise RuntimeError("X_cache contains NaN values")
    if torch.isinf(X_cache).any():
        raise RuntimeError("X_cache contains Inf values")

    return X_cache, y_cache, unique_mask, drawn_per_class, unique_per_class
# --- END  ---

@torch.no_grad()
def _taylor_scores(X, y, layer_specs):
    """
    Compute Taylor importance scores for each filter.

    Algorithm:
    1. For each class separately, compute gradient-weighted activations
    2. Score = |activation * gradient| averaged over spatial dimensions
    3. Higher score = more important filter (larger impact on loss)
    4. Final score = max across classes (worst-case importance)

    This measures first-order sensitivity: how much does removing a filter
    affect the loss? Filters with low Taylor scores can be pruned safely.
    """
    device = X.device
    model.eval()

    # Configuration - batch size and mixed precision
    # Smaller batch size reduces memory, AMP speeds up computation
    bs = int(getattr(T, "TAYLOR_BATCH_SIZE", getattr(T, "BATCH_SIZE_EVAL", 256)))
    use_amp = bool(getattr(T, "TAYLOR_USE_AMP", torch.cuda.is_available()))
    #  Layer chunking - process N layers at a time to limit memory
    # 0 = all layers at once, >0 = chunk to reduce peak memory
    layers_per_pass = int(getattr(T, "TAYLOR_LAYERS_PER_PASS", 0))

    #  Gradient checkpointing - trade compute for memory
    # Reduces peak memory by ~30% at cost of ~20% slower backward pass
    # Automatically enabled when GPU memory is low (<8GB available)
    use_checkpointing = bool(getattr(T, "TAYLOR_USE_CHECKPOINTING", False))
    if torch.cuda.is_available() and not use_checkpointing:
        # Auto-enable if low memory
        free_memory_gb = torch.cuda.get_device_properties(0).total_memory / (1024**3)
        if free_memory_gb < 8.0:
            use_checkpointing = True
            print(f"  [Taylor] Auto-enabling gradient checkpointing (GPU memory: {free_memory_gb:.1f}GB)")

    #  Limit number of batches to cap computation time
    #  If T.TAYLOR_MAX_BATCHES is None, cover the full active set.
    max_batches_cfg = getattr(T, "TAYLOR_MAX_BATCHES", None)
    if max_batches_cfg is None:
        max_batches = int(math.ceil(X.size(0) / max(1, bs)))
    else:
        max_batches = max(1, int(max_batches_cfg))

    #  Refactored hook state - use explicit result storage instead of closure mutation
    # This improves thread safety and makes the data flow more explicit
    class TaylorScoreAccumulator:
        """Accumulates Taylor scores with explicit state management"""
        def __init__(self, layer_specs):
            self.scores_c0 = {spec["conv"]: None for spec in layer_specs}
            self.counts_c0 = {spec["conv"]: 0    for spec in layer_specs}
            self.scores_c1 = {spec["conv"]: None for spec in layer_specs}
            self.counts_c1 = {spec["conv"]: 0    for spec in layer_specs}
            self.activations = {}  # Temporary storage for forward pass

        def accumulate(self, key, class_id, contrib):
            """Thread-safe accumulation of contributions"""
            if class_id == 0:
                if self.scores_c0[key] is None:
                    self.scores_c0[key] = contrib
                else:
                    self.scores_c0[key] += contrib
                self.counts_c0[key] += 1
            else:
                if self.scores_c1[key] is None:
                    self.scores_c1[key] = contrib
                else:
                    self.scores_c1[key] += contrib
                self.counts_c1[key] += 1

        def clear_activations(self):
            """Clear temporary activation storage"""
            self.activations.clear()

    accumulator = TaylorScoreAccumulator(layer_specs)

    def make_hooks(key, class_id):
        """
         Refactored hook creation with explicit state management.

        Forward hook: Saves activations in accumulator
        Backward hook: Computes contribution and stores via accumulator

        Benefits:
        - No closure-captured mutable state
        - Explicit data flow
        - Better thread safety
        - Easier to debug and test
        """
        save_key = f"{key}_{class_id}"

        def fwd_hook(_, __, out):
            # Save activation in accumulator's storage
            accumulator.activations[save_key] = out
            return out

        def bwd_hook(_, grad_input, grad_output):
            if save_key not in accumulator.activations:
                return

            # Compute Taylor importance: |A * dA|
            A = accumulator.activations[save_key]
            dA = grad_output[0]
            contrib = (A * dA).abs().mean(dim=(0, 2, 3)).detach().float()

            # Accumulate via explicit method call
            accumulator.accumulate(key, class_id, contrib)

            # Clean up activation
            del accumulator.activations[save_key]

        return fwd_hook, bwd_hook

    crit = criterion
    Xs, ys = _maybe_slice_for_scoring(X, y)  # keep your existing sampler

    # set up AMP context managers
    _amp_ctx = (torch.amp.autocast(device_type="cuda") if (use_amp and torch.cuda.is_available())
                else torch.autocast("cpu", enabled=False))

    #  Checkpointing wrapper for forward pass
    def checkpointed_forward(x):
        """Wrapper that optionally uses gradient checkpointing"""
        if use_checkpointing:
            # Use checkpointing to save memory during backward pass
            return torch.utils.checkpoint.checkpoint(_raw_forward, x, use_reentrant=False)
        else:
            return _raw_forward(x)



    # layer chunks to limit simultaneous hooks (0 => one pass with all layers)
    layer_chunks = list(_chunked(layer_specs, layers_per_pass))

    with _temporarily_uncompiled_eval(), _noninplace_activations(model), torch.enable_grad():
        n_batches = min(max_batches, math.ceil(Xs.size(0) / max(1, bs)))
        for b in range(n_batches):
            i0 = b * bs
            i1 = min((b + 1) * bs, Xs.size(0))
            if i0 >= i1:
                break

            xb_full = Xs[i0:i1].to(device, non_blocking=True)
            yb_full = ys[i0:i1].to(device, non_blocking=True)

            # # class-wise splits
            # xb_c0 = xb_full[yb_full == 0]; yb_c0 = yb_full[yb_full == 0]
            # xb_c1 = xb_full[yb_full == 1]; yb_c1 = yb_full[yb_full == 1]

            # class-wise splits — sanity checks
            assert isinstance(xb_full, torch.Tensor), \
                f"xb_full must be tensor, got {type(xb_full)}"
            assert isinstance(yb_full, torch.Tensor), \
                f"yb_full must be tensor, got {type(yb_full)}"

            assert xb_full.device == yb_full.device, \
                f"Device mismatch in Taylor batch: X={xb_full.device}, y={yb_full.device}"

            assert xb_full.ndim >= 2, \
                f"xb_full must have batch dimension, got shape {tuple(xb_full.shape)}"
            assert yb_full.ndim == 1, \
                f"yb_full must be 1-D, got shape {tuple(yb_full.shape)}"

            assert xb_full.shape[0] == yb_full.shape[0], \
                f"Taylor batch size mismatch: X={xb_full.shape[0]} vs y={yb_full.shape[0]}"

            # labels should be 0/1 for binary CIFAR runs
            y_min = int(yb_full.min().item())
            y_max = int(yb_full.max().item())
            assert y_min >= 0, f"yb_full contains negative labels, min={y_min}"
            assert y_max <= 1, f"yb_full contains labels >1, max={y_max}"

            # # class-wise splits
            # xb_c0 = xb_full[yb_full == 0]; yb_c0 = yb_full[yb_full == 0]
            # xb_c1 = xb_full[yb_full == 1]; yb_c1 = yb_full[yb_full == 1]

            # class-wise splits — use integer indices instead of boolean indexing
            # idx0 = (yb_full == 0).nonzero(as_tuple=True)[0]
            # idx1 = (yb_full == 1).nonzero(as_tuple=True)[0]

            y_cpu = yb_full.detach().to("cpu")
            idx0 = (y_cpu == 0).nonzero(as_tuple=True)[0]  # on CPU
            idx1 = (y_cpu == 1).nonzero(as_tuple=True)[0]  # on CPU

            idx0 = idx0.to(device)
            idx1 = idx1.to(device)

            xb_c0 = xb_full.index_select(0, idx0) if idx0.numel() > 0 else xb_full.new_empty((0,) + xb_full.shape[1:])
            yb_c0 = yb_full.index_select(0, idx0) if idx0.numel() > 0 else yb_full.new_empty((0,), dtype=yb_full.dtype)

            xb_c1 = xb_full.index_select(0, idx1) if idx1.numel() > 0 else xb_full.new_empty((0,) + xb_full.shape[1:])
            yb_c1 = yb_full.index_select(0, idx1) if idx1.numel() > 0 else yb_full.new_empty((0,), dtype=yb_full.dtype)


            # process per layer-chunk so we don't hold hooks for all layers at once
            for chunk in layer_chunks:
                # ---- class 0 pass ----
                if xb_c0.numel() > 0:
                    handles_c0 = []
                    try:
                        for spec in chunk:
                            bn = get_module(model, spec["bn"])
                            fh, bh = make_hooks(spec["conv"], class_id=0)
                            handles_c0.append(bn.register_forward_hook(fh))
                            handles_c0.append(bn.register_full_backward_hook(bh))
                        model.zero_grad(set_to_none=True)
                        with _amp_ctx:
                            #  Use checkpointed forward to reduce memory
                            logits_c0 = checkpointed_forward(xb_c0)
                            loss_c0   = crit(logits_c0, yb_c0)
                        loss_c0.backward()  # NEW: no retain_graph
                    finally:
                        for h in handles_c0: h.remove()
                        #  Clear activations via accumulator
                        accumulator.clear_activations()
                        #  Explicit tensor deletion
                        try:
                            del logits_c0, loss_c0
                        except Exception:
                            pass
                        # Removed empty_cache() - causes unnecessary GPU sync and slowdown

                # ---- class 1 pass ----
                if xb_c1.numel() > 0:
                    handles_c1 = []
                    try:
                        for spec in chunk:
                            bn = get_module(model, spec["bn"])
                            fh, bh = make_hooks(spec["conv"], class_id=1)
                            handles_c1.append(bn.register_forward_hook(fh))
                            handles_c1.append(bn.register_full_backward_hook(bh))
                        model.zero_grad(set_to_none=True)
                        with _amp_ctx:
                            #  Use checkpointed forward to reduce memory
                            logits_c1 = checkpointed_forward(xb_c1)
                            loss_c1   = crit(logits_c1, yb_c1)
                        loss_c1.backward()
                    finally:
                        for h in handles_c1: h.remove()
                        #  Clear activations via accumulator
                        accumulator.clear_activations()
                        #  Explicit tensor deletion
                        try:
                            del logits_c1, loss_c1
                        except Exception:
                            pass
                        #  Removed empty_cache() - causes unnecessary GPU sync and slowdown

                _clear_cuda()  # free graphs promptly

            #  Delete batch tensors after processing
            try:
                del xb_full, yb_full, xb_c0, yb_c0, xb_c1, yb_c1
            except Exception:
                pass

    #  Optimized score fusion - batch GPU operations, single .cpu() call
    # Keep tensors on GPU during computation, move to CPU only at the end
    out = {}
    for spec in layer_specs:
        key = spec["conv"]
        C = get_conv_module(model, key).out_channels

        # Get scores from accumulator - keep on GPU
        if accumulator.counts_c0[key] > 0:
            s0 = accumulator.scores_c0[key] / max(1, accumulator.counts_c0[key])
        else:
            s0 = torch.zeros(C, device=device if torch.cuda.is_available() else 'cpu')

        if accumulator.counts_c1[key] > 0:
            s1 = accumulator.scores_c1[key] / max(1, accumulator.counts_c1[key])
        else:
            s1 = torch.zeros(C, device=device if torch.cuda.is_available() else 'cpu')

        # Take max across classes on GPU, then single transfer to CPU
        out[key] = torch.max(s0, s1).cpu()

    #  Monitor GPU utilization during Taylor scoring
    check_gpu_utilization("Taylor Scoring", warn_threshold=0.90)

    #  Report checkpointing status
    if use_checkpointing:
        print(f"  [Taylor] Gradient checkpointing enabled (expected: ~30% memory reduction)")

    #  Report layer chunking status
    if layers_per_pass > 0:
        num_chunks = len(layer_chunks)
        print(f"  [Taylor] Layer chunking enabled: {layers_per_pass} layers/pass, {num_chunks} chunks (expected: ~40-50% memory reduction)")

    return out
# --- END  Taylor scorer ---

@torch.no_grad()
def collect_hrank_streaming(conv_path, bn_path, max_batches=CONFIG.get("HRANK_MAX_BATCHES", 8)):
    bn = get_module(model, bn_path)
    acc = None; cnt = 0; saved = {"A": None}
    def fhook(_, __, out):
        saved["A"] = _downsample_spatial(out.detach())
        return out
    h = bn.register_forward_hook(fhook)
    try:
        n_batches = 0
        for xb, _ in sequential_loader:
            xb = xb.to(DEVICE, non_blocking=True)
            _ = FWD_EVAL(xb)  # compiled ok (no grad)
            A = saved["A"]
            if A is not None:
                N, C, H, W = A.shape
                Ac = A.view(N, C, -1)
                fro = torch.sqrt(torch.clamp((Ac*Ac).sum(dim=(0,2)), min=1e-12))  # [C]
                acc = fro if acc is None else (acc + fro)
                cnt += 1
            n_batches += 1
            if n_batches >= max_batches: break
            saved["A"] = None; _clear_cuda()
    finally:
        h.remove(); saved["A"] = None; _clear_cuda()
    if acc is None or cnt == 0:
        C = get_conv_module(model, conv_path).out_channels
        return torch.full((C,), 1e-8)
    return (acc / cnt).cpu()

def _bn_gamma_scores(layer_specs):
    out = {}
    for spec in layer_specs:
        bn = get_module(model, spec["bn"])
        gamma = bn.weight.detach().abs().float().cpu()
        out[spec["conv"]] = gamma
    return out

# --- START [Global 2.2]  Per-layer Normalization ---
def _normalize_for_pruning(d: Dict[str, torch.Tensor]) -> Dict[str, torch.Tensor]:
    """
    Normalizes scores *per-layer* to [0, 1] where 0 is least important.
    """
    out = {}
    for k, v in d.items():
        if v is None or v.numel() == 0:
            continue
        t = v.float()
        # Per-layer min/max scaling
        t_min = t.min()
        t_max = t.max()
        if (t_max - t_min).abs() < 1e-9:
            out[k] = torch.zeros_like(t) # All same value
        else:
            out[k] = (t - t_min) / (t_max - t_min) # Scale to [0, 1]
    return out
# --- END [Global 2.2]  ---

def _normalize_global_for_pruning(d: Dict[str, torch.Tensor]) -> Dict[str, torch.Tensor]:
    """
    Normalizes scores *globally* across all layers to [0, 1].

    This preserves cross-layer comparability for the global ranking step,
    unlike purely per-layer scaling which forces each layer into its own
    [0,1] range.
    """
    out: Dict[str, torch.Tensor] = {}

    # Collect all values across layers
    flats = []
    for v in d.values():
        if v is None or v.numel() == 0:
            continue
        flats.append(v.float().view(-1))

    if not flats:
        return out

    all_vals = torch.cat(flats, dim=0)
    t_min = all_vals.min()
    t_max = all_vals.max()
    if (t_max - t_min).abs() < 1e-9:
        # Degenerate case: all scores identical → treat all as least-important (0)
        for k, v in d.items():
            if v is None or v.numel() == 0:
                continue
            out[k] = torch.zeros_like(v, dtype=torch.float32)
        return out

    # Global min-max scaling to [0,1]
    for k, v in d.items():
        if v is None or v.numel() == 0:
            continue
        t = v.float()
        out[k] = (t - t_min) / (t_max - t_min)
    return out

#  STEP-4: INSIDE-LAYER RANKING — ENTRY
@torch.no_grad()
def _collect_act_rms_streaming(conv_path: str,
                               bn_path: Optional[str] = None,
                               max_batches: int = None,
                               max_hw: int = None) -> torch.Tensor:
    """
    Stream per-channel activation RMS from a layer's own output.

    - If bn_path is given, we hook the BatchNorm module at `bn_path`.
    - Otherwise, we hook the conv (or its Sequential container) at `conv_path`.

    This keeps the ActRMS vector length equal to conv.out_channels for every
    layer (CNN and VGG), even when blocks contain multiple convs with shared
    pools.
    """
    if max_batches is None:
        max_batches = int(getattr(T, "ILR_MAX_BATCHES", 6))
    if max_hw is None:
        max_hw = int(getattr(T, "ILR_MAX_HW", 4096))

    # Resolve module to hook: prefer BN, fall back to conv container.
    try:
        hook_module = get_module(model, bn_path) if bn_path else get_module(model, conv_path)
    except Exception:
        # If resolution fails, fall back to an epsilon vector sized to conv out_channels.
        C_fallback = get_conv_module(model, conv_path).out_channels
        return torch.full((C_fallback,), 1e-8)

    saved = {"A": None}

    def fhook(_, __, out):
        saved["A"] = _downsample_spatial(out, max_hw=max_hw)
        return out

    h = hook_module.register_forward_hook(fhook)

    try:
        acc = None
        cnt = 0
        n_batches = 0
        for xb, _ in sequential_loader:
            xb = xb.to(DEVICE, non_blocking=True)
            _ = FWD_EVAL(xb)  # compiled ok (no grad)
            A = saved["A"]
            saved["A"] = None
            if A is None:
                n_batches += 1
                if n_batches >= max_batches:
                    break
                continue

            # A: [N, C, H, W] → RMS over (N, H, W)
            N, C, H, W = A.shape
            Ar = A.view(N, C, -1)
            rms = torch.sqrt(torch.clamp((Ar * Ar).mean(dim=(0, 2)), min=1e-12))  # [C]
            acc = rms if acc is None else (acc + rms)
            cnt += 1
            n_batches += 1
            if n_batches >= max_batches:
                break

        if acc is None or cnt == 0:
            # Fall back to a tiny epsilon so the layer is “uninformative” but safe.
            C = get_conv_module(model, conv_path).out_channels
            return torch.full((C,), 1e-8)

        return (acc / cnt).cpu()
    finally:
        h.remove()
        saved["A"] = None

@torch.no_grad()
def _ilr_scores(layer_specs,
                use_hrank: bool = True,
                target_layers: Optional[Set[str]] = None) -> Dict[str, torch.Tensor]:
    """
    Inside-layer per-channel IMPORTANCE in [0,1] per-layer:
      - act_rms: RMS of pooled activations (post-ReLU, post-pool)
      - bn_gamma: |BN.gamma|
      - hrank:    Frobenius (already no-grad)
    Output dict maps conv_path -> tensor[C] with 0=least important.
    """
    W = dict(getattr(T, "ILR_WEIGHTS", {"act_rms":0.6,"bn_gamma":0.4,"hrank":0.2}))
    use = dict(getattr(T, "ILR_COMPONENTS", {"act_rms": True, "bn_gamma": True, "hrank": True}))
    comp: Dict[str, Dict[str, torch.Tensor]] = {}

    # Restrict ILR computation to a subset of layers when requested.
    if target_layers is not None:
        target_layers = set(target_layers)
        specs = [s for s in layer_specs if s["conv"] in target_layers]
    else:
        specs = list(layer_specs)

    # act_rms
    if use.get("act_rms", True):
        comp["act_rms"] = {}
        for spec in specs:
            comp["act_rms"][spec["conv"]] = _collect_act_rms_streaming(
                spec["conv"],
                spec.get("bn"),
                max_batches=int(getattr(T, "ILR_MAX_BATCHES", 6)),
                max_hw=int(getattr(T, "ILR_MAX_HW", 4096)),
            )

    # bn_gamma
    if use.get("bn_gamma", True):
        comp["bn_gamma"] = _bn_gamma_scores(specs)

    # hrank (Frobenius) reuse existing streaming impl
    if use.get("hrank", True) and use_hrank:
        comp["hrank"] = {}
        for spec in specs:
            comp["hrank"][spec["conv"]] = collect_hrank_streaming(
                spec["conv"], spec["bn"],
                max_batches=int(getattr(T, "ILR_MAX_BATCHES", 6))
            )

    # Per-layer normalize each component to [0,1] then fuse with ILR_WEIGHTS
    comp_norm = {name: _normalize_for_pruning(d) for name, d in comp.items()}
    fused: Dict[str, torch.Tensor] = {}
    for spec in specs:
        k = spec["conv"]
        acc = None; wsum = 0.0
        for name, d in comp_norm.items():
            if k not in d: continue
            w = float(W.get(name, 0.0))
            if w == 0.0: continue
            v = d[k].to(torch.float32)
            acc = v * w if acc is None else (acc + v * w)
            wsum += w
        if acc is None:
            # If nothing available, make a flat zero vector → “everything least important”
            C = get_conv_module(model, k).out_channels
            fused[k] = torch.zeros(C, dtype=torch.float32)
        else:
            fused[k] = acc / max(1e-12, wsum)
    return fused
    #  STEP-4: INSIDE-LAYER RANKING — EXIT


def _fuse_scores_per_layer(components: Dict[str, Dict[str, torch.Tensor]], weights: Dict[str, float]):
    # components: {"taylor": {conv: [C]}, "hrank": {...}, "gamma": {...}}
    fused = {}
    # union of conv paths present in any component
    conv_paths = set()
    for comp in components.values():
        if comp is None: continue
        conv_paths.update(comp.keys())
    for conv in conv_paths:
        acc = None; wsum = 0.0
        for name, comp in components.items():
            if comp is None or conv not in comp: continue
            w = float(weights.get(name, 0.0));
            if w == 0.0: continue
            # Scores are now [0, 1] per-layer, where 0 is least important
            v = comp[conv].to(torch.float32)
            acc = v*w if acc is None else (acc + v*w); wsum += w
        if acc is None:  # fallback to first available component
            for comp in components.values():
                if comp and conv in comp: acc = comp[conv]; break
        if acc is not None: # Ensure we have a score
             fused[conv] = (acc / max(1e-12, wsum)) if wsum>0 else acc
    return fused


def _scorer_enabled(name: str) -> bool:
    gs = getattr(T, "GLOBAL_SCORERS", {})
    if name in gs: return bool(gs[name])
    # accept Phase-4 'bn_gamma' for our internal 'gamma'
    if name == "gamma":
        return bool(gs.get("bn_gamma", gs.get("gamma", True)))
    # 🔧 PATCH: Fail-safe for unknown scorers
    print(f"⚠️ Unknown scorer '{name}' not in GLOBAL_SCORERS; defaulting to False")
    return False



# Benefit per channel (robust, conv-hooked shapes)
# ----------------------------
@torch.no_grad()
def _conv_output_hw(model, conv_path, loader, device, cache_mgr=None):
    """
    Return (H_out, W_out) for the *current* conv at conv_path.
    Robust to torch.compile by probing with the raw forward.
    Falls back to running the 'features' subgraph or using the pool output if needed.

     Added caching support via cache_mgr parameter.
    """
    #  Check cache first
    if cache_mgr is not None:
        cached_shape = cache_mgr.get_shape(conv_path)
        if cached_shape is not None:
            return cached_shape

    # Resolve conv module (unwrap Sequential container)
    seq_or_conv = get_module(model, conv_path)
    conv = seq_or_conv[0] if isinstance(seq_or_conv, nn.Sequential) else seq_or_conv
    assert isinstance(conv, nn.Conv2d), f"{conv_path} is not a Conv2d."

    #  Grouped convolution validation
    if conv.groups > 1:
        raise NotImplementedError(
            f"Grouped convolution detected at {conv_path} (groups={conv.groups}). "
            f"Shape probing for grouped convolutions is not supported. "
            f"Please use standard convolutions (groups=1) or implement grouped conv support."
        )

    shape = {"hw": None}

    def hook(_, __, out):
        if isinstance(out, torch.Tensor) and out.dim() == 4:
            shape["hw"] = (int(out.shape[2]), int(out.shape[3]))
        return out

    # 1) Try: hook conv + run RAW forward (disable compiled graph)
    #  Track hook trigger count for debugging
    hook_trigger_count = [0]

    def hook_with_counter(_, __, out):
        hook_trigger_count[0] += 1
        if isinstance(out, torch.Tensor) and out.dim() == 4:
            shape["hw"] = (int(out.shape[2]), int(out.shape[3]))
        return out

    h = conv.register_forward_hook(hook_with_counter)
    try:
        #  Use a lightweight one-off batch from the existing loader to avoid
        # constructing a new DataLoader. If the loader is empty, fall back to
        # a small synthetic batch that matches the model's expected input
        # channels.
        try:
            it = iter(loader)
            x, _ = next(it)
        except StopIteration:
            # Empty loader: synthesize a minimal batch
            H, W = CONFIG.get("IMG_SIZE", (32, 32))
            C = 3
            try:
                first_conv = next(m for m in model.modules() if isinstance(m, nn.Conv2d))
                C = int(getattr(first_conv, "in_channels", C))
            except Exception:
                pass
            x = torch.zeros(1, C, H, W, device=device)
        except Exception:
            # Loader failure: also fall back to synthetic batch
            H, W = CONFIG.get("IMG_SIZE", (32, 32))
            C = 3
            try:
                first_conv = next(m for m in model.modules() if isinstance(m, nn.Conv2d))
                C = int(getattr(first_conv, "in_channels", C))
            except Exception:
                pass
            x = torch.zeros(1, C, H, W, device=device)

        # Ensure tensor is on the correct device
        if x.device != device:
            x = x.to(device, non_blocking=True)

        with _temporarily_uncompiled_eval():
            _ = _raw_forward(x)  #  Removed redundant .to(device)
    finally:
        h.remove()

    if shape["hw"] is not None:
        #  Cache the result before returning
        if cache_mgr is not None:
            cache_mgr.set_shape(conv_path, shape["hw"])
        return shape["hw"]


    # 2) Fallback: run only the 'features' stem to ensure the conv is executed in isolation
    #    (use parent 'features' container so hooks definitely see this conv)
    parent_path = conv_path.split('.')[0]  # "features" in your net
    try:
        features_mod = get_module(model, parent_path)
    except Exception:
        features_mod = None

    if features_mod is not None:
        h2 = conv.register_forward_hook(hook)
        try:
            # Reuse the same loader-based or synthetic probing strategy
            try:
                it = iter(loader)
                x, _ = next(it)
            except StopIteration:
                H, W = CONFIG.get("IMG_SIZE", (32, 32))
                C = 3
                try:
                    first_conv = next(m for m in model.modules() if isinstance(m, nn.Conv2d))
                    C = int(getattr(first_conv, "in_channels", C))
                except Exception:
                    pass
                x = torch.zeros(1, C, H, W, device=device)
            except Exception:
                H, W = CONFIG.get("IMG_SIZE", (32, 32))
                C = 3
                try:
                    first_conv = next(m for m in model.modules() if isinstance(m, nn.Conv2d))
                    C = int(getattr(first_conv, "in_channels", C))
                except Exception:
                    pass
                x = torch.zeros(1, C, H, W, device=device)

            if x.device != device:
                x = x.to(device, non_blocking=True)
            with _temporarily_uncompiled_eval():
                _ = features_mod(x)  #  Removed redundant .to(device)
        finally:
            h2.remove()

    if shape["hw"] is not None:
        #  Cache the result before returning
        if cache_mgr is not None:
            cache_mgr.set_shape(conv_path, shape["hw"])
        return shape["hw"]

    # 3) Last-ditch: derive from the pool output in the same block (slightly later in graph, good enough for MACs)
    #    We expect the caller to pass a spec with 'pool' alongside conv; mine it from known layout:
    try:
        # Guess pool path from your ALT_ORDER spec
        pool_path = None
        for L in T.ALT_ORDER:
            if L["conv"] == conv_path:
                pool_path = L.get("pool", None)
                break
        if pool_path is not None:
            pool = get_module(model, pool_path)
            shape_pool = {"hw": None}
            def hook_pool(_, __, out):
                if isinstance(out, torch.Tensor) and out.dim()==4:
                    shape_pool["hw"] = (int(out.shape[2]), int(out.shape[3]))
                return out
            hp = pool.register_forward_hook(hook_pool)
            try:
                # Reuse the same loader-based or synthetic probing strategy
                try:
                    it = iter(loader)
                    x, _ = next(it)
                except StopIteration:
                    H, W = CONFIG.get("IMG_SIZE", (32, 32))
                    C = 3
                    try:
                        first_conv = next(m for m in model.modules() if isinstance(m, nn.Conv2d))
                        C = int(getattr(first_conv, "in_channels", C))
                    except Exception:
                        pass
                    x = torch.zeros(1, C, H, W, device=device)
                except Exception:
                    H, W = CONFIG.get("IMG_SIZE", (32, 32))
                    C = 3
                    try:
                        first_conv = next(m for m in model.modules() if isinstance(m, nn.Conv2d))
                        C = int(getattr(first_conv, "in_channels", C))
                    except Exception:
                        pass
                    x = torch.zeros(1, C, H, W, device=device)

                if x.device != device:
                    x = x.to(device, non_blocking=True)
                with _temporarily_uncompiled_eval():
                    _ = _raw_forward(x)  #  Removed redundant .to(device)
            finally:
                hp.remove()
            if shape_pool["hw"] is not None:
                Hp, Wp = shape_pool["hw"]
                # Infer pre-pool size conservatively
                pool = get_module(model, pool_path)
                if isinstance(pool, nn.MaxPool2d):
                    k = pool.kernel_size if isinstance(pool.kernel_size, int) else pool.kernel_size[0]
                    s = (pool.stride if pool.stride is not None else pool.kernel_size)
                    s = s if isinstance(s, int) else s[0]
                    p = pool.padding if isinstance(pool.padding, int) else pool.padding[0]
                    if k == 2 and s == 2 and p == 0:
                        result = (int(Hp*2), int(Wp*2))
                        #  Cache the result before returning
                        if cache_mgr is not None:
                            cache_mgr.set_shape(conv_path, result)
                        return result
                result = (int(Hp), int(Wp))
                #  Cache the result before returning
                if cache_mgr is not None:
                    cache_mgr.set_shape(conv_path, result)
                return result
    except Exception:
        pass

    # If we made it here, the conv still didn’t fire — bail with a clear error.
    # 🔧 PATCH: Add explicit validation before returning
    if shape["hw"] is None:
        #  Removed estimation fallback - it doesn't account for pooling layers
        # The estimation was causing HW mismatch (reporting 8×8 instead of actual 4×4 after pooling)
        # If hooks failed, we should fail with a clear error rather than return incorrect HW
        try:
            conv = seq_or_conv[0] if isinstance(seq_or_conv, nn.Sequential) else seq_or_conv
            x_shape = "unknown"
            try:
                it = iter(loader)
                x_dbg, _ = next(it)
                x_shape = x_dbg.shape
            except Exception:
                # Fall back to synthetic input shape for diagnostics
                H, W = CONFIG.get("IMG_SIZE", (32, 32))
                C = 3
                try:
                    first_conv = next(m for m in model.modules() if isinstance(m, nn.Conv2d))
                    C = int(getattr(first_conv, "in_channels", C))
                except Exception:
                    pass
                x_shape = (1, C, H, W)
            e = RuntimeError("Hook-based shape capture failed - no valid output captured")
        except Exception as e:
            #  Enhanced error message with full debugging context
            error_msg = (
                f"[_conv_output_hw] Shape capture failed for {conv_path}\n"
                f"  Device info:\n"
                f"    Model device: {device}\n"
                f"    Input device: {x.device if 'x' in locals() else 'unknown'}\n"
                f"    Conv device: {next(conv.parameters()).device if list(conv.parameters()) else 'no params'}\n"
                f"  Input shape: {x.shape if 'x' in locals() else 'unknown'}\n"
                f"  Hook info:\n"
                f"    Hook trigger count: {hook_trigger_count[0]}\n"
                f"    Hook registered: Yes\n"
                f"  Conv parameters:\n"
                f"    in_channels: {conv.in_channels}\n"
                f"    out_channels: {conv.out_channels}\n"
                f"    kernel_size: {conv.kernel_size}\n"
                f"    stride: {conv.stride}\n"
                f"    padding: {conv.padding}\n"
                f"    groups: {conv.groups}\n"
            )
            if conv.groups > 1:
                error_msg += f"  Note: Grouped convolution detected (groups={conv.groups})\n"
            error_msg += (
                f"  Failure details: {e}\n"
                f"  Recovery suggestions:\n"
                f"    1. Check if model is in eval mode\n"
                f"    2. Verify input tensor is on correct device\n"
                f"    3. Ensure conv layer is not frozen or disabled\n"
                f"    4. Try disabling torch.compile if enabled"
            )
            raise AssertionError(error_msg)

    #  Cache the result before returning
    if cache_mgr is not None and shape["hw"] is not None:
        cache_mgr.set_shape(conv_path, shape["hw"])
    return shape["hw"]

# === Phase-1 helpers (ECON benefit + alignment hint) ===
@torch.no_grad()
def _benefit_per_channel_econ(layer_specs,
                              alpha: Optional[float] = None,
                              beta: Optional[float]  = None):
    """
     Economics-aware per-channel 'benefit' calculation.

    Benefit = computational savings from pruning one channel
    Formula: b_eff = b_this + α * b_next + β * b_lin

    Components:
    - b_this: MACs saved in current layer's convolution
    - b_next: MACs saved in next layer (weighted by α, default 0.25)
    - b_lin:  MACs saved in Linear1 layer (weighted by β, default 0.0)

    Higher benefit = more economical to prune (saves more computation)
    """
    # T Get weighting coefficients from config
    if alpha is None:
        alpha = float(getattr(T, "ALPHA_NEXT", 0.25))
    if beta is None:
        beta  = float(getattr(T, "BETA_LINEAR", 0.0))

    out = {}
    for spec in layer_specs:
        conv_path = spec["conv"]
        conv_seq_or_conv = get_module(model, conv_path)
        conv = conv_seq_or_conv[0] if isinstance(conv_seq_or_conv, nn.Sequential) else conv_seq_or_conv
        assert isinstance(conv, nn.Conv2d)
        Cout = conv.out_channels

        # Component 1: Current layer MACs (H_out * W_out * C_in/groups * kH * kW)
        Hc, Wc = _conv_output_hw(model, conv_path, sequential_loader, DEVICE, cache_mgr=cache_manager)
        kH,kW = (conv.kernel_size if isinstance(conv.kernel_size, tuple) else (conv.kernel_size, conv.kernel_size))
        g = max(1, conv.groups)
        b_this = float(Hc * Wc * (conv.in_channels // g) * kH * kW)

        # Component 2: Next layer MACs (pruning this layer's output reduces next layer's input)
        b_next = 0.0
        next_conv_path = spec.get("next_conv")
        if next_conv_path:
            nseq = get_module(model, next_conv_path)
            nconv = nseq[0] if isinstance(nseq, nn.Sequential) else nseq
            assert isinstance(nconv, nn.Conv2d)
            Hn, Wn = _conv_output_hw(model, next_conv_path, sequential_loader, DEVICE, cache_mgr=cache_manager)
            nkH, nkW = (nconv.kernel_size if isinstance(nconv.kernel_size, tuple) else (nconv.kernel_size, nconv.kernel_size))
            g_next = max(1, nconv.groups)
            b_next = float(Hn * Wn * (nconv.out_channels // g_next) * nkH * nkW)

        # Component 3: Linear layer MACs (terminal layers only, each channel contributes H*W features)
        b_lin = 0.0
        if not next_conv_path:
            lin1 = model.classifier[LINEAR_INDEX]
            b_lin = float((Hc * Wc) * lin1.out_features)

        # Combine components with weights (all channels in same layer have same benefit)
        per_c = float(b_this + alpha * b_next + beta * b_lin)
        out[conv_path] = torch.full((Cout,), per_c, dtype=torch.float32)

    return out

# Linear layer (head) scoring helpers

@torch.no_grad()
def _linear1_cols_per_channel(H: int, W: int, C: int):
    """Return list of slices, one per channel, covering that channel’s H*W columns in Linear1."""
    stride = H * W
    return [slice(c * stride, (c + 1) * stride) for c in range(C)]

@torch.no_grad()
def _linear1_channel_scores(H: int, W: int, agg: str = "l1_mean") -> torch.Tensor:
    """
    Build per-channel importance from Linear1 weights by aggregating the columns
    belonging to each B5 channel. Returns [C] normalized to [0,1] (0 = least important).
    """
    lin1 = model.classifier[LINEAR_INDEX]
    Wmat = lin1.weight.detach()  # [out, in]
    stride = H * W
    C = Wmat.size(1) // stride
    cols = _linear1_cols_per_channel(H, W, C)

    scores = torch.empty(C, dtype=torch.float32, device=Wmat.device)
    if agg == "l1_min":
        for c, sl in enumerate(cols): scores[c] = Wmat[:, sl].abs().sum(dim=0).min().float()
    elif agg == "l2_mean":
        for c, sl in enumerate(cols): scores[c] = torch.sqrt((Wmat[:, sl] ** 2).sum(dim=0)).mean().float()
    else:  # "l1_mean"
        for c, sl in enumerate(cols): scores[c] = Wmat[:, sl].abs().sum(dim=0).mean().float()

    # Normalize per-layer to [0,1]
    smin, smax = scores.min(), scores.max()
    if (smax - smin).abs() < 1e-12:
        return torch.zeros_like(scores, device="cpu")
    return ((scores - smin) / (smax - smin)).detach().cpu()

@torch.no_grad()
def _alignment_hint(layer_specs, channels_pre: Dict[str,int], max_steps: int = 8):
    """
    Layer-level bonus to encourage landing on a nearby plateau.
    Returns dict[conv_path] -> tensor[C] with a constant value per channel:
        bonus = 1 / clamp(steps_to_next_lower_plateau, 1..max_steps)
    If no lower plateau exists, bonus = 0.
    """
    out = {}
    plateaus = set(T.PLATEAUS)
    if not plateaus:
        return out
    p_sorted = sorted(list(plateaus))
    for spec in layer_specs:
        conv_path = spec["conv"]
        C = int(channels_pre.get(conv_path, get_conv_module(model, conv_path).out_channels))
        lower = [p for p in p_sorted if p < C]
        if not lower:
            out[conv_path] = torch.zeros(C, dtype=torch.float32)
            continue
        target = lower[-1]  # closest lower plateau
        steps = max(1, min(int(C - target), int(max_steps)))
        bonus = 1.0 / float(steps)
        out[conv_path] = torch.full((C,), bonus, dtype=torch.float32)
    return out


@torch.no_grad()
def _benefit_per_channel(layer_specs):
    out = {}
    for spec in layer_specs:
        conv_path = spec["conv"]
        conv_seq_or_conv = get_module(model, conv_path)
        conv = conv_seq_or_conv[0] if isinstance(conv_seq_or_conv, nn.Sequential) else conv_seq_or_conv
        assert isinstance(conv, nn.Conv2d)

        # This layer
        #  Pass cache_manager for shape caching
        Hc, Wc = _conv_output_hw(model, conv_path, sequential_loader, DEVICE, cache_mgr=cache_manager)
        kH, kW = (conv.kernel_size if isinstance(conv.kernel_size, tuple) else (conv.kernel_size, conv.kernel_size))
        Cin, Cout, g = conv.in_channels, conv.out_channels, max(1, conv.groups)
        #  Use float to prevent integer overflow
        b_this = float(Hc * Wc * (Cin // g) * kH * kW)  # per-out-channel MACs

        # Next layer share (if any)
        b_next = 0.0
        next_conv_path = spec.get("next_conv")
        if next_conv_path:
            nconv_seq_or_conv = get_module(model, next_conv_path)
            nconv = nconv_seq_or_conv[0] if isinstance(nconv_seq_or_conv, nn.Sequential) else nconv_seq_or_conv
            assert isinstance(nconv, nn.Conv2d)
            #  Pass cache_manager for shape caching
            Hn, Wn = _conv_output_hw(model, next_conv_path, sequential_loader, DEVICE, cache_mgr=cache_manager)
            nkH, nkW = (nconv.kernel_size if isinstance(nconv.kernel_size, tuple) else (nconv.kernel_size, nconv.kernel_size))
            g_next = max(1, nconv.groups)
            # each input channel to next layer participates in (Cout_next / g_next) kernels
            #  Use float to prevent integer overflow
            b_next = float(Hn * Wn * (nconv.out_channels // g_next) * nkH * nkW)

        # Terminal linear share
        b_lin = 0.0
        if not next_conv_path:
            HW = Hc * Wc
            lin1 = model.classifier[LINEAR_INDEX]
            #  Use float to prevent integer overflow
            b_lin = float(HW * lin1.out_features)

        per_c = float(b_this + b_next + b_lin)
        out[conv_path] = torch.full((Cout,), per_c, dtype=torch.float32)
    return out

# --- START [Global 2.2]  Add Dispersion Health Checkers ---
@torch.no_grad()
def measure_dispersion(conv_path):
    conv = get_conv_module(model, conv_path)
    W = conv.weight.detach().view(conv.out_channels, -1)
    if W.shape[0] < 10:
        return 1.0 # Not enough filters to measure
    Wn = F.normalize(W, p=2, dim=1)

    # Sample K random (i<j) pairs
    K = min(200, (Wn.shape[0]*(Wn.shape[0]-1))//2)
    if K <= 0: return 1.0

    device_local = Wn.device
    idx_i = torch.randint(0, Wn.shape[0], (K,), device=device_local)
    idx_j = torch.randint(0, Wn.shape[0], (K,), device=device_local)
    # Ensure i != j
    idx_j = torch.where(idx_j == idx_i, (idx_j+1) % Wn.shape[0], idx_j)

    sim = (Wn[idx_i] * Wn[idx_j]).sum(dim=1)
    # Use median dispersion (1 - similarity)
    dispersion = float((1.0 - sim).median().item())
    return dispersion

@torch.no_grad()
def check_dispersion(conv_path, baseline_dispersion_map, min_pct=getattr(T, "HEALTH_MIN_DISPERSION_PCT", 0.6)):
    """
    Checks if the surviving filters in a layer are still diverse.
    Returns True if healthy, False if correlated.
    """
    base = float(baseline_dispersion_map.get(conv_path, 1.0)) # Get baseline
    now = float(measure_dispersion(conv_path)) # Measure current

    ok = (now / max(1e-9, base)) >= float(min_pct)

    if not ok:
        print(f"🩺 [Health] {conv_path}: dispersion {now:.3f} < {min_pct*100:.0f}% of baseline {base:.3f}")
    return ok


