# Phase 4 Cell 3C.1 — CHANNELGATE & SURGERY FUNCTIONS
# Lines: ~464 lines
# Dependencies: Cell 3A, Cell 3B
# Exports: 1 class + 10 functions
# Contents:
#   - ChannelGate (class) - simple mask-based gating
#   - Gate helpers (6 functions):
#     * _ensure_gate_for_conv_path(), _get_gate_by_conv_path()
#     * set_drop_mask(), strip_channel_gate_for_infer()
#     * _next_conv_path_from_pool()
#   - Surgery functions (4 functions):
#     * rebuild_linear_layer_with_recovery()
#     * prune_conv_block_and_linear_() - main surgery operation
#     * restore_model_structure_from_snapshot()
#     * sync_all_channelgates()
# ═══════════════════════════════════════════════════════════════════════════

class ChannelGate(nn.Module):
    def __init__(self, C: int):
        super().__init__(); self.register_buffer("mask", torch.ones(1, C, 1, 1))
    def forward(self, x): return x * self.mask

def _ensure_gate_for_conv_path(model, conv_path: str, device) -> str:
    parent, name = _get_parent_and_name(model, conv_path)
    L = getattr(parent, name)
    if isinstance(L, nn.Sequential):
        for idx, child in enumerate(L):
            if isinstance(child, ChannelGate):
                if isinstance(L[0], nn.Conv2d) and child.mask.shape[1] != L[0].out_channels:
                    with torch.no_grad():
                        child.mask = torch.ones(1, L[0].out_channels, 1, 1, device=child.mask.device)
                return f"{conv_path}.{idx}"
        conv = L[0]; gate = ChannelGate(conv.out_channels).to(device)
        setattr(parent, name, nn.Sequential(*list(L), gate))
        return f"{conv_path}.{len(L)}"
    else:
        assert isinstance(L, nn.Conv2d), f"Expected Conv2d at {conv_path}, got {type(L)}"
        gate = ChannelGate(L.out_channels).to(device)
        setattr(parent, name, nn.Sequential(L, gate))
        return f"{conv_path}.1"

def _get_gate_by_conv_path(model, conv_path: str) -> ChannelGate:
    m = get_module(model, conv_path)
    if isinstance(m, nn.Sequential):
        for child in m:
            if isinstance(child, ChannelGate): return child
    if isinstance(m, nn.Conv2d):
        parent, name = _get_parent_and_name(model, conv_path)
        gate = ChannelGate(m.out_channels).to(m.weight.device)
        setattr(parent, name, nn.Sequential(m, gate))
        return gate
    raise RuntimeError(f"No ChannelGate found or creatable at {conv_path}")

@torch.no_grad()
def set_drop_mask(model, conv_path: str, indices: Optional[torch.LongTensor]):
    """
    Set drop mask for a conv layer, automatically resizing if channel count changed.

    Handles dynamic channel count changes during pruning by resizing the gate mask
    to match the current conv layer's out_channels.
    """
    gate = _get_gate_by_conv_path(model, conv_path)
    C = get_conv_module(model, conv_path).out_channels
    if gate.mask.shape[1] != C:
        gate.mask = torch.ones(1, C, 1, 1, device=gate.mask.device)
    gate.mask.fill_(1.0)
    if indices is not None and indices.numel() > 0:
        gate.mask.index_fill_(1, indices.to(gate.mask.device), 0.0)

def strip_channel_gate_for_infer(model, conv_path: str) -> bool:
    parent, name = _get_parent_and_name(model, conv_path)
    L = getattr(parent, name)
    if isinstance(L, nn.Sequential):
        keep = [m for m in L if not isinstance(m, ChannelGate)]
        if len(keep) != len(L):
            setattr(parent, name, nn.Sequential(*keep))
            return True
    return False

@torch.no_grad()
def _next_conv_path_from_pool(model, pool_path: str) -> Optional[str]:
    """
    CNN-style: find the next conv layer *after* a pooling layer in the model.

    Used for the 5-layer CNN backbone where blocks are (conv, bn, pool).
    """
    parts = pool_path.split('.')
    parent_path = '.'.join(parts[:-1])
    try:
        start_idx = int(parts[-1])
    except ValueError:
        return None

    parent = get_module(model, parent_path)

    def _is_conv_container(m: nn.Module) -> bool:
        return isinstance(m, nn.Conv2d) or (
            isinstance(m, nn.Sequential)
            and len(m) > 0
            and isinstance(m[0], nn.Conv2d)
        )

    for j in range(start_idx + 1, len(parent)):
        if _is_conv_container(parent[j]):
            return f"{parent_path}.{j}"
    return None


def _next_conv_in_features_from_conv(model, conv_path: str) -> Optional[str]:
    """
    VGG-style: walk forward in `model.features` from `conv_path` and
    return the next conv container in that Sequential.

    This mirrors the local VGG ModelAdapter.next_conv_path_from_conv logic
    and is used to distinguish internal vs terminal convs within a block.
    """
    parent_path = ".".join(conv_path.split(".")[:-1])
    leaf = conv_path.split(".")[-1]
    parent = get_module(model, parent_path)

    try:
        start_idx = int(leaf)
    except ValueError:
        return None

    def _is_conv_container(m: nn.Module) -> bool:
        return isinstance(m, nn.Conv2d) or (
            isinstance(m, nn.Sequential)
            and len(m) > 0
            and isinstance(m[0], nn.Conv2d)
        )

    for j in range(start_idx + 1, len(parent)):
        if _is_conv_container(parent[j]):
            return f"{parent_path}.{j}"
    # No later conv in features → terminal conv (e.g., features.40)
    return None

def rebuild_linear_layer_with_recovery(model, device, lin1, C_new, H, W, keep, conv_path):
    """
    Rebuild Linear layer when dimension validation fails.

    Attempts to recover from dimension mismatches using heuristics.
    Uses heuristics to recover from common misalignment scenarios.

    Args:
        model: The model being pruned
        device: Device to create tensors on
        lin1: Current Linear layer
        C_new: Number of channels after pruning
        H: Height of feature maps
        W: Width of feature maps
        keep: Indices of channels to keep
        conv_path: Path to conv layer for logging

    Returns:
        nn.Linear: New Linear layer with corrected dimensions, or None if recovery fails
    """
    new_in_features = C_new * H * W

    print(f"⚠️ [recovery] Attempting Linear layer recovery at {conv_path}")
    print(f"  Target dimensions: {C_new} channels × {H}×{W} = {new_in_features} features")
    print(f"  Current lin1.in_features: {lin1.in_features}")

    # Recovery Strategy 1: Rebuild from scratch with Xavier initialization
    try:
        print(f"  Strategy 1: Rebuild with Xavier initialization")
        new_lin1 = nn.Linear(new_in_features, lin1.out_features, bias=True).to(device)

        # Initialize weights using Xavier uniform (same as PyTorch default)
        nn.init.xavier_uniform_(new_lin1.weight)
        if new_lin1.bias is not None:
            nn.init.zeros_(new_lin1.bias)

        print(f"✓ [recovery] Successfully rebuilt Linear layer: {new_in_features} → {lin1.out_features}")
        return new_lin1

    except Exception as e:
        print(f"✗ [recovery] Strategy 1 failed: {e}")

    # Recovery Strategy 2: Try to salvage weights if dimensions are close
    try:
        if lin1.in_features >= new_in_features:
            print(f"  Strategy 2: Truncate existing weights (old >= new)")
            new_lin1 = nn.Linear(new_in_features, lin1.out_features, bias=True).to(device)

            with torch.no_grad():
                # Take first new_in_features columns
                new_lin1.weight.copy_(lin1.weight.data[:, :new_in_features])
                if lin1.bias is not None:
                    new_lin1.bias.copy_(lin1.bias.data)

            print(f"✓ [recovery] Successfully truncated Linear layer weights")
            return new_lin1
        else:
            print(f"  Strategy 2: Pad existing weights (old < new)")
            new_lin1 = nn.Linear(new_in_features, lin1.out_features, bias=True).to(device)

            with torch.no_grad():
                # Copy existing weights and zero-pad the rest
                new_lin1.weight.data[:, :lin1.in_features].copy_(lin1.weight.data)
                new_lin1.weight.data[:, lin1.in_features:].zero_()
                if lin1.bias is not None:
                    new_lin1.bias.copy_(lin1.bias.data)

            print(f"✓ [recovery] Successfully padded Linear layer weights")
            return new_lin1

    except Exception as e:
        print(f"✗ [recovery] Strategy 2 failed: {e}")

    print(f"✗ [recovery] All recovery strategies failed")
    return None


def prune_conv_block_and_linear_(model, device, conv_path, bn_path, pool_path, keep_indices, loader):
    """
    Prunes a conv block and updates the next layer's input channels or Linear1.
    CRITICAL FIX: Always sync ChannelGate mask dimensions after pruning.
    """
    #  Validate keep_indices is not empty
    if not keep_indices or len(keep_indices) == 0:
        raise ValueError(
            f"keep_indices cannot be empty for {conv_path}. "
            f"Cannot create layer with 0 output channels."
        )

    lin1 = model.classifier[LINEAR_INDEX]
    conv_seq_or_conv = get_module(model, conv_path)
    conv = conv_seq_or_conv[0] if isinstance(conv_seq_or_conv, nn.Sequential) else conv_seq_or_conv
    bn   = get_module(model, bn_path)
    keep = torch.as_tensor(sorted(set(keep_indices)), dtype=torch.long)

    if keep.numel() == conv.out_channels:
        # No-op: already at target size
        return model

    # 1. Prune Conv + BN tensors
    with torch.no_grad():
        conv.weight = nn.Parameter(conv.weight.data[keep].clone())
        if conv.bias is not None:
            conv.bias = nn.Parameter(conv.bias.data[keep].clone())
        conv.out_channels = keep.numel()

        bn.weight = nn.Parameter(bn.weight.data[keep].clone())
        bn.bias   = nn.Parameter(bn.bias.data[keep].clone())
        bn.running_mean = bn.running_mean.data[keep].clone()
        bn.running_var  = bn.running_var.data[keep].clone()
        bn.num_features = keep.numel()

    # 2. ✅ CRITICAL FIX: Force ChannelGate resize BEFORE any forward pass
    try:
        gate = _get_gate_by_conv_path(model, conv_path)
        if gate.mask.shape[1] != conv.out_channels:
            with torch.no_grad():
                gate.mask = torch.ones(1, conv.out_channels, 1, 1, device=gate.mask.device)
                print(f"[surgery] Resized ChannelGate mask: {gate.mask.shape[1]} channels at {conv_path}")
    except Exception as e:
        print(f"⚠️ [surgery] Failed to resize ChannelGate at {conv_path}: {e}")

    # 3. Check if this is an internal or terminal layer
    #    CNN uses pool→next_conv wiring; VGG uses conv→next_conv-in-features.
    if BACKBONE == "vgg16_bn":
        next_conv_path = _next_conv_in_features_from_conv(model, conv_path)
    else:
        next_conv_path = _next_conv_path_from_pool(model, pool_path)


    if next_conv_path is not None:
        # Internal layer: slice next conv's input channels
        next_seq_or_conv = get_module(model, next_conv_path)
        next_conv = next_seq_or_conv[0] if isinstance(next_seq_or_conv, nn.Sequential) else next_seq_or_conv
        #  Enhanced error message with debugging context
        if not isinstance(next_conv, nn.Conv2d):
            raise TypeError(
                f"[surgery] Expected Conv2d at {next_conv_path}, got {type(next_conv)}.\n"
                f"  Current layer: {conv_path}\n"
                f"  Next layer: {next_conv_path}\n"
                f"  Module type: {type(next_seq_or_conv)}\n"
                f"  Recovery: Check layer_specs configuration"
            )
        if next_conv.groups != 1:
            raise NotImplementedError(
                f"[surgery] Grouped convolutions not supported at {next_conv_path}.\n"
                f"  Groups: {next_conv.groups}\n"
                f"  Current layer: {conv_path}\n"
                f"  Recovery: Use standard Conv2d (groups=1) or implement grouped conv support"
            )

        with torch.no_grad():
            W = next_conv.weight.data
            new_W = W[:, keep, :, :].clone()
            next_conv.weight = nn.Parameter(new_W)
            next_conv.in_channels = keep.numel()

        return model

    # Terminal layer: Direct calculation (no hooks, more robust)
    # ✅ ROBUST APPROACH: Calculate dimensions directly from current model state

    C_new = keep.numel()  # Number of channels we kept after pruning

    # Get spatial dimensions (H, W) by running one forward pass through features
    # FIX: Use single-worker loader for shape probing
    probe_loader = DataLoader(loader.dataset, batch_size=loader.batch_size,
                              shuffle=False, num_workers=0, pin_memory=False)
    imgs, _ = next(iter(probe_loader))
    with torch.no_grad():
        with _temporarily_uncompiled_eval():
            feat_out = MODEL_REF.features(imgs.to(device))

    _, C_actual, H, W = feat_out.shape

    # Sanity check: feature output should have C_new channels
    if C_actual != C_new:
        print(f"⚠️ [surgery] Warning: Features output {C_actual} channels but expected {C_new}. Using {C_actual}.")
        C_new = C_actual
        keep = torch.arange(C_new, device=device)

    #  Comprehensive Linear layer dimension validation with recovery
    old_C, new_in_features, is_valid, error_msg = validate_linear_dimensions(
        lin1, H, W, C_new, conv_path
    )

    if not is_valid:
        print(f"⚠️ {error_msg}")
        print(f"⚠️ [surgery] Attempting recovery for Linear layer at {conv_path}")

        # Attempt recovery
        recovered_lin1 = rebuild_linear_layer_with_recovery(
            model, device, lin1, C_new, H, W, keep, conv_path
        )

        if recovered_lin1 is not None:
            # Recovery successful - use the rebuilt layer
            model.classifier[LINEAR_INDEX] = recovered_lin1
            print(f"✓ [surgery] Recovery successful: Terminal layer rebuilt with {new_in_features} input features")
            return model
        else:
            # Recovery failed - raise the original error
            raise ValueError(error_msg)

    # Validation passed - proceed with normal column selection
    # Calculate which columns to keep from the OLD linear layer
    # Old linear expects: [batch, C_old × H × W]
    # Each channel c occupies columns [c*H*W : (c+1)*H*W]

    keep_cols = []
    for c in keep.tolist():
        keep_cols.extend(range(c * H * W, (c + 1) * H * W))
    keep_cols = torch.as_tensor(keep_cols, dtype=torch.long, device=device)

    # Final validation
    if keep_cols.numel() != new_in_features:
        # Enhanced error message with full debugging context
        error_msg = (
            f"[surgery] Linear dimension calculation failed for {conv_path}\n"
            f"  Dimension mismatch:\n"
            f"    keep_cols: {keep_cols.numel()}\n"
            f"    expected:  {new_in_features}\n"
            f"  Channel info:\n"
            f"    C_old: {old_C}\n"
            f"    C_new: {C_new}\n"
            f"    kept:  {len(keep)} channels\n"
            f"  Spatial dimensions:\n"
            f"    H: {H}, W: {W}\n"
            f"  Linear layer:\n"
            f"    old in_features: {lin1.in_features}\n"
            f"    new in_features: {new_in_features}\n"
            f"    out_features: {lin1.out_features}\n"
            f"  Recovery suggestions:\n"
            f"    1. Check if features output shape matches expected\n"
            f"    2. Verify keep_indices are valid\n"
            f"    3. Ensure H*W alignment (in_features % (H*W) == 0)"
        )
        raise RuntimeError(error_msg)

    # Create new Linear layer with correct dimensions
    with torch.no_grad():
        new_lin1 = nn.Linear(new_in_features, lin1.out_features, bias=True).to(device)
        new_lin1.weight.copy_(lin1.weight.data[:, keep_cols])
        new_lin1.bias.copy_(lin1.bias.data)

    model.classifier[LINEAR_INDEX] = new_lin1

    print(f"[surgery] Terminal: kept={C_new}/{old_C} channels; "
          f"lin1: {old_C}×{H}×{W}={lin1.in_features} → {C_new}×{H}×{W}={new_in_features}")
    return model


#  Snapshot validation helper
def restore_model_structure_from_snapshot(model, snapshot_state, device):
    """
    Restores model layer dimensions to match a snapshot before loading weights.

    This is critical for rollback after failed pruning attempts. We must:
    1. Resize conv layers to match snapshot dimensions (both in_channels and out_channels)
    2. Resize BN layers to match conv out_channels
    3. Do this BEFORE calling load_state_dict() to avoid shape mismatches

    Why needed: Pruning modifies layer dimensions. If we try to load old weights
    into modified layers, PyTorch will raise shape mismatch errors.
    """
    if 'layer_specs' not in globals():
        raise RuntimeError("restore_model_structure_from_snapshot requires global 'layer_specs' to be defined.")

    print(f"[Rollback] Restoring model structure from snapshot...")

    #  Iterate through all layers that may have been pruned
    for spec in layer_specs:
        conv_path = spec["conv"]
        bn_path   = spec["bn"]

        #  Get current live modules from model
        try:
            seq_or_conv = get_module(model, conv_path)
            conv = seq_or_conv[0] if isinstance(seq_or_conv, nn.Sequential) else seq_or_conv
            bn   = get_module(model, bn_path)
        except Exception:
            #  Skip if module doesn't exist (shouldn't happen)
            continue

        #  Build state dict keys (handle Sequential wrapper)
        # Sequential layers have ".0" in their path, direct layers don't
        conv_w_key = f"{conv_path}.0.weight" if isinstance(seq_or_conv, nn.Sequential) else f"{conv_path}.weight"
        conv_b_key = f"{conv_path}.0.bias"   if isinstance(seq_or_conv, nn.Sequential) else f"{conv_path}.bias"
        bn_w_key   = f"{bn_path}.weight"
        bn_b_key   = f"{bn_path}.bias"
        bn_rm_key  = f"{bn_path}.running_mean"
        bn_rv_key  = f"{bn_path}.running_var"

        #  Check if conv dimensions need restoration
        # Compare current dimensions with snapshot dimensions
        if conv_w_key in snapshot_state:
            exp_w = snapshot_state[conv_w_key]
            exp_Cout, exp_Cin = int(exp_w.shape[0]), int(exp_w.shape[1])

            need_rebuild = (getattr(conv, "out_channels", None) != exp_Cout) or \
                           (getattr(conv, "in_channels", None)  != exp_Cin)

            if need_rebuild:
                # Build a new Conv2d with snapshot channel dims but same hyperparams
                new_conv = nn.Conv2d(
                    in_channels=exp_Cin,
                    out_channels=exp_Cout,
                    kernel_size=conv.kernel_size,
                    stride=conv.stride,
                    padding=conv.padding,
                    dilation=conv.dilation,
                    groups=conv.groups if conv.groups == 1 or conv.groups == exp_Cin else 1,  # safety
                    bias=(conv.bias is not None),
                    padding_mode=conv.padding_mode,
                    device=device,
                    dtype=conv.weight.dtype,
                )

                # Replace in the model (preserve any siblings like ChannelGate)
                parent, name = _get_parent_and_name(model, conv_path)
                if isinstance(seq_or_conv, nn.Sequential):
                    rest = list(seq_or_conv)[1:]  # keep everything after conv (e.g., ChannelGate)
                    setattr(parent, name, nn.Sequential(new_conv, *rest))
                else:
                    setattr(parent, name, new_conv)

                conv = new_conv  # update handle

            else:
                # Ensure Param tensors have correct shapes (rare edge case)
                if tuple(conv.weight.shape) != tuple(exp_w.shape):
                    conv.weight = nn.Parameter(torch.empty_like(exp_w, device=device, dtype=exp_w.dtype))
                if (conv.bias is not None) and (conv_b_key in snapshot_state):
                    if conv.bias.shape != snapshot_state[conv_b_key].shape:
                        conv.bias = nn.Parameter(torch.empty_like(snapshot_state[conv_b_key], device=device, dtype=conv.bias.dtype))

            # --- Make sure ChannelGate buffer matches Cout ---
            try:
                gate = _get_gate_by_conv_path(model, conv_path)
                if gate.mask.shape[1] != int(exp_w.shape[0]):
                    gate.mask = torch.ones((1, int(exp_w.shape[0]), 1, 1), device=device, dtype=gate.mask.dtype)
            except Exception as e:
                print(f"  Skipping ChannelGate restore for {conv_path}: {e}")

        # --- Restore BN tensors/num_features ---
        if bn_w_key in snapshot_state:
            exp_bn_w = snapshot_state[bn_w_key]
            exp_nf = int(exp_bn_w.shape[0])
            if getattr(bn, "num_features", None) != exp_nf:
                bn.num_features = exp_nf
                bn.weight = nn.Parameter(torch.empty_like(exp_bn_w, device=device, dtype=exp_bn_w.dtype))
                if (bn_b_key in snapshot_state) and (bn.bias is not None):
                    bn.bias = nn.Parameter(torch.empty_like(snapshot_state[bn_b_key], device=device, dtype=bn.bias.dtype))
                if bn_rm_key in snapshot_state:
                    bn.running_mean = torch.empty_like(snapshot_state[bn_rm_key], device=device, dtype=bn.running_mean.dtype)
                if bn_rv_key in snapshot_state:
                    bn.running_var  = torch.empty_like(snapshot_state[bn_rv_key], device=device, dtype=bn.running_var.dtype)

    # --- Linear layer restore remains as you had it ---
    try:
        lin1 = model.classifier[LINEAR_INDEX]
        lin1_w_key = f"classifier.{LINEAR_INDEX}.weight"
        lin1_b_key = f"classifier.{LINEAR_INDEX}.bias"
        if lin1_w_key in snapshot_state:
            exp_w = snapshot_state[lin1_w_key]
            exp_out, exp_in = int(exp_w.shape[0]), int(exp_w.shape[1])
            if lin1.in_features != exp_in or lin1.out_features != exp_out:
                new_lin1 = nn.Linear(exp_in, exp_out, bias=(lin1_b_key in snapshot_state)).to(device)
                model.classifier[LINEAR_INDEX] = new_lin1
    except Exception as e:
        print(f"⚠️ [Rollback] Failed to restore Linear layer: {e}")


@torch.no_grad()
def sync_all_channelgates(model, layer_specs):
    """
    Ensures ALL ChannelGate masks match their corresponding Conv out_channels.
    Call this before any compiled evaluation.
    """
    for spec in layer_specs:
        conv_path = spec["conv"]
        try:
            gate = _get_gate_by_conv_path(model, conv_path)
            conv = get_conv_module(model, conv_path)
            C = conv.out_channels

            if gate.mask.shape[1] != C:
                with torch.no_grad():
                    gate.mask = torch.ones(1, C, 1, 1, device=gate.mask.device)
                    print(f"[sync] Resized ChannelGate: {C} channels at {conv_path}")
        except Exception as e:
            print(f"⚠️ [sync] Failed at {conv_path}: {e}")



