# Eval helpers
# ----------------------------
@torch.no_grad()
def bn_recalibrate_from_cache(model, X_cache, iters=2048):
    was_training = model.training

    # Snapshot Dropout modes so we can force them to eval during BN refresh
    saved_dropout_modes = []  # (module, was_training_bool)
    # Snapshot BN momenta so we can restore after calibration
    saved_bn_momenta = []     # (bn_module, original_momentum)

    for m in model.modules():
        if isinstance(m, (nn.Dropout, nn.Dropout2d, nn.Dropout3d,
                          nn.AlphaDropout, nn.FeatureAlphaDropout)):
            saved_dropout_modes.append((m, m.training))
        if isinstance(m, (nn.BatchNorm1d, nn.BatchNorm2d, nn.BatchNorm3d)):
            saved_bn_momenta.append((m, m.momentum))
            m.momentum = BN_MOMENTUM  # temporary override for recalibration

    # BN needs train mode to update running stats; keep the rest deterministic
    model.train()
    for m, _ in saved_dropout_modes:
        m.eval()

    # Run forward passes to refresh BN stats
    bs = T.BATCH_SIZE_EVAL if hasattr(T, "BATCH_SIZE_EVAL") else 512
    seen = 0
    # --- Use new device-aware cache ---
    device = next(model.parameters()).device

    while seen < min(iters, X_cache.size(0)):
        xb = X_cache[seen:seen+bs].to(device, non_blocking=True)
        _ = FWD_PROBE(xb)  # no grad; just update BN buffers
        seen += xb.size(0)

    # Restore BN momenta exactly
    for bn, mom in saved_bn_momenta:
        bn.momentum = mom

    # Restore Dropout modes
    for m, was_m_training in saved_dropout_modes:
        m.train(was_m_training)

    # Restore model mode
    if not was_training:
        model.eval()

# Safety contexts + memory helpers
# ----------------------------
@contextmanager
def _temporarily_uncompiled_eval():
    """Run with uncompiled forward to avoid Dynamo recompiles during grad."""
    global FWD_EVAL
    old = FWD_EVAL
    FWD_EVAL = _raw_forward
    try:
        yield
    finally:
        FWD_EVAL = old

@contextmanager
def _noninplace_activations(model):
    """Temporarily set inplace=False for ReLU/LeakyReLU to avoid view+inplace grad issues."""
    mods = []
    for m in model.modules():
        if isinstance(m, (nn.ReLU, nn.LeakyReLU)) and getattr(m, "inplace", False):
            mods.append((m, m.inplace)); m.inplace = False
    try:
        yield
    finally:
        for m, val in mods: m.inplace = val

