def _clear_cuda():
    if torch.cuda.is_available():
        torch.cuda.synchronize(); torch.cuda.empty_cache()

def _maybe_slice_for_scoring(X, y):
    max_samples = int(CONFIG.get("TAYLOR_MAX_SAMPLES", X.size(0)))
    if X.size(0) > max_samples:
        return X[:max_samples], y[:max_samples]
    return X, y

def _downsample_spatial(x, max_hw=CONFIG.get("HRANK_MAX_HW", 4096)):
    if not isinstance(x, torch.Tensor) or x.dim() != 4: return x
    N, C, H, W = x.shape
    if H*W <= max_hw: return x
    stride = int(math.ceil(math.sqrt((H*W)/max_hw)))
    return x[:, :, ::stride, ::stride].contiguous()


