# Alignment Sweep Functions
# =========================

def _prune_layer_alignment(spec: Dict, count: int) -> bool:
    """
    Prune count filters from a layer using existing infrastructure.

    REQUIREMENT 40: Alignment Sweep Structural Rollback Fix
    This function implements two-step rollback to handle guard violations:
    1. restore_model_structure_from_snapshot() - Rebuilds model architecture
    2. model.load_state_dict() - Loads weights into restored structure
    3. Synchronizes channel_tracker and ChannelGate masks

    This prevents RuntimeError from dimension mismatches when rolling back
    after prune_conv_block_and_linear_() has modified the model structure.

    Note: If ALIGN_DISABLE_EARLY_LOCK is True, this function ignores
    the early_locked flag, allowing alignment of B1-B3 layers even after
    early-lock was triggered in main pruning.

    Args:
        spec: Layer specification dict with 'conv', 'bn', 'pool' keys
        count: Number of filters to prune

    Returns:
        True if successful, False if guards violated
    """
    global early_locked, last_good_model_state, structural_ledger

    conv_path = spec["conv"]
    bn_path = spec["bn"]
    pool_path = spec["pool"]

    # Temporarily disable early-lock if configured for alignment
    # For soft-lock: save and clear the entire dictionary
    original_early_locked = early_locked.copy()
    if T.ALIGN_DISABLE_EARLY_LOCK:
        early_locked.clear()

    # 1. Score filters using BN gamma (simple and effective)
    conv = get_conv_module(model, conv_path)
    bn = get_module(model, bn_path)
    scores = torch.abs(bn.weight.data)  # |gamma| as importance

    # 2. Select lowest-scoring filters
    indices_to_drop = torch.argsort(scores)[:count].tolist()

    # 3. Calculate keep indices and target channels
    C = conv.out_channels
    floor_ch = channel_tracker.floors.get(conv_path, 0)
    target_channels = max(floor_ch, C - count)  # Compute BEFORE edit for safe logging
    all_indices = set(range(C))
    keep_indices = sorted(list(all_indices - set(indices_to_drop)))

    # 4. Save snapshot
    snapshot = copy.deepcopy(model.state_dict())
    acc_before, per_class_before, N_per_class_before = quick_acc_and_perclass_on_cache(X_eval_active, y_eval_active, unique_mask_eval, T.BATCH_SIZE_EVAL)

    # 5. Prune using existing function
    try:
        prune_conv_block_and_linear_(
            model, DEVICE, conv_path, bn_path, pool_path,
            keep_indices, sequential_loader
        )

        # Sync channel gates
        sync_all_channelgates(model, layer_specs)

        # Update channel tracker
        channel_tracker.sync_with_model(model, layer_specs)

        # Invalidate caches for edited layer and all downstream dependents
        _invalidate_layer_and_dependents(conv_path, layer_specs, cache_manager)

    except Exception as e:
        print(f"  ✗ Pruning failed: {e}")
        print(f"      Layer: {conv_path}, Target: {target_channels} channels")
        # REQUIREMENT 40: Two-step rollback (structure + weights)
        try:
            restore_model_structure_from_snapshot(model, snapshot, DEVICE)
            model.load_state_dict(snapshot, strict=True)
            channel_tracker.sync_with_model(model, layer_specs)
            sync_all_channelgates(model, layer_specs)
            _invalidate_layer_and_dependents(conv_path, layer_specs, cache_manager)
        except Exception as rollback_error:
            print(f"  ❌ Rollback failed: {rollback_error}")
            import traceback
            traceback.print_exc()
        finally:
            # Restore original early-lock state
            if T.ALIGN_DISABLE_EARLY_LOCK:
                early_locked.clear()
                early_locked.update(original_early_locked)
        return False

    # 6. BN recalibration
    bn_recalibrate_from_cache(model, X_bn_fixed, iters=T.BN_MINI_ITERS)

    # 7. Check guards
    acc_after, per_class_after, N_per_class_after = quick_acc_and_perclass_on_cache(X_eval_active, y_eval_active, unique_mask_eval, T.BATCH_SIZE_EVAL)

    step_drop = acc_before - acc_after

    # CLASS-AWARE FIX: Use relative/error-budget guard instead of absolute threshold
    class_guard_fail, worst_class, class_guard_details = check_per_class_guard(
        per_class_before, per_class_after, N_per_class_after,
        rel_max=T.STEP_CLASS_REL_MAX,
        N_min=T.GUARD_N_MIN,
        err_budget_pct=T.GUARD_ERR_BUDGET_PCT
    )

    # Check step gates (overall accuracy + class-aware guard)
    if step_drop > T.STEP_ACC_MAX or class_guard_fail:
        # REQUIREMENT 40: Two-step rollback (structure + weights)
        try:
            print(f"  ⚠️  Step guard violated")
            print(f"      Acc drop: {step_drop:.4f} (max: {T.STEP_ACC_MAX:.4f})")
            if class_guard_fail:
                print(f"      Class guard: {class_guard_details}")
            print(f"      Layer: {conv_path}, Target: {target_channels} channels")
            print(f"  🔄 Restoring model structure from snapshot...")
            restore_model_structure_from_snapshot(model, snapshot, DEVICE)
            print(f"  🔄 Loading weights from snapshot...")
            model.load_state_dict(snapshot, strict=True)
            print(f"  🔄 Synchronizing channel tracker...")
            channel_tracker.sync_with_model(model, layer_specs)
            print(f"  🔄 Synchronizing ChannelGate masks...")
            sync_all_channelgates(model, layer_specs)
            print(f"  🔄 Invalidating caches for rolled-back layer and dependents...")
            _invalidate_layer_and_dependents(conv_path, layer_specs, cache_manager)
            print(f"  ✓ Successfully rolled back to snapshot")
        except Exception as rollback_error:
            print(f"  ❌ Rollback failed: {rollback_error}")
            import traceback
            traceback.print_exc()
        finally:
            # Restore original early-lock state
            if T.ALIGN_DISABLE_EARLY_LOCK:
                early_locked.clear()
                early_locked.update(original_early_locked)
        return False

    # Check cumulative gates
    per0_map = trajectory[0]["per"]
    cumulative_drop = acc0 - acc_after

    # CLASS-AWARE FIX: Use relative/error-budget guard for cumulative check
    cum_class_guard_fail, cum_worst_class, cum_class_guard_details = check_per_class_guard(
        per0_map, per_class_after, N_per_class_after,
        rel_max=T.CUM_CLASS_REL_MAX,
        N_min=T.GUARD_N_MIN,
        err_budget_pct=T.GUARD_ERR_BUDGET_PCT
    )

    if cumulative_drop > T.CUM_ACC_MAX or cum_class_guard_fail:
        # REQUIREMENT 40: Two-step rollback (structure + weights)
        try:
            print(f"  ⚠️  Cumulative guard violated")
            print(f"      Acc drop: {cumulative_drop:.4f} (max: {T.CUM_ACC_MAX:.4f})")
            if cum_class_guard_fail:
                print(f"      Class guard: {cum_class_guard_details}")
            print(f"      Layer: {conv_path}, Target: {target_channels} channels")
            print(f"  🔄 Restoring model structure from snapshot...")
            restore_model_structure_from_snapshot(model, snapshot, DEVICE)
            print(f"  🔄 Loading weights from snapshot...")
            model.load_state_dict(snapshot, strict=True)
            print(f"  🔄 Synchronizing channel tracker...")
            channel_tracker.sync_with_model(model, layer_specs)
            print(f"  🔄 Synchronizing ChannelGate masks...")
            sync_all_channelgates(model, layer_specs)
            print(f"  🔄 Invalidating caches for rolled-back layer and dependents...")
            _invalidate_layer_and_dependents(conv_path, layer_specs, cache_manager)
            print(f"  ✓ Successfully rolled back to snapshot")
        except Exception as rollback_error:
            print(f"  ❌ Rollback failed: {rollback_error}")
            import traceback
            traceback.print_exc()
        finally:
            # Restore original early-lock state
            if T.ALIGN_DISABLE_EARLY_LOCK:
                early_locked.clear()
                early_locked.update(original_early_locked)
        return False

    # 8. Update trajectory
    trajectory.append({
        "stage": f"Align {conv_path}",
        "acc": acc_after,
        "per": per_class_after
    })

    # 9. Update structural ledger (defensive initialization)
    channels_after = get_conv_module(model, conv_path).out_channels

    # Defensive: Initialize ledger structure if needed
    if 'shape_lineage' not in structural_ledger:
        structural_ledger['shape_lineage'] = {}
    if 'checkpoints' not in structural_ledger:
        structural_ledger['checkpoints'] = []
    if 'initial_shapes' not in structural_ledger:
        structural_ledger['initial_shapes'] = {}

    # Initialize this layer's lineage if needed
    if conv_path not in structural_ledger['shape_lineage']:
        structural_ledger['shape_lineage'][conv_path] = []

    # Append checkpoint
    structural_ledger['checkpoints'].append({
        'stage': 'alignment',
        'layer': conv_path,
        'before': C,
        'after': channels_after,
        'kept_indices': keep_indices,
        'dropped_count': count
    })

    # Append to lineage
    structural_ledger['shape_lineage'][conv_path].append({
        'stage': 'alignment',
        'channels': channels_after,
        'kept_indices': keep_indices
    })

    # 10. CRITICAL: Update last_good_model_state after full commit pipeline
    last_good_model_state = copy.deepcopy(model.state_dict())

    # 11. Mark graph as dirty - needs recompile before next eval
    global graph_dirty
    graph_dirty = True

    # Restore original early-lock state before returning success
    if T.ALIGN_DISABLE_EARLY_LOCK:
        early_locked.clear()
        early_locked.update(original_early_locked)

    print(f"  ✓ Guards passed (acc: {acc_after:.4f}, drop: {step_drop:.4f})")
    return True


def _alignment_sweep_simple():
    """
    Simplified alignment sweep that processes each target layer individually.

    Aligns early/mid layers (B3, B2, B1) to kernel-friendly plateau sizes
    after main pruning completes. Uses existing pruning infrastructure.
    """
    global PHASE4_WHITELIST, PHASE4_MICRO_CHUNK, trajectory, channel_tracker

    # Start alignment timer (with try/finally to handle early return)
    sw.go("alignment_total_s")
    try:
        # 1. Save original configuration
        original_whitelist = PHASE4_WHITELIST.copy() if PHASE4_WHITELIST else set()
        original_chunk = PHASE4_MICRO_CHUNK

        # 2. Log start
        _bar("PHASE A.5: Alignment Sweep", width=70)
        print(f"[Alignment] Target plateaus: {T.ALIGN_TARGETS}")

        # 3. Get current channel counts
        channels_before = {s["conv"]: get_conv_module(model, s["conv"]).out_channels
                          for s in layer_specs}

        # 4. Build alignment plan
        alignment_plan = []
        for layer, target in T.ALIGN_TARGETS.items():
            current = channels_before.get(layer, 0)
            floor = T.HARD_FLOORS.get(layer, 0)

            # Align if current > target, but respect floor as minimum
            if current > target:
                # Clamp target to floor if it's below
                effective_target = max(target, floor)
                if current > effective_target:
                    gap = current - effective_target
                    alignment_plan.append((layer, current, effective_target, gap))
                    if effective_target != target:
                        print(f"[Alignment] {layer}: {current} → {effective_target} (target {target} clamped to floor {floor})")
                    else:
                        print(f"[Alignment] {layer}: {current} → {target} (gap: {gap})")
                else:
                    print(f"[Alignment] {layer}: {current} (already at floor {floor})")
            else:
                print(f"[Alignment] {layer}: {current} (already at/below target {target})")

        if not alignment_plan:
            print("[Alignment] No work needed. Skipping sweep.")
            return

        # 5. Process each layer individually
        for layer_path, current, target, gap in alignment_plan:
            print(f"\n[Alignment] Processing {layer_path}...")

            # Find layer spec
            spec = next((s for s in layer_specs if s["conv"] == layer_path), None)
            if not spec:
                print(f"[Alignment] Layer {layer_path} not found in layer_specs, skipping")
                continue

            # Run limited rounds for this layer
            for micro_round in range(1, 4):  # Max 3 rounds per layer
                # Check if we've reached target
                current_channels = get_conv_module(model, layer_path).out_channels
                if current_channels <= target:
                    print(f"[Alignment] {layer_path} reached target {target}")
                    break

                # Calculate how many to prune this round (max 8 at a time)
                remaining_gap = current_channels - target
                prune_count = min(8, remaining_gap)

                print(f"[Alignment] Round {micro_round}: {current_channels} → {current_channels - prune_count}")

                # Prune using existing infrastructure
                success = _prune_layer_alignment(spec, prune_count)

                if not success:
                    print(f"[Alignment] Guards violated for {layer_path}, stopping alignment")
                    break

        # 6. Restore original configuration
        PHASE4_WHITELIST = original_whitelist
        PHASE4_MICRO_CHUNK = original_chunk

        # 7. Log final results
        channels_after = {s["conv"]: get_conv_module(model, s["conv"]).out_channels
                         for s in layer_specs}
        print("\n[Alignment] Sweep complete. Results:")
        for layer, _, target, _ in alignment_plan:
            before = channels_before.get(layer, 0)
            after = channels_after.get(layer, 0)
            delta = before - after
            status = "✓" if after <= target else "⚠"
            print(f"  {status} {layer}: {before} → {after} (target: {target}, pruned: {delta})")

    finally:
        # Stop alignment timer (always executed, even on early return)
        sw.stop()
        timing["alignment_total_s"] = sw.t.get("alignment_total_s", 0.0)


# Global Pruning
# =========================
_bar(f"Global Pruning ({T.GLOBAL_ROUNDS} Rounds)", width=70)

# Start Phase A total timer (manual timing to avoid nesting issues)
t_phaseA_start = time.perf_counter()

round_failed = False
#  Track plateau hits for deferred commit
plateau_hit_this_round = False
counts_at_round_start = {}

# ═══════════════════════════════════════════════════════════════════════════
# END OF CELL 3C.3 — PHASE A SETUP
# ═══════════════════════════════════════════════════════════════════════════

# ═══════════════════════════════════════════════════════════════════════════
# Phase 4 Cell 3C.4 — MAIN PRUNING LOOP
# Lines: ~1043 lines (largest sub-cell in Cell 3C)
# Dependencies: ALL previous cells
# Exports: Executes main pruning algorithm, modifies global model state
# Contents:
#   - Main multi-round pruning loop (CANNOT BE SPLIT):
#     * Round initialization
#     * Chunk processing (per-layer iteration)
#     * Merge selection (HCProximity.pop_best)
#     * Benefit evaluation (Wilson CI early-exit)
#     * Guard checks (step/cumulative/latency)
#     * Rollback logic (on guard failure)
#     * BN recalibration (deferred)
#     * Trajectory tracking
#     * Progress reporting
#     * Plateau commit logic
#     * Active set refresh
# ⚠️ CRITICAL: This is the main pruning algorithm. Do not split further.
# ═══════════════════════════════════════════════════════════════════════════

for round_idx in range(1, T.GLOBAL_ROUNDS + 1):
    if round_failed: break

    assert 1 <= round_idx <= T.GLOBAL_ROUNDS, f"Invalid round_idx: {round_idx} (expected 1-{T.GLOBAL_ROUNDS})"

    # Start round timer (manual timing to avoid nesting with sw-based timers)
    t_round_start = time.perf_counter()

    plateau_hit_this_round = False
    counts_at_round_start = {s["conv"]: get_conv_module(model, s["conv"]).out_channels for s in layer_specs}

    lat_guard_fail_count = 0
    last_chunk_size_for_lat_guard = current_chunk_size

    # Reset score caches at round start but keep shape_cache warm since H×W
    # does not change when pruning channels.
    cache_manager.invalidate_scores()

    # Periodic active set refresh to adapt to changing model characteristics
    active_refresh_interval = int(getattr(T, "ACTIVE_REFRESH_EVERY", 5))
    if active_refresh_interval > 0 and round_idx % active_refresh_interval == 0:
        sw.go(f"active_refresh_s_R{round_idx}")
        print(f"  [Active Set] Periodic refresh (round {round_idx}, interval: {active_refresh_interval})")
        X_eval_active, y_eval_active, unique_mask_eval, drawn_per_class_eval, unique_per_class_eval = \
            build_eval_and_bn_caches(X_eval_full, y_eval_full, T.EVAL_BATCH_LIMIT, n_hard_pct=0.25)
        X_bn_fixed, y_bn_fixed, unique_mask_bn, drawn_per_class_bn, unique_per_class_bn = \
            build_eval_and_bn_caches(X_eval_full, y_eval_full, T.BN_RECAL_SAMPLES, n_hard_pct=0.25)
        print(f"  [Active Set] Refreshed with {X_eval_active.size(0)} samples ({unique_mask_eval.sum().item()} unique)")
        sw.stop(); timing[f"active_refresh_s_R{round_idx}"] = sw.t.get(f"active_refresh_s_R{round_idx}", 0.0)

    # Force eager mode (disable compiled graph during structure mutation)
    global FWD_EVAL
    saved_FWD_EVAL = FWD_EVAL
    try:
        FWD_EVAL = _raw_forward
    except Exception as e:
        print(f"⚠️ Failed to set eager mode: {e}")
        FWD_EVAL = saved_FWD_EVAL

    _bar(f"GLOBAL ROUND {round_idx} / {T.GLOBAL_ROUNDS}", "─", 70)

    params_total_pre = sum(p.numel() for p in model.parameters())
    channel_tracker.sync_with_model(model, layer_specs)
    channels_pre = channel_tracker.current.copy()

    # Soft-lock management: decrement cooldowns and unlock expired layers
    global early_locked
    layers_to_unlock = []
    for layer_name in list(early_locked.keys()):
        early_locked[layer_name] -= 1
        if early_locked[layer_name] <= 0:
            layers_to_unlock.append(layer_name)

    for layer_name in layers_to_unlock:
        del early_locked[layer_name]
        print(f"  [Soft-Lock] {layer_name} cooldown expired, now unlocked")

    prunable_layers = [
        spec["conv"] for spec in layer_specs
        if channel_tracker.get_remaining(spec["conv"]) > 0
    ]
    active_layers = [
        layer for layer in prunable_layers
        if layer not in early_locked or early_locked[layer] <= 0
    ]

    # Unlock cycle: clear all locks if active set is empty but prunable layers remain
    if not active_layers and prunable_layers:
        print(f"  🔓 [Unlock Cycle] Active set empty but {len(prunable_layers)} layers have headroom.")
        print(f"     Clearing soft-locks: {list(early_locked.keys())}")
        early_locked.clear()
        active_layers = prunable_layers
        print(f"     Active set rebuilt: {len(active_layers)} layers now available")

    reporter.begin_round(round_idx)

    # Phase-4 gating: activate whitelist and switch to micro-chunks if needed
    phase4_layers_live = _phase4_live_layers(
        channels_pre,
        getattr(T, "HARD_FLOORS", {})
    )
    phase4_active_round = bool(PHASE4_WHITELIST) and bool(phase4_layers_live)

    if phase4_active_round:
        current_chunk_size = max(1, PHASE4_MICRO_CHUNK)
        print(f"[Phase-4] Active this round. Whitelist={sorted(phase4_layers_live)} | micro-chunk size={current_chunk_size}")
    else:
        current_chunk_size = int(getattr(T, "CHUNK_SIZE", 4))


    channels_remaining_total = sum(channels_pre.values())

    if channels_remaining_total == 0:
        print("[Global] No channels remaining. Stopping.")
        break

    print("[Global] Scoring all filters...")

    # Skip layers at floor or on cooldown (budget calculation still uses full headroom)
    scoring_specs = []
    skipped_layers = []
    early_locked_layers = []
    for spec in layer_specs:
        conv_path = spec["conv"]
        current_ch = channel_tracker.current.get(conv_path, get_conv_module(model, conv_path).out_channels)
        floor_ch = channel_tracker.floors.get(conv_path, 0)

        if current_ch <= floor_ch:
            skipped_layers.append(conv_path)
        elif conv_path in early_locked and early_locked[conv_path] > 0:
            early_locked_layers.append((conv_path, early_locked[conv_path]))
        else:
            scoring_specs.append(spec)

    if skipped_layers:
        print(f"  [Floor-hit] Skipping {len(skipped_layers)} layers at floor: {skipped_layers}")
    if early_locked_layers:
        locked_info = ", ".join([f"{layer}(cooldown={cd})" for layer, cd in early_locked_layers])
        print(f"  [Soft-Lock] Skipping {len(early_locked_layers)} locked layers: {locked_info}")

    sw.go(f"global_score_s_R{round_idx}")

    #   A. Taylor (Fix #2, #10)
    taylor = _taylor_scores(X_eval_active, y_eval_active, scoring_specs) if _scorer_enabled("taylor") else {}
    #   B. HRank
    hrank = {}
    if _scorer_enabled("hrank"):
        for spec in scoring_specs:  #  Use filtered specs
            if channels_pre[spec["conv"]] > 0:
                hrank[spec["conv"]] = collect_hrank_streaming(spec["conv"], spec["bn"])
    #   C. BN-Gamma
    gamma = _bn_gamma_scores(scoring_specs) if _scorer_enabled("gamma") else {}  #  Use filtered specs

    #   Normalize (Fix #4)
    #   Use *global* normalization across all layers to preserve cross-layer
    #   comparability for the global ranking step, instead of per-layer scaling
    #   which collapses each layer independently to [0,1].
    comp_scores = {}
    if taylor: comp_scores["taylor"] = _normalize_global_for_pruning(taylor)
    if hrank:  comp_scores["hrank"]  = _normalize_global_for_pruning(hrank)
    if gamma:  comp_scores["gamma"]  = _normalize_global_for_pruning(gamma)

    #  Fuse weighted scorers into one per-layer vector
    fused_scores = _fuse_scores_per_layer(comp_scores, GLOBAL_WEIGHTS_LOCAL)

    #  ILR INTEGRATION — ENTRY (optional replace or fuse)
    use_ilr = bool(getattr(T, "ILR_ENABLE", False))
    if use_ilr:
        # Restrict ILR to layers that are actually live in Phase-4 for this round.
        # This avoids computing ILR components for layers we never prune (e.g.,
        # internal VGG convs with mismatched pooled channel counts).
        ilr_target_layers = phase4_layers_live if phase4_active_round else [
            spec["conv"] for spec in scoring_specs
        ]
        ilr = _ilr_scores(
            layer_specs,
            use_hrank=bool(getattr(T, "ILR_COMPONENTS", {}).get("hrank", True)),
            target_layers=set(ilr_target_layers),
        )
        # If set to replace (or if the gradient-based scorers are disabled/empty), use ILR alone.
        replace = bool(getattr(T, "ILR_REPLACE_GLOBAL", True))
        no_global = (not taylor) and (not hrank) and (not gamma)
        if replace or no_global:
            fused_scores = ilr
        else:
            # Fuse ILR into existing components with a neutral weight of 1.0
            # (You can also expose a GLOBAL_WEIGHTS_LOCAL["ilr"] if you want)
            comp_scores["ilr"] = ilr
            fused_scores = _fuse_scores_per_layer(comp_scores, {**GLOBAL_WEIGHTS_LOCAL, "ilr": 1.0})
    # ILR INTEGRATION — EXIT

    # HEAD COUPLING — FUSE ENTRY (conv score + Linear1 columns)
    if (getattr(T, "LINEAR1_SLICE", False)) \
      and getattr(HEAD_T, "HEAD_ENABLE", True):
        if (head_conv in fused_scores) and HEAD_INFO.get("H") and HEAD_INFO.get("W"):
            try:
                C_head = len(fused_scores[head_conv])
                lin_ch = _linear1_channel_scores(HEAD_INFO["H"], HEAD_INFO["W"],
                                                agg=getattr(HEAD_T, "HEAD_AGG", "l1_mean"))
                if lin_ch.numel() == C_head:
                    w = float(getattr(HEAD_T, "HEAD_FUSE_W", 0.70))
                    fused_scores[head_conv] = (
                        w * fused_scores[head_conv].to(torch.float32) +
                        (1.0 - w) * lin_ch.to(torch.float32)
                    )
                    # keep it as [0,1] per-layer
                    fused_scores[head_conv] = _normalize_for_pruning({head_conv: fused_scores[head_conv]})[head_conv]
            except Exception as e:
                print(f"⚠️ [HEAD] Fuse skipped: {e}")
    # HEAD COUPLING — FUSE EXIT

    #   Benefit (FLOPs/params saved)
    # benefit = _benefit_per_channel(layer_specs)
    # benefit_norm = _normalize_for_pruning(benefit)

    #  ENTRY: Economics-aware benefit + alignment & layer prior
    if bool(getattr(T, "USE_ECON_FIX", True)):
        # a) Economics-aware benefit
        benefit_econ = _benefit_per_channel_econ(
            layer_specs,
            alpha=float(getattr(T, "ALPHA_NEXT", 0.25)),
            beta=float(getattr(T, "BETA_LINEAR", 0.0))  # stays 0.0 until Phase-3
        )
        # b) Alignment bonus (γ · 1/steps_to_plateau)
        align = _alignment_hint(
            layer_specs,
            channels_pre=channels_pre,
            max_steps=int(getattr(T, "ALIGN_MAX_STEPS", 8))
        )
        gamma = float(getattr(T, "GAMMA_ALIGN", 0.10))
        # c) Late-layer prior
        layer_prior = dict(getattr(T, "LAYER_PRIOR", {}))

        # Combine into effective "benefit" used for tie-break
        benefit = {}
        for spec in layer_specs:
            k = spec["conv"]
            b_e = benefit_econ.get(k)
            if b_e is None:
                continue
            b_eff = b_e.clone()
            if k in align:
                b_eff = b_eff + gamma * align[k]
            # multiply entire layer by prior (scalar)
            if k in layer_prior:
                b_eff = b_eff * float(layer_prior[k])
            benefit[k] = b_eff
    else:
        # Fallback to original behavior if econ disabled
        benefit = _benefit_per_channel(layer_specs)
    #  PHASE-1 EXIT


    sw.stop(); timing[f"global_score_s_R{round_idx}"] = sw.t.get(f"global_score_s_R{round_idx}", 0.0)

    # Start selection timer
    sw.go(f"selection_s_R{round_idx}")

    # Build Global Rank List
    #  Per-layer sorting with k-way merge for 40-50% faster rank list

    # Build and sort per-layer lists independently
    per_layer_lists = []
    for spec in layer_specs:
        conv_path = spec["conv"]
        scores_l = fused_scores.get(conv_path)
        benefit_l = benefit.get(conv_path) # Use the raw, non-normalized benefit
        if scores_l is None or benefit_l is None: continue
        C = channels_pre[conv_path]
        if C != len(scores_l): continue

        layer_list = []
        for filter_idx in range(C):
            s = scores_l[filter_idx].item()
            b = benefit_l[filter_idx].item()
            #  Store benefit as NEGATIVE for correct sorting
            # We negate benefit here so that ascending sort on tuple gives us:
            # 1. Lowest score first (least important filters)
            # 2. Within same score, highest benefit first (most economical to prune)
            layer_list.append( (s, -b, conv_path, filter_idx) )

        # Sort this layer's list independently
        layer_list.sort(key=lambda x: (x[0], x[1]))
        per_layer_lists.append(layer_list)

    # K-way merge using heap for efficient merging of sorted lists
    # This is O(N log K) where N is total filters and K is number of layers
    # Much faster than sorting all filters together O(N log N) when K << N
    global_rank_list = []

    # Initialize heap with first element from each layer
    merge_heap = []
    for layer_idx, layer_list in enumerate(per_layer_lists):
        if layer_list:
            # Heap entry: (score, -benefit, layer_idx, position_in_layer)
            entry = layer_list[0]
            heapq.heappush(merge_heap, (entry[0], entry[1], layer_idx, 0, entry[2], entry[3]))

    # Extract minimum and add next from same layer
    while merge_heap:
        score, neg_benefit, layer_idx, pos, conv_path, filter_idx = heapq.heappop(merge_heap)
        global_rank_list.append((score, neg_benefit, conv_path, filter_idx))

        # Add next element from the same layer if available
        next_pos = pos + 1
        if next_pos < len(per_layer_lists[layer_idx]):
            next_entry = per_layer_lists[layer_idx][next_pos]
            heapq.heappush(merge_heap, (next_entry[0], next_entry[1], layer_idx, next_pos, next_entry[2], next_entry[3]))

    #  CANDIDATE FILTER (restrict to B4/B5 while active) — ENTRY
    if phase4_active_round:
        # global_rank_list entries are tuples: (score, -benefit, conv_path, filter_idx)
        before = len(global_rank_list)
        global_rank_list = [t for t in global_rank_list if t[2] in set(phase4_layers_live)]
        after = len(global_rank_list)
        if after == 0:
            # Nothing left to prune in whitelist — fall back to full list for this round.
            # We keep micro-chunk size for safety this round.
            print("[Phase-4] Whitelist exhausted this round; falling back to all layers (kept micro-chunk size).")
            global_rank_list = []  # force re-fill from original
            # Rebuild unfiltered list (already sorted) from the copy we still have in scope:
            # If you don't have a saved copy, simply do nothing and keep the 'before' list.
            # Here we simply do nothing because 'global_rank_list' above is already the original.
            # (Comment left intentionally to show the intended behavior.)
            pass
        else:
            print(f"[Phase-4] Shortlisted {after}/{before} candidates from whitelist layers.")
    #  PHASE-4 — CANDIDATE FILTER (restrict to B4/B5 while active) — EXIT


    # Calculate Budget (Global: Independent of Selection Constraints)
    # Compute global headroom across ALL layers (floor-aware)
    # This reflects the model's overall pruning potential, independent of locks/whitelist
    H_global = sum(
        channel_tracker.get_remaining(spec["conv"])
        for spec in layer_specs
    )

    # Budget based ONLY on global headroom (not capped by selection constraints)
    pace = math.ceil(H_global * current_round_pct)
    budget_k = min(max(T.MIN_ABS_BUDGET, pace), T.GLOBAL_MAX_PER_ROUND, len(global_rank_list))

    print(f"  [Budget] H_global={H_global}, pct={current_round_pct*100:.1f}%, pace={pace}, budget={budget_k} "
          f"(min={T.MIN_ABS_BUDGET}, max={T.GLOBAL_MAX_PER_ROUND})")

    # Build Selection Sets (locks/whitelist apply here, NOT to budget)
    # Build eligible layers (have headroom above floor)
    eligible_layers = [
        spec["conv"] for spec in layer_specs
        if channel_tracker.get_remaining(spec["conv"]) > 0
    ]

    # Stop condition: If no eligible layers, all are at floor
    if not eligible_layers:
        print(f"🛑 [STOP] All layers at floor. Proceeding to alignment sweep.")
        break

    # Build active layers (eligible + selectable based on locks/whitelist)
    if phase4_active_round:
        # Apply whitelist first, then check locks
        primary = [
            layer for layer in eligible_layers
            if layer in phase4_layers_live and (layer not in early_locked or early_locked[layer] <= 0)
        ]
        # Fallback: if whitelist is empty, use all eligible unlocked layers
        active_layers = primary if primary else [
            layer for layer in eligible_layers
            if layer not in early_locked or early_locked[layer] <= 0
        ]
    else:
        # Normal mode: just check locks
        active_layers = [
            layer for layer in eligible_layers
            if layer not in early_locked or early_locked[layer] <= 0
        ]

    # Unlock cycle: if active is empty but eligible is not, clear all locks
    early_locked_cleared = False
    if not active_layers and eligible_layers:
        print(f"  🔓 [Unlock Cycle] Active set empty but {len(eligible_layers)} layers have headroom.")
        print(f"     Clearing soft-locks: {list(early_locked.keys())}")
        early_locked.clear()
        active_layers = eligible_layers[:]
        early_locked_cleared = True
        print(f"     Active set rebuilt: {len(active_layers)} layers now available")

    print(f"  [Select] eligible={len(eligible_layers)}, active={len(active_layers)}, unlock_cycle={early_locked_cleared}")

    # Filter global_rank_list by active layers (selection constraints applied here)
    active_set = set(active_layers)
    global_rank_list_filtered = [
        (score, neg_b, conv_path, filter_idx)
        for (score, neg_b, conv_path, filter_idx) in global_rank_list
        if conv_path in active_set
    ]

    if len(global_rank_list_filtered) < len(global_rank_list):
        print(f"  [Filter] Filtered {len(global_rank_list)} → {len(global_rank_list_filtered)} candidates (active layers only)")

    # --- NEW (Two-Stage Shortlist) Picking Logic ---
    # Stage 1: Create the "shortlist" of the least important filters
    #  Use configurable shortlist percentage
    shortlist_q_pct = float(getattr(T, "SHORTLIST_Q_PCT", 0.25))
    # Validate percentage
    if not (0.0 < shortlist_q_pct <= 1.0):
        raise ValueError(f"SHORTLIST_Q_PCT must be between 0 and 1, got {shortlist_q_pct}")

    shortlist_size = max(budget_k, int(len(global_rank_list_filtered) * shortlist_q_pct))
    shortlist_by_score = global_rank_list_filtered[:shortlist_size]

    # Stage 2: From that shortlist, re-sort *only by benefit*
    # Benefit sort direction clarification
    # IMPORTANT: Benefit values are stored as NEGATIVE in global_rank_list
    # Format: (score, -benefit, conv_path, filter_idx)
    #
    # Sorting logic:
    # - x[1] contains -benefit (negative benefit)
    # - Sorting ASCENDING on x[1] means: smallest -benefit first
    # - Smallest -benefit = LARGEST positive benefit
    # - Therefore: sorting ascending picks HIGHEST benefit filters first
    #
    # Example: If benefits are [0.5, 0.8, 0.3], stored as [-0.5, -0.8, -0.3]
    # Ascending sort gives: [-0.8, -0.5, -0.3] → benefits [0.8, 0.5, 0.3] ✓
    # ============================================================

    shortlist_by_benefit = sorted(shortlist_by_score, key=lambda x: x[1])

    print(f"[Global] Stage 1 (Score): Shortlist size {len(shortlist_by_score)} "
          f"({shortlist_q_pct*100:.1f}% of {len(global_rank_list_filtered)}). "
          f"Stage 2 (Benefit): Picking {budget_k} from this list.")

    # Stage 3: Pick from the benefit-sorted shortlist, respecting floors
    # Use ChannelTracker for floor enforcement
    picked_candidates = []
    # Create a temporary snapshot for virtual pruning simulation
    tracker_snapshot = channel_tracker.snapshot()

    # Iterate through our new list, which is pre-sorted by (score) and then (highest benefit)
    for s, neg_b, conv_path, filter_idx in shortlist_by_benefit:

        # Stop once we hit our budget
        if len(picked_candidates) >= budget_k:
            break

        #  Use ChannelTracker.can_prune() for floor validation
        if channel_tracker.can_prune(conv_path, count=1):
            # This filter is safe to prune
            picked_candidates.append((s, conv_path, filter_idx))
            # Virtually prune in tracker to maintain accurate count for subsequent checks
            channel_tracker.prune(conv_path, count=1)

            # Hook A – note intent
            reporter.note_pick(conv_path, 1)

            #  Log pruning decision
            if T.VERBOSE and len(picked_candidates) <= 10:  # Log first 10 only to avoid spam
                benefit = -neg_b  # Convert back from negative
                print(f"  [Prune] {conv_path} filter {filter_idx}: score={s:.6f}, benefit={benefit:.6f}")
        else:
            #  Log floor rejection
            if T.VERBOSE and channel_tracker.get_remaining(conv_path) == 0:  # Log once per layer when floor reached
                current_count = channel_tracker.current.get(conv_path, 0)
                floor = channel_tracker.floors.get(conv_path, 0)
                print(f"  [Skip] {conv_path} filter {filter_idx}: would violate floor "
                      f"(current={current_count}, floor={floor})")

    #  Restore tracker to pre-selection state (picks were virtual)
    # Actual pruning happens later in chunks
    channel_tracker.restore(tracker_snapshot)

    filters_to_prune_this_round = picked_candidates

    #  Comprehensive diagnostics for empty shortlist
    if not filters_to_prune_this_round:
        print("[Global] ⚠️ No filters selected after floor filtering.")
        print(f"  Shortlist size: {len(shortlist_by_benefit)}")
        print(f"  Budget requested: {budget_k}")

        #  Analyze why candidates were rejected per layer using ChannelTracker
        rejected_by_layer = {}
        total_rejected = 0
        for s, neg_b, conv_path, filter_idx in shortlist_by_benefit:
            # Use ChannelTracker for accurate floor checking
            if not channel_tracker.can_prune(conv_path, count=1):
                if conv_path not in rejected_by_layer:
                    rejected_by_layer[conv_path] = {
                        'count': 0,
                        'current': channel_tracker.current.get(conv_path, 0),
                        'floor': channel_tracker.floors.get(conv_path, 0)
                    }
                rejected_by_layer[conv_path]['count'] += 1

        if rejected_by_layer:
            #  Detailed per-layer rejection analysis
            print(f"  Candidates rejected per layer due to floors:")
            total_rejected_count = 0
            for conv_path, info in rejected_by_layer.items():
                total_rejected_count += info['count']
                margin = info['current'] - info['floor']
                print(f"    {conv_path}: {info['count']} candidates rejected "
                      f"(current={info['current']}, floor={info['floor']}, margin={margin})")

            print(f"  Total rejected: {total_rejected_count}/{len(shortlist_by_benefit)}")
            print(f"  Diagnosis: Floors are too aggressive or model is converged.")
            print(f"  Suggestions:")
            print(f"    1. Lower floor values in HARD_FLOORS")
            print(f"    2. Disable floor decay lock (FLOORS_LOCKED=False)")
            print(f"    3. Consider stopping pruning (convergence reached)")
        else:
            #  Shortlist exhaustion diagnosis
            print(f"  Diagnosis: Shortlist exhausted before reaching budget.")
            print(f"  This indicates shortlist is too small for current floors.")
            print(f"  Suggestions:")
            print(f"    1. Increase SHORTLIST_Q_PCT (current: {shortlist_q_pct})")
            print(f"    2. Check if scoring is working correctly")
            print(f"    3. Verify global_rank_list has enough candidates")

        break

    # Stop selection timer
    sw.stop(); timing[f"selection_s_R{round_idx}"] = sw.t.get(f"selection_s_R{round_idx}", 0.0)

    # Process in Chunks
    #  Check for empty filter list
    if len(filters_to_prune_this_round) == 0:
        print(f"[Global] Round {round_idx}: No filters to prune (all at floor or filtered out)")
        continue

    # Validate chunk size to prevent division by zero
    assert current_chunk_size > 0, f"Chunk size must be positive, got: {current_chunk_size}"
    num_chunks = math.ceil(len(filters_to_prune_this_round) / current_chunk_size)
    print(f"[Global] Round {round_idx}: Budget {len(filters_to_prune_this_round)} filters in {num_chunks} chunks of ~{current_chunk_size}.")

    # Start surgery+guards timer for entire chunk loop
    sw.go(f"surgery_guard_s_R{round_idx}")

    # Don't reset early_locked - let it persist across rounds
    # early_locked = False  # REMOVED: This was preventing persistence
    # Once early lock is triggered, it should remain active for all subsequent rounds

    #  Use ChannelTracker for virtual count tracking during chunk processing
    # Take a snapshot at round start for rollback purposes
    round_start_snapshot = channel_tracker.snapshot()

    for chunk_idx in range(num_chunks):
        early_lock_triggered_this_chunk = False
        chunk_start = chunk_idx * current_chunk_size
        chunk_end = (chunk_idx + 1) * current_chunk_size
        #  Validate chunk bounds to prevent index errors
        chunk_end = min(chunk_end, len(filters_to_prune_this_round))
        chunk = filters_to_prune_this_round[chunk_start:chunk_end]
        counts_before_chunk = {s["conv"]: get_conv_module(model, s["conv"]).out_channels for s in layer_specs}

        if not chunk: continue

        prune_map_chunk = {s["conv"]: [] for s in layer_specs}
        healthy_chunk_count = 0

        # --- Check Floors & Health ---
        #  Track health rejections per layer for diagnostics
        health_rejections = {}

        for metric, conv_path, filter_idx in chunk:
            # Skip if layer is soft-locked (cooldown > 0)
            if conv_path in early_locked and early_locked[conv_path] > 0:
                continue

            #  Use ChannelTracker for floor validation
            if not channel_tracker.can_prune(conv_path, count=1):
                continue

            #  Enhanced dispersion check with recovery metrics
            if T.HEALTH_CHECK_ENABLE and not check_dispersion(conv_path, baseline_dispersion, T.HEALTH_MIN_DISPERSION_PCT):
                # Track rejection for diagnostics
                if conv_path not in health_rejections:
                    health_rejections[conv_path] = 0
                health_rejections[conv_path] += 1
                continue

            #  HEAD COUPLING — GUARD ENTRY
            if (getattr(T, "LINEAR1_SLICE", False)) \
              and getattr(HEAD_T, "HEAD_ENABLE", True) and (conv_path == head_conv):
                spec = layer_map.get(conv_path, None)
                if spec and (spec.get("next_conv") is None) and HEAD_INFO.get("H") and HEAD_INFO.get("W"):
                    # Predict Linear1.in_features after dropping this one B5 channel
                    #  Use ChannelTracker for accurate count prediction
                    C_post = channel_tracker.current[conv_path] - 1
                    new_in_cols = C_post * HEAD_INFO["H"] * HEAD_INFO["W"]
                    if new_in_cols < _head_linear_floor_cols():
                        # Skip this candidate — would violate head floor
                        continue
            #  HEAD COUPLING — GUARD EXIT


            prune_map_chunk[conv_path].append(filter_idx)
            #  Update ChannelTracker with virtual prune
            channel_tracker.prune(conv_path, count=1)
            healthy_chunk_count += 1

        if healthy_chunk_count == 0:
            print(f"  > Chunk {chunk_idx+1}/{num_chunks}: No healthy filters. Skipping.")
            continue

        print(f"  > Chunk {chunk_idx+1}/{num_chunks}: Proposing {healthy_chunk_count} filters...")

        # --- Apply Chunk & Mini-Eval ---
        snapshot_chunk = copy.deepcopy(model.state_dict()) # (Fix #7)

        for spec in T.ALT_ORDER:
            filters_to_drop_idx = prune_map_chunk.get(spec["conv"], [])
            if not filters_to_drop_idx: continue

            C_pre_chunk = get_conv_module(model, spec["conv"]).out_channels
            all_indices = set(range(C_pre_chunk))
            survivor_indices = sorted(list(all_indices - set(filters_to_drop_idx)))

            model = prune_conv_block_and_linear_(
                model, DEVICE, spec["conv"], spec["bn"], spec["pool"],
                survivor_indices, sequential_loader
            )

            #  Invalidate cache for pruned layer and downstream layers
            cache_manager.invalidate_layer(spec["conv"], layer_specs)

        #  Sync all ChannelGates after surgery
        sync_all_channelgates(model, layer_specs)

        # Reset torch.compile cache after structural changes
        if compiled_eval and hasattr(torch, "_dynamo"):
            torch._dynamo.reset()

        #  Deferred BN recalibration - only recalibrate when needed
        if bn_recalibrator.should_recalibrate():
            bn_recalibrate_from_cache(model, X_bn_fixed, iters=T.BN_MINI_ITERS)
            bn_recalibrator.mark_recalibrated()
        # else: defer recalibration to reduce overhead

        #  Sync all ChannelGates before evaluation
        sync_all_channelgates(model, layer_specs)

        # Deferred recompilation: Skip recompile during chunks, defer to round end
        # This reduces overhead from N recompiles per round to 1 recompile per round
        # Uncompiled forward is still correct, just slightly slower per chunk
        if graph_dirty and chunk_idx == 0:
            print(f"  [Deferred] Graph dirty, using uncompiled forward (will recompile at round end)")

        # --- Sanity checks before eval ---
        assert isinstance(X_eval_active, torch.Tensor), \
            f"X_eval_active must be tensor, got {type(X_eval_active)}"
        assert isinstance(y_eval_active, torch.Tensor), \
            f"y_eval_active must be tensor, got {type(y_eval_active)}"
        assert isinstance(unique_mask_eval, torch.Tensor), \
            f"unique_mask_eval must be tensor, got {type(unique_mask_eval)}"

        assert X_eval_active.shape[0] == y_eval_active.shape[0], \
            f"X_eval_active and y_eval_active batch mismatch: {X_eval_active.shape[0]} != {y_eval_active.shape[0]}"

        assert unique_mask_eval.ndim == 1, \
            f"unique_mask_eval must be 1-D, got shape {tuple(unique_mask_eval.shape)}"
        assert unique_mask_eval.shape[0] == X_eval_active.shape[0], \
            f"unique_mask_eval length {unique_mask_eval.shape[0]} != X_eval_active {X_eval_active.shape[0]}"

        assert X_eval_active.device == y_eval_active.device == unique_mask_eval.device, \
            f"Device mismatch: X={X_eval_active.device}, y={y_eval_active.device}, mask={unique_mask_eval.device}"

        # --- NEW: minimal test forward to catch structural errors ---
        try:
            with torch.no_grad():
                n_test = min(T.BATCH_SIZE_EVAL, X_eval_active.size(0))
                xb_test = X_eval_active[:n_test].to(DEVICE)
                out_test = FWD_EVAL(xb_test)
                assert out_test.shape[0] == xb_test.shape[0], \
                    f"FWD_EVAL batch size mismatch: out={out_test.shape[0]}, in={xb_test.shape[0]}"
        except Exception as e:
            print("❌ [Test Forward] Failed after surgery before quick_acc:")
            raise

        acc_chunk, per_class_chunk, N_per_class_chunk = quick_acc_and_perclass_on_cache(X_eval_active, y_eval_active, unique_mask_eval, T.BATCH_SIZE_EVAL)


        # ---- Latency guard with dual threshold (OR logic) -----------------------------------------
        if T.LATENCY_GUARD_ENABLE:
            n_guard = min(T.LATENCY_GUARD_SAMPLES, X_eval_active.size(0))
            if n_guard > 0:
                X_guard = X_eval_active[:n_guard]

                # Measure latency (median of 2 passes)
                lat1 = _median_latency_ms_on_tensor(X_guard, T.BATCH_SIZE_EVAL)
                if T.LATENCY_TWO_PASS:
                    if torch.cuda.is_available():
                        torch.cuda.empty_cache()
                    lat2 = _median_latency_ms_on_tensor(X_guard, T.BATCH_SIZE_EVAL)
                    lat_meas = (lat1 + lat2) * 0.5
                else:
                    lat_meas = lat1

                # Adaptive relative threshold (2% → 3% over rounds)
                rel_pct = T.LAT_GUARD_REL_MIN + (round_idx / max(1, T.GLOBAL_ROUNDS - 1)) * (T.LAT_GUARD_REL_MAX - T.LAT_GUARD_REL_MIN)
                rel_pct = max(T.LAT_GUARD_REL_MIN, min(rel_pct, T.LAT_GUARD_REL_MAX))

                # Ensure absolute noise floor is calibrated (fallback if no commits yet)
                if abs_noise_floor_ms is None:
                    abs_noise_floor_ms = 0.01  # 4μs conservative default

                # Dual threshold with OR logic
                delta_rel = (lat_meas / last_good_latency_ms) - 1.0 if last_good_latency_ms > 0 else 0.0
                delta_abs = lat_meas - last_good_latency_ms

                guard_fail = (delta_rel > rel_pct) and (delta_abs > abs_noise_floor_ms)

                if guard_fail:
                    lat_guard_fail_count += 1

                    #  Validate snapshot before rollback
                    validate_snapshot(snapshot_chunk, "latency guard")

                    # Enhanced latency guard failure logging
                    print(f"  🛑 [LATENCY GUARD] Failed (attempt {lat_guard_fail_count}/{T.MAX_LAT_GUARD_FAILS})")
                    print(f"     Baseline: {last_good_latency_ms:.3f}ms")
                    print(f"     Measured: {lat_meas:.3f}ms")
                    print(f"     Δrel: {delta_rel*100:.1f}% (threshold: {rel_pct*100:.1f}%)")
                    print(f"     Δabs: {delta_abs*1000:.1f}μs (threshold: {abs_noise_floor_ms*1000:.1f}μs)")
                    print(f"     Round: {round_idx}/{T.GLOBAL_ROUNDS}, Chunk: {chunk_idx+1}/{num_chunks}")
                    if T.LATENCY_TWO_PASS:
                        print(f"     Two-pass: lat1={lat1:.3f}ms, lat2={lat2:.3f}ms")

                    # Validate and rollback
                    validate_snapshot(snapshot_chunk, "latency guard")

                    try:
                        restore_model_structure_from_snapshot(model, snapshot_chunk, DEVICE)
                        model.load_state_dict(snapshot_chunk, strict=True)
                    except Exception as e:
                        print(f"❌ [CRITICAL] Rollback failed: {e}")
                        try:
                            model.load_state_dict(snapshot_chunk, strict=False)
                            print(f"     ⚠️ Partial recovery (strict=False)")
                        except Exception as e2:
                            raise RuntimeError("Rollback and emergency recovery both failed") from e

                    sync_all_channelgates(model, layer_specs)
                    channel_tracker.sync_with_model(model, layer_specs)

                    if bn_recalibrator.force_recalibrate():
                        bn_recalibrate_from_cache(model, X_bn_fixed, iters=T.BN_MINI_ITERS)
                        bn_recalibrator.mark_recalibrated()

                    # Check fail budget
                    if lat_guard_fail_count >= T.MAX_LAT_GUARD_FAILS:
                        print(f"  🛑 [ROUND ABORT] Latency guard budget exhausted ({lat_guard_fail_count}/{T.MAX_LAT_GUARD_FAILS})")
                        round_failed = True
                        break
                    else:
                        # Shrink chunk and reset counter on strategy change
                        current_chunk_size = max(1, current_chunk_size // 2)
                        if current_chunk_size != last_chunk_size_for_lat_guard:
                            lat_guard_fail_count = 0
                            last_chunk_size_for_lat_guard = current_chunk_size
                            print(f"  [Strategy Change] Chunk size → {current_chunk_size}, fail counter reset")
                        else:
                            print(f"  [Retry] Chunk size unchanged ({current_chunk_size}), fail count: {lat_guard_fail_count}/{T.MAX_LAT_GUARD_FAILS}")
                        continue


        # --- Check Gates  ---
        step_drop = last_good_acc - acc_chunk

        step_class_drop_max = 0.0
        for cid, acc in per_class_chunk.items():
            per_drop = last_good_per_class.get(cid, acc) - acc
            if per_drop > step_class_drop_max:
                step_class_drop_max = per_drop

        cumulative_drop = acc0 - acc_chunk
        cumulative_per_class_drop_max = 0.0
        per0_map = trajectory[0]["per"]
        for cid, acc in per_class_chunk.items():
            per_drop = per0_map.get(cid, acc) - acc
            if per_drop > cumulative_per_class_drop_max:
                cumulative_per_class_drop_max = per_drop

        # ---- Early-warning lock (B1–B3) - Soft-Lock Mode ----------------
        #Check if early lock is enabled before triggering
        # Check if any early layer is NOT already locked
        any_early_layer_unlocked = any(
            layer not in early_locked or early_locked[layer] <= 0
            for layer in EARLY_LAYERS
        )

        if T.WARN_ENABLE and any_early_layer_unlocked and (
            (cumulative_drop >= T.WARN_OVERALL) or
            (cumulative_per_class_drop_max >= T.WARN_PER_CLASS)
        ):
            # Soft-lock: Set cooldown for all early layers
            for layer_name in EARLY_LAYERS:
                if layer_name not in early_locked or early_locked[layer_name] <= 0:
                    early_locked[layer_name] = T.SOFT_LOCK_COOLDOWN_ROUNDS

            early_lock_triggered_this_chunk = True

            #  Enhanced early lock trigger logging
            print(f"🔒 [Soft-Lock] B1–B3 layers locked with {T.SOFT_LOCK_COOLDOWN_ROUNDS}-round cooldown.")
            print(f"     Trigger reason:")
            if cumulative_drop >= T.WARN_OVERALL:
                print(f"       - Overall drop: {cumulative_drop:.4f} >= threshold {T.WARN_OVERALL:.4f} ❌")
            else:
                print(f"       - Overall drop: {cumulative_drop:.4f} < threshold {T.WARN_OVERALL:.4f} ✓")

            if cumulative_per_class_drop_max >= T.WARN_PER_CLASS:
                print(f"       - Per-class drop: {cumulative_per_class_drop_max:.4f} >= threshold {T.WARN_PER_CLASS:.4f} ❌")
            else:
                print(f"       - Per-class drop: {cumulative_per_class_drop_max:.4f} < threshold {T.WARN_PER_CLASS:.4f} ✓")

            print(f"     Locked layers: {EARLY_LAYERS}")
            print(f"     Cooldown will expire after {T.SOFT_LOCK_COOLDOWN_ROUNDS} rounds.")

            # NOTE:
            # We no longer mutate filters_to_prune_this_round or num_chunks here.
            # Soft-locked early layers are simply skipped by the chunk loop via
            # the early_locked check, so the current round can continue pruning
            # safe (non-early) layers without aborting the remaining chunks.

        # --- Gate Logic ---
        if step_drop > T.STEP_ACC_MAX or step_class_drop_max > T.STEP_CLASS_REL_MAX:
            #  Enhanced gate failure logging
            print(f"  🛑 [ROLLBACK CHUNK] Step gate failed.")
            print(f"     Step Drop: {step_drop:.4f} (Max: {T.STEP_ACC_MAX:.4f}) "
                  f"{'❌ EXCEEDED' if step_drop > T.STEP_ACC_MAX else '✓'}")
            print(f"     Step Class Drop: {step_class_drop_max:.4f} (Max: {T.STEP_CLASS_REL_MAX:.4f}) "
                  f"{'❌ EXCEEDED' if step_class_drop_max > T.STEP_CLASS_REL_MAX else '✓'}")
            print(f"     Accuracy: {last_good_acc:.4f} → {acc_chunk:.4f} (Δ={step_drop:.4f})")
            print(f"     Per-class: {dict(per_class_chunk)}")
            # Calculate total filters pruned from prune_map_chunk
            total_pruned = sum(len(indices) for indices in prune_map_chunk.values())
            print(f"     Filters pruned this chunk: {total_pruned}")

            # Restore structure before loading weights
            # Exception handling for rollback
            try:
                restore_model_structure_from_snapshot(model, snapshot_chunk, DEVICE)
                model.load_state_dict(snapshot_chunk, strict=True)
            except Exception as e:
                print(f"❌ [CRITICAL] Step gate rollback failed: {e}")
                try:
                    model.load_state_dict(snapshot_chunk, strict=False)
                    print(f"     ⚠️ Partial recovery successful (strict=False)")
                except Exception as e2:
                    raise RuntimeError("Step gate rollback failed") from e

            #  Sync all ChannelGates after rollback
            sync_all_channelgates(model, layer_specs)

            #  Refresh active set using RESTORED (last good) model state
            # CRITICAL: This must happen AFTER model.load_state_dict() to avoid causality paradox
            # The model is now in the last good state (before the failed chunk)
            # We refresh the active set based on this good state, not the failed state
            print("     [Stabilize] Refreshing active set post-rollback using restored model...")
            X_eval_active, y_eval_active, unique_mask_eval, drawn_per_class_eval, unique_per_class_eval = \
                build_eval_and_bn_caches(X_eval_full, y_eval_full, T.EVAL_BATCH_LIMIT, n_hard_pct=0.25)
            # ➕ also refresh BN cache using the restored model
            X_bn_fixed, y_bn_fixed, unique_mask_bn, drawn_per_class_bn, unique_per_class_bn = \
                build_eval_and_bn_caches(X_eval_full, y_eval_full, T.BN_RECAL_SAMPLES, n_hard_pct=0.25)

            #  Sync ChannelTracker with restored model state
            channel_tracker.sync_with_model(model, layer_specs)

            #  Force BN recalibration after rollback
            if bn_recalibrator.force_recalibrate():
                bn_recalibrate_from_cache(model, X_bn_fixed, iters=T.BN_MINI_ITERS)
                bn_recalibrator.mark_recalibrated()

            current_chunk_size = max(1, current_chunk_size // 2)
            print(f"     Chunk size halved to {current_chunk_size}. Skipping rest of round.")
            # round_failed = True  <-- This remains deleted
            break

        elif cumulative_drop > T.CUM_ACC_MAX or cumulative_per_class_drop_max > T.CUM_CLASS_REL_MAX:
            #  Enhanced gate failure logging
            print(f"  🛑 [STOP PRUNING] Cumulative gate failed.")
            print(f"     Cumulative Drop: {cumulative_drop:.4f} (Max: {T.CUM_ACC_MAX:.4f}) "
                  f"{'❌ EXCEEDED' if cumulative_drop > T.CUM_ACC_MAX else '✓'}")
            print(f"     Cumulative Class Drop: {cumulative_per_class_drop_max:.4f} (Max: {T.CUM_CLASS_REL_MAX:.4f}) "
                  f"{'❌ EXCEEDED' if cumulative_per_class_drop_max > T.CUM_CLASS_REL_MAX else '✓'}")
            print(f"     Baseline: {acc0:.4f}, Current: {acc_chunk:.4f}")
            print(f"     Per-class: {dict(per_class_chunk)}")
            print(f"     Total rounds completed: {round_idx}")
            # Restore structure before loading weights
            # Exception handling for rollback
            try:
                restore_model_structure_from_snapshot(model, snapshot_chunk, DEVICE)
                model.load_state_dict(snapshot_chunk, strict=True)
            except Exception as e:
                print(f"❌ [CRITICAL] Cumulative gate rollback failed: {e}")
                try:
                    model.load_state_dict(snapshot_chunk, strict=False)
                    print(f"     ⚠️ Partial recovery successful (strict=False)")
                except Exception as e2:
                    raise RuntimeError("Cumulative gate rollback failed") from e

            #  Sync all ChannelGates after rollback
            sync_all_channelgates(model, layer_specs)

            # Refresh active set using RESTORED (last good) model state
            # CRITICAL: This must happen AFTER model.load_state_dict() to avoid causality paradox
            # Stabilize both caches after restoring snapshot using the restored model
            print("     [Stabilize] Refreshing active set post-rollback using restored model...")
            X_eval_active, y_eval_active, unique_mask_eval, drawn_per_class_eval, unique_per_class_eval = \
                build_eval_and_bn_caches(X_eval_full, y_eval_full, T.EVAL_BATCH_LIMIT, n_hard_pct=0.25)
            X_bn_fixed, y_bn_fixed, unique_mask_bn, drawn_per_class_bn, unique_per_class_bn = \
                build_eval_and_bn_caches(X_eval_full, y_eval_full, T.BN_RECAL_SAMPLES, n_hard_pct=0.25)

            # Sync ChannelTracker with restored model state
            channel_tracker.sync_with_model(model, layer_specs)

            #  Force BN recalibration after rollback
            if bn_recalibrator.force_recalibrate():
                bn_recalibrate_from_cache(model, X_bn_fixed, iters=T.BN_MINI_ITERS)
                bn_recalibrator.mark_recalibrated()

            round_failed = True
            break


        else:
            # --- Commit Chunk ---
            print(f"  > Chunk {chunk_idx+1}/{num_chunks}: PASSED. Acc: {acc_chunk:.4f} (Δ: {acc_chunk-last_good_acc:+.4f})")

            commits_accepted += 1

            last_good_acc = acc_chunk
            last_good_per_class = per_class_chunk
            last_good_model_state = copy.deepcopy(model.state_dict())

            # Update latency baseline only on accepted commits
            if T.LATENCY_GUARD_ENABLE and 'lat_meas' in locals() and lat_meas is not None:
                last_good_latency_ms = lat_meas

            #  Sync ChannelTracker with committed model state
            channel_tracker.sync_with_model(model, layer_specs)
            channels_pre = channel_tracker.current.copy()

            # Soft-lock: Set cooldown for layers that were pruned in this chunk (prevents thrashing)
            layers_pruned_this_chunk = set(prune_map_chunk.keys())
            for layer_name in layers_pruned_this_chunk:
                if prune_map_chunk[layer_name]:  # If filters were actually pruned
                    # Only set cooldown for early layers (B1-B3)
                    if layer_name in EARLY_LAYERS:
                        early_locked[layer_name] = T.SOFT_LOCK_COOLDOWN_ROUNDS
                        print(f"  [Soft-Lock] {layer_name} locked for {T.SOFT_LOCK_COOLDOWN_ROUNDS} rounds (pruned this chunk)")

            # Calibrate noise floor once after first commit
            if abs_noise_floor_ms is None and commits_accepted == 1 and T.LATENCY_GUARD_ENABLE:
                print("  [Latency Guard] Calibrating noise floor...")
                n_guard = min(T.LATENCY_GUARD_SAMPLES, X_eval_active.size(0))
                if n_guard > 0:
                    X_guard = X_eval_active[:n_guard]
                    timings = []
                    for _ in range(20):
                        lat = _median_latency_ms_on_tensor(X_guard, T.BATCH_SIZE_EVAL)
                        timings.append(lat)

                    median_lat = float(np.median(timings))
                    MAD = float(np.median([abs(t - median_lat) for t in timings]))
                    abs_noise_floor_ms = max(3 * MAD, 0.002)
                    print(f"  [Latency Guard] Noise floor: {abs_noise_floor_ms*1000:.1f}μs (MAD={MAD*1000:.1f}μs)")

            # Invalidate caches for all modified layers AND their dependents
            for conv_path in prune_map_chunk.keys():
                if prune_map_chunk[conv_path]:  # If filters were pruned
                    _invalidate_layer_and_dependents(conv_path, layer_specs, cache_manager)

            # Mark graph as dirty - needs recompile
            graph_dirty = True

            # Defer plateau commit until end of round
            # Check if any layer hit a plateau, but don't recompile yet
            if T.PLATEAUS and T.PLATEAU_COMMIT:
                for spec in layer_specs:
                    k = spec["conv"]
                    try:
                        before = int(counts_before_chunk.get(k, -1))
                        after  = int(get_conv_module(model, k).out_channels)
                        if (after in T.PLATEAUS) and (after != before):
                            plateau_hit_this_round = True
                            break
                    except Exception:
                        pass


    #  Report health rejection metrics after chunk loop
    if T.HEALTH_CHECK_ENABLE and health_rejections:
        total_rejections = sum(health_rejections.values())
        print(f"  🩺 [Health] Dispersion check rejected {total_rejections} candidates across {len(health_rejections)} layers:")
        for conv_path, count in sorted(health_rejections.items(), key=lambda x: x[1], reverse=True):
            print(f"     {conv_path}: {count} rejections")

        # Warn if chunk was significantly reduced by health checks
        chunk_size_actual = len([c for c in chunk if c])  # Count non-empty entries
        if total_rejections > chunk_size_actual * 0.5:
            print(f"  ⚠️ [Health] Warning: Health checks rejected >50% of chunk candidates.")
            print(f"     Consider relaxing HEALTH_MIN_DISPERSION_PCT (current: {T.HEALTH_MIN_DISPERSION_PCT:.2f})")
            print(f"     or increasing chunk size to maintain pruning progress.")

    # --- End of Chunk Loop ---

    # Stop surgery+guards timer
    sw.stop(); timing[f"surgery_guard_s_R{round_idx}"] = sw.t.get(f"surgery_guard_s_R{round_idx}", 0.0)

    reporter.finish_round_after_surgery()
    reporter.print_round()

    # Store trajectory point for the *last good state* of the round
    trajectory.append({"stage":f"Global R{round_idx}", "acc":last_good_acc, "per":last_good_per_class})

    #  Deferred plateau commit - recompile once at round end
    # This reduces recompilation overhead by 50-90% compared to per-chunk commits
    if plateau_hit_this_round and not round_failed:
        print(f"  [Plateau] Deferred commit: recompiling once for all plateaus hit this round...")
        _maybe_plateau_commit(counts_at_round_start, layer_specs, sequential_loader)
        print(f"  [Plateau] Recompilation complete. Saved {num_chunks-1} redundant recompiles.")

    # Deferred recompilation: Recompile once at round end if graph is dirty
    # This reduces overhead from N recompiles per round to 1 recompile per round
    # Expected savings: 80-90% reduction in recompile time (e.g., 10 chunks → 1 recompile)
    if graph_dirty and hasattr(torch, "compile") and torch.cuda.is_available() and T.ENABLE_COMPILE:
        sw.go(f"recompile_s_R{round_idx}")
        print(f"  [Recompile] Deferred recompilation after round {round_idx}...")
        try:
            if hasattr(torch, "_dynamo"):
                torch._dynamo.reset()
            FWD_EVAL = torch.compile(_raw_forward, mode="default", dynamic=True, fullgraph=False)
            graph_dirty = False
            print(f"  [Recompile] Complete. Model ready for next round.")
        except Exception as e:
            print(f"  ⚠️ Recompile failed: {e}, using uncompiled forward")
            FWD_EVAL = _raw_forward
            graph_dirty = False  # Reset flag even on failure
        finally:
            sw.stop(); timing[f"recompile_s_R{round_idx}"] = sw.t.get(f"recompile_s_R{round_idx}", 0.0)

    #  Reset BN recalibrator at round end
    bn_recalibrator.reset_for_round()

    # --- Phase-0 (0.6) Floors stay frozen — skip decay when locked ---
    if not round_failed:
        if bool(getattr(T, "FLOORS_LOCKED", True)):
            print("  > Floors locked; skipping floor decay.")
        else:
            print("  > Round successful. Decaying layer floors slightly...")
            #  Track which layers had decay applied
            decayed_layers = []
            frozen_layers = []

            for k, v in T.HARD_FLOORS.items():
                #  Don't decay floors for soft-locked layers (cooldown > 0)
                if k in early_locked and early_locked[k] > 0:
                    frozen_layers.append(k)
                    continue  # Skip decay for this layer

                min_keep_pct = {
                    "features.0":  0.50, "features.4":  0.40, "features.8":  0.35,
                    "features.12": 0.30, "features.16": 0.30
                }.get(k, 0.1)
                initial_c = channels_at_start.get(k, v)
                min_keep_abs = int(min_keep_pct * initial_c)
                new_v = max(min_keep_abs, int(v * T.FLOOR_DECAY_RATE))
                T.HARD_FLOORS[k] = new_v
                decayed_layers.append(k)

            #  Log which layers were frozen due to early lock
            if frozen_layers:
                print(f"  > Early-locked layers frozen (no decay): {frozen_layers}")
            if decayed_layers:
                print(f"  > Decayed layers: {decayed_layers}")


    if round_failed:
        print(f"--- Round {round_idx} halted due to gate violation. ---")
        print(f"    Continuing to next round with reduced chunk size ({current_chunk_size})...")
        # Don't break - continue to next round with smaller chunks
        # The chunk size has already been halved, which will make future rounds more conservative
        round_failed = False  # Reset for next round

    # Record round total time (at end of round, after all operations)
    timing[f"round_total_s_R{round_idx}"] = time.perf_counter() - t_round_start


# ═══════════════════════════════════════════════════════════════════════════
# END OF CELL 3C.4 — MAIN PRUNING LOOP
# ═══════════════════════════════════════════════════════════════════════════

# ═══════════════════════════════════════════════════════════════════════════
# END OF CELL 3C — EXECUTION FUNCTIONS & PHASE A LOOP (ALL SUB-CELLS COMPLETE)
# ═══════════════════════════════════════════════════════════════════════════

"""## Phase 4 - Cell 4"""

# ═══════════════════════════════════════════════════════════════════════════
# Phase 4 Cell 4A — POST-PRUNING PHASES
# Purpose: Post-processing (alignment, Linear1 sync, final evaluation)
# ═══════════════════════════════════════════════════════════════════════════

# PHASE A : Alignment Sweep
#--------------------------

# Record Phase A total time (after all rounds complete)
timing["phaseA_total_s"] = time.perf_counter() - t_phaseA_start

if T.ALIGN_SWEEP_ENABLE and not round_failed:
    _alignment_sweep_simple()

# PHASE B: Linear1 Alignment
#---------------------------

# ⚠️ CRITICAL: Linear1 input pruning is DISABLED because:
#    - Linear1's input dimension MUST match the flattened conv output
#    - Pruning Linear1 input independently breaks this constraint
#    - To reduce Linear1 size, prune the last conv layer (features.16) instead
#    - This phase now ONLY ensures dimension alignment after conv pruning

if T.LINEAR_PRUNE_ENABLE and not round_failed:
    sw.go("phaseB_total_s")
    try:
        _bar(f"PHASE B: Linear1 Dimension Alignment (Pruning Disabled)", width=70)

        # Recalculate expected Linear1 input dimension based on current conv output
        # Get the last conv layer (features.16 / Block 5)
        # Architecture: [..., Conv(16), BN(17), ReLU(18), MaxPool(19)]
        # So features[-4] is the last conv (features.16)
        last_conv = model.features[-4]  # features.16 is the last conv (index 16)
        if isinstance(last_conv, nn.Sequential):
            last_conv = last_conv[0]  # unwrap if Sequential (in case of ChannelGate wrapper)

        current_conv_out = last_conv.out_channels
        h, w = CONFIG["IMG_SIZE"]
        NUM_POOLING_LAYERS = 5
        DOWNSCALE_FACTOR = 2 ** NUM_POOLING_LAYERS  # 32
        downscale = DOWNSCALE_FACTOR  # Use named constant
        spatial_size = (h // downscale) * (w // downscale)

        #  Validate spatial_size to prevent division by zero
        if spatial_size <= 0:
            raise ValueError(
                f"Invalid spatial_size: {spatial_size}. "
                f"Image size {(h, w)} with downscale {downscale} results in collapsed dimensions."
            )

        expected_lin_in = current_conv_out * spatial_size

        lin1 = model.classifier[LINEAR_INDEX]
        actual_lin_in = lin1.in_features

        # Rebuild Linear1 if dimensions don't match (due to conv pruning)
        if actual_lin_in != expected_lin_in:
            print(f"[Linear1] Dimension mismatch detected: {actual_lin_in} != {expected_lin_in}")
            print(f"          Conv output: {current_conv_out} channels × {spatial_size} spatial = {expected_lin_in}")
            print(f"          Rebuilding Linear1 to match current conv output...")

            old_lin1 = lin1
            new_lin1 = nn.Linear(expected_lin_in, old_lin1.out_features, bias=(old_lin1.bias is not None)).to(DEVICE)

            # Initialize new weights intelligently
            with torch.no_grad():
                # If expanding: copy old weights and init new ones
                # If shrinking: slice old weights
                if expected_lin_in <= actual_lin_in:
                    # Shrinking: slice the old weights
                    new_lin1.weight.copy_(old_lin1.weight[:, :expected_lin_in])
                else:
                    # Expanding: copy what we can, init the rest
                    new_lin1.weight[:, :actual_lin_in].copy_(old_lin1.weight)
                    nn.init.kaiming_normal_(new_lin1.weight[:, actual_lin_in:], nonlinearity='relu')

                if new_lin1.bias is not None and old_lin1.bias is not None:
                    new_lin1.bias.copy_(old_lin1.bias)

            model.classifier[LINEAR_INDEX] = new_lin1
            lin1 = new_lin1
            print(f"          ✅ Linear1 rebuilt: {lin1.in_features} → {lin1.out_features}")

            # Update last_good_model_state after successful rebuild
            last_good_model_state = copy.deepcopy(model.state_dict())
            trajectory.append({"stage":"Linear1 Align", "acc":acc0, "per":trajectory[-1]["per"]})
        else:
            print(f"[Linear1] Dimensions already aligned: {actual_lin_in} features")
            print(f"          (Conv output: {current_conv_out} channels × {spatial_size} spatial)")

        # ⚠️ INDEPENDENT LINEAR1 PRUNING DISABLED - See comment at top of Phase B
        # To reduce Linear1 parameters, prune features.16 (last conv) in Phase A instead
        print(f"[Linear1] Independent input pruning DISABLED (would break dimension constraints)")
        print(f"          To reduce Linear1 size, increase pruning of features.16 in Phase A")

    finally:
        sw.stop()
        timing["phaseB_total_s"] = sw.t.get("phaseB_total_s", 0.0)
else:
    # Phase B skipped - record 0 time
    timing["phaseB_total_s"] = 0.0


# PHASE C: Final Compile & Eval
#-----------------------------
_bar("PHASE C: Final Compile & Evaluation", width=70)

# Skip reload - model is already in committed state after alignment
# Reloading is redundant since we just snapshotted after successful commits
print("[Phase C] Using in-memory committed model (already validated)")
print("[Phase C] Skipping reload - model topology matches snapshot")

sync_all_channelgates(model, layer_specs)

# Final FULL BN recalibration
sw.go("bn_recalibrate_s"); _sync()
bn_recalibrate_from_cache(model, X_bn_fixed, iters=T.BN_ROUND_ITERS)
sw.stop(); _sync(); timing["bn_recalibrate_s"] = sw.t["bn_recalibrate_s"]; heartbeat("after BN recal")

# Strip ChannelGate(s) for inference
sw.go("phaseC_strip_gates_s")
stripped = 0
for L in T.ALT_ORDER:
    if strip_channel_gate_for_infer(model, L["conv"]): stripped += 1
sw.stop(); timing["phaseC_strip_gates_s"] = sw.t.get("phaseC_strip_gates_s", 0.0)

# --- Final Compile-Once ---
if hasattr(torch, "compile") and torch.cuda.is_available() and T.ENABLE_COMPILE:
    sw.go("phaseC_compile_s")
    try:
        if hasattr(torch, "_dynamo"):
            torch._dynamo.reset()

        FWD_EVAL = torch.compile(_raw_forward, mode="default", dynamic=True, fullgraph=False)
        w = 0
        for x,_ in sequential_loader: # Warm up on full loader
            _ = FWD_EVAL(x.to(DEVICE)); w += 1
            if w >= 2: break
        print(f"✅ recompiled FINAL eval graph (no ChannelGate x{stripped}) + warm-up complete")
    except Exception as e:
        print("⚠️ FINAL eval recompile skipped:", e)
        FWD_EVAL = _raw_forward # Fallback for final eval
    finally:
        sw.stop(); timing["phaseC_compile_s"] = sw.t.get("phaseC_compile_s", 0.0)
else:
    # Compile skipped - record 0 time
    timing["phaseC_compile_s"] = 0.0

# Post eval (steady) on FULL validation set
_sync(); sw.go("post_eval_s")
acc1, per1 = safe_eval_top1_and_perclass(model, sequential_loader, DEVICE)
sw.stop(); _sync(); timing["post_eval_s"] = sw.t["post_eval_s"]; heartbeat("after post eval")

# ---- Final summary (Corrected: Sum all layers) ----
c_params1, l_params1 = 0, 0
c_macs1, l_macs1 = 0, 0
c_ch1 = 0
shape_cache1 = {} # Cache for post-pruning shapes

lin1_p = model.classifier[LINEAR_INDEX]
l_params1 = count_params_module(lin1_p)
l_macs1   = linear_macs_per_image(lin1_p)

for spec in layer_specs:
    conv_p = get_conv_module(model, spec["conv"])
    bn_p   = get_module(model, spec["bn"])

    # Re-calculate post-pruning shapes; they may have changed
    shapes_post = layer_shapes_prepool(model, DEVICE, spec["conv"], spec["pool"], sequential_loader)
    Hc1, Wc1 = (int(shapes_post["conv"][2]), int(shapes_post["conv"][3]))

    c_ch1     += conv_p.out_channels
    c_params1 += count_params_module(conv_p) + count_params_module(bn_p)
    c_macs1   += conv_macs_per_image(conv_p, conv_p.in_channels, Hc1, Wc1)

params_total1 = sum(p.numel() for p in model.parameters())

# --- Print All Summaries ---
# 1. Print the Reporter's Layer-by-Layer Summary
reporter.print_final_summary()

# 2. Print the Model-Wide Financial Summary
print("Model-wide totals (params, FLOPs*)")
rows = [
    ["Params total",    f"{_fmt_big(pre_stats[-1][5])} → {_fmt_big(params_total1)}",    f"{_fmt_big(params_total1-pre_stats[-1][5])}"],
    ["Conv params (Σ)", f"{_fmt_big(pre_stats[-1][1])} → {_fmt_big(c_params1)}",        f"{_fmt_big(c_params1-pre_stats[-1][1])}"],
    ["Linear1 params",  f"{_fmt_big(pre_stats[-1][2])} → {_fmt_big(l_params1)}",        f"{_fmt_big(l_params1-pre_stats[-1][2])}"],
    ["Conv FLOPs* (Σ)", f"{_fmt_big(pre_stats[-1][3])} → {_fmt_big(c_macs1)}",          f"{_fmt_big(c_macs1-pre_stats[-1][3])}"],
    ["Linear1 FLOPs*",  f"{_fmt_big(pre_stats[-1][4])} → {_fmt_big(l_macs1)}",          f"{_fmt_big(l_macs1-pre_stats[-1][4])}"],
]
_print_table(rows, header=["Metric","Before → After","Δ"], colw=[18,30,16])

# Timing + perf
timing["total_s"] = time.perf_counter()-t0_all

# Enhanced hierarchical timing report
print("\n" + "="*70)
print("DETAILED TIMING BREAKDOWN")
print("="*70)

# Phase-level summary
print("\n📊 PHASE-LEVEL SUMMARY")
print("-"*70)
phase_times = {
    "Baseline + Cache": timing.get("baseline_eval_s", 0) + timing.get("eval_cache_s", 0),
    "Phase A (Pruning)": timing.get("phaseA_total_s", 0),
    "Phase A.5 (Alignment)": timing.get("alignment_total_s", 0),
    "Phase B (Linear1)": timing.get("phaseB_total_s", 0),
    "Phase C (Strip+Compile)": timing.get("phaseC_strip_gates_s", 0) + timing.get("phaseC_compile_s", 0),
    "Phase C (BN+Eval)": timing.get("bn_recalibrate_s", 0) + timing.get("post_eval_s", 0),
}
total_measured = sum(phase_times.values())

for phase, t in phase_times.items():
    pct = (t / timing["total_s"] * 100) if timing["total_s"] > 0 else 0
    print(f"  {phase:<30}: {t:>8.2f}s  ({pct:>5.1f}%)")

print(f"  {'Total Measured':<30}: {total_measured:>8.2f}s  ({total_measured/timing['total_s']*100:>5.1f}%)")
unmeasured = timing["total_s"] - total_measured
print(f"  {'Unmeasured Residual':<30}: {unmeasured:>8.2f}s  ({unmeasured/timing['total_s']*100:>5.1f}%)")
print(f"  {'TOTAL RUNTIME':<30}: {timing['total_s']:>8.2f}s  (100.0%)")

# Per-round breakdown
print("\n📊 PER-ROUND BREAKDOWN")
print("-"*70)
print(f"{'Round':<8} {'Total':>10} {'Score':>10} {'Select':>10} {'Surgery':>10} {'Recomp':>10}")
print("-"*70)

for r in range(1, T.GLOBAL_ROUNDS + 1):
    if f"round_total_s_R{r}" not in timing:
        break

    round_total = timing.get(f"round_total_s_R{r}", 0)
    score_t = timing.get(f"global_score_s_R{r}", 0)
    select_t = timing.get(f"selection_s_R{r}", 0)
    surgery_t = timing.get(f"surgery_guard_s_R{r}", 0)
    recomp_t = timing.get(f"recompile_s_R{r}", 0)
    refresh_t = timing.get(f"active_refresh_s_R{r}", 0)

    # Calculate overhead (unmeasured time in round)
    measured_sum = score_t + select_t + surgery_t + recomp_t + refresh_t
    overhead = round_total - measured_sum

    print(f"R{r:<7} {round_total:>9.1f}s {score_t:>9.1f}s {select_t:>9.1f}s {surgery_t:>9.1f}s {recomp_t:>9.1f}s")
    if refresh_t > 0:
        print(f"        (refresh: {refresh_t:.1f}s, overhead: {overhead:.1f}s)")

# Phase C breakdown
print("\n📊 PHASE C BREAKDOWN")
print("-"*70)
print(f"  Strip ChannelGates : {timing.get('phaseC_strip_gates_s', 0):>8.2f}s")
print(f"  torch.compile()    : {timing.get('phaseC_compile_s', 0):>8.2f}s")
print(f"  BN Recalibration   : {timing.get('bn_recalibrate_s', 0):>8.2f}s")
print(f"  Final Evaluation   : {timing.get('post_eval_s', 0):>8.2f}s")
phaseC_total = (timing.get('phaseC_strip_gates_s', 0) + timing.get('phaseC_compile_s', 0) +
                timing.get('bn_recalibrate_s', 0) + timing.get('post_eval_s', 0))
print(f"  Phase C Total      : {phaseC_total:>8.2f}s")

# Alignment breakdown (if executed)
if timing.get("alignment_total_s", 0) > 0:
    print("\n📊 ALIGNMENT SWEEP")
    print("-"*70)
    print(f"  Total Alignment Time: {timing.get('alignment_total_s', 0):>8.2f}s")

print("="*70)

# Original simple timing (for backwards compatibility)
print("\nTIMING (Raw)")
for k,v in sorted(timing.items()): print(f"  {k}: {v:.2f}")

lat1_ms = timing["post_eval_s"] * 1000.0 / max(1, len(sequential_loader.dataset))
speedup = lat0_ms/lat1_ms if lat1_ms>0 else float('inf')
overhead_s = timing["total_s"] - timing["baseline_eval_s"] - timing["post_eval_s"]

print("\nPERF SUMMARY")
_print_kv_block([
    ("Latency per sample", f"{lat0_ms:.3f} ms → {lat1_ms:.3f} ms ({speedup:.2f}×)"),
    ("Optimization overhead (s)", f"{overhead_s:.2f}"),
    ("FLOPs* note", "per-image MACs proxy"),
], width=70)

if T.PROFILE_HC:
    print("HC COST PROFILE")
    for k,v in prof.counters.items():
        if isinstance(v, float): print(f"  {k}: {v:.2f}")
        else:                     print(f"  {k}: {v}")
_rule(width=70)

# ═══════════════════════════════════════════════════════════════════════════
# END OF CELL 4A — POST-PRUNING
# ═══════════════════════════════════════════════════════════════════════════

# ============================================================================
# Phase 4 Cell 4B : REPORTING
# Purpose : Should cover accuracty comparison - baseline vs post pruning, parameter reduction, etc.,
# ============================================================================

import pandas as pd
from IPython.display import display, HTML

print("=" * 80)
print("ACCURACY COMPARISON: Baseline vs Post-Pruning")
print("=" * 80)

# Extract baseline and final accuracy from trajectory
baseline_acc = trajectory[0]["acc"]
baseline_per_class = trajectory[0]["per"]
final_acc = trajectory[-1]["acc"]
final_per_class = trajectory[-1]["per"]

# Overall accuracy comparison
print("\n📊 OVERALL ACCURACY")
print("-" * 80)
acc_drop = baseline_acc - final_acc
acc_drop_pct = (acc_drop / baseline_acc) * 100 if baseline_acc > 0 else 0
print(f"  Baseline:      {baseline_acc*100:.2f}%")
print(f"  Post-Pruning:  {final_acc*100:.2f}%")
print(f"  Drop:          {acc_drop*100:.2f}% ({acc_drop_pct:.1f}% relative)")
print(f"  Status:        {'✅ PASS' if acc_drop <= 0.02 else '⚠️ DEGRADED'}")

# Per-class accuracy comparison
print("\n📊 PER-CLASS ACCURACY")
print("-" * 80)

# Build comparison table
class_data = []
all_classes = sorted(set(list(baseline_per_class.keys()) + list(final_per_class.keys())))

for class_id in all_classes:
    baseline_class_acc = baseline_per_class.get(class_id, 0.0)
    final_class_acc = final_per_class.get(class_id, 0.0)

    drop_abs = baseline_class_acc - final_class_acc
    drop_rel = (drop_abs / baseline_class_acc * 100) if baseline_class_acc > 0 else 0

    status = "✅" if drop_abs <= 0.04 else "⚠️"

    class_data.append({
        "Class": f"Class {class_id}",
        "Baseline": f"{baseline_class_acc*100:.2f}%",
        "Post-Pruning": f"{final_class_acc*100:.2f}%",
        "Abs Drop": f"{drop_abs*100:.2f}%",
        "Rel Drop": f"{drop_rel:.1f}%",
        "Status": status
    })

# Display as formatted table
df_comparison = pd.DataFrame(class_data)
print(df_comparison.to_string(index=False))

# Summary statistics
print("\n📈 SUMMARY STATISTICS")
print("-" * 80)
max_class_drop = max([baseline_per_class.get(c, 0) - final_per_class.get(c, 0)
                      for c in all_classes])
avg_class_drop = sum([baseline_per_class.get(c, 0) - final_per_class.get(c, 0)
                      for c in all_classes]) / len(all_classes)

print(f"  Max per-class drop:  {max_class_drop*100:.2f}%")
print(f"  Avg per-class drop:  {avg_class_drop*100:.2f}%")
print(f"  Classes affected:    {len([c for c in all_classes if baseline_per_class.get(c, 0) - final_per_class.get(c, 0) > 0.01])}/{len(all_classes)}")

# Model compression stats (if available)
if 'pre_stats' in globals() and len(pre_stats) > 0:
    print("\n🗜️ MODEL COMPRESSION")
    print("-" * 80)

    params_before = pre_stats[-1][5]  # Total params
    params_after = sum(p.numel() for p in model.parameters())
    params_reduction = (1 - params_after / params_before) * 100

    print(f"  Parameters:      {params_before:,} → {params_after:,}")
    print(f"  Reduction:       {params_reduction:.1f}%")

    if 'lat0_ms' in globals() and 'lat1_ms' in globals():
        speedup = lat0_ms / lat1_ms if lat1_ms > 0 else 1.0
        print(f"  Latency:         {lat0_ms:.3f}ms → {lat1_ms:.3f}ms")
        print(f"  Speedup:         {speedup:.2f}×")

# Visual comparison (optional - requires matplotlib)
try:
    import matplotlib.pyplot as plt

    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 5))

    # Overall accuracy bar chart
    ax1.bar(['Baseline', 'Post-Pruning'],
            [baseline_acc*100, final_acc*100],
            color=['#4CAF50', '#2196F3'])
    ax1.set_ylabel('Accuracy (%)')
    ax1.set_title('Overall Accuracy Comparison')
    ax1.set_ylim([0, 100])
    ax1.grid(axis='y', alpha=0.3)

    # Add value labels on bars
    for i, v in enumerate([baseline_acc*100, final_acc*100]):
        ax1.text(i, v + 1, f'{v:.2f}%', ha='center', va='bottom', fontweight='bold')

    # Per-class accuracy comparison
    x = range(len(all_classes))
    width = 0.35
    baseline_vals = [baseline_per_class.get(c, 0)*100 for c in all_classes]
    final_vals = [final_per_class.get(c, 0)*100 for c in all_classes]

    ax2.bar([i - width/2 for i in x], baseline_vals, width,
            label='Baseline', color='#4CAF50', alpha=0.8)
    ax2.bar([i + width/2 for i in x], final_vals, width,
            label='Post-Pruning', color='#2196F3', alpha=0.8)

    ax2.set_xlabel('Class')
    ax2.set_ylabel('Accuracy (%)')
    ax2.set_title('Per-Class Accuracy Comparison')
    ax2.set_xticks(x)
    ax2.set_xticklabels([f'C{c}' for c in all_classes])
    ax2.legend()
    ax2.grid(axis='y', alpha=0.3)
    ax2.set_ylim([0, 100])

    plt.tight_layout()
    plt.show()

except ImportError:
    print("\n(Install matplotlib for visual comparison: !pip install matplotlib)")

print("\n" + "=" * 80)
print("✅ Comparison complete!")
print("=" * 80)

# ═══════════════════════════════════════════════════════════════════════════
# END OF CELL 4B — REPORTING
# ═══════════════════════════════════════════════════════════════════════════

# ═══════════════════════════════════════════════════════════════════════════
# Phase 4 Cell 4C — Unified Experiment Summary (JSON)
# Purpose: Emit a machine-readable summary for cross-experiment comparison.
# ═══════════════════════════════════════════════════════════════════════════

import os as _os, json as _json

try:
    # --- Meta / config ------------------------------------------------------
    _meta = {
        "approach": "global",
        "backbone": "cnn_v1" if BACKBONE == "cnn" else "vgg16_bn",
        "dataset": DATASET,
    }

    _config_summary = {
        "img_size": list(CONFIG.get("IMG_SIZE", (224, 224))),
        "num_classes": int(CONFIG.get("NUM_CLASSES", 2)),
        "train_samples": int(CONFIG.get("TRAIN_SAMPLES", 10000)),
        "prune_ref_samples": int(CONFIG.get("PRUNE_REF_SAMPLES", 6000)),
        "eval_samples": int(len(sequential_loader.dataset)) if hasattr(sequential_loader, "dataset") else None,
        "batch_size_train": int(CONFIG.get("BATCH_SIZE", 64)),
        "batch_size_eval": int(getattr(T, "BATCH_SIZE_EVAL", CONFIG.get("BATCH_SIZE_EVAL", 512))),
        "taylor_batch_size": int(getattr(T, "TAYLOR_BATCH_SIZE", CONFIG.get("TAYLOR_BATCH_SIZE", 256))),
        "global_rounds": int(getattr(T, "GLOBAL_ROUNDS", CONFIG.get("GLOBAL_ROUNDS", 5))),
        "seed": int(CONFIG.get("SEED", 42)),
    }

    _guards_summary = {
        "step_acc_max": float(getattr(T, "STEP_ACC_MAX", CONFIG.get("STEP_ACC_MAX", 0.010))),
        "step_class_rel_max": float(getattr(T, "STEP_CLASS_REL_MAX", CONFIG.get("STEP_CLASS_REL_MAX", 0.030))),
        "cum_acc_max": float(getattr(T, "CUM_ACC_MAX", CONFIG.get("CUM_ACC_MAX", 0.020))),
        "cum_class_rel_max": float(getattr(T, "CUM_CLASS_REL_MAX", CONFIG.get("CUM_CLASS_REL_MAX", 0.060))),
        "guard_n_min": int(getattr(T, "GUARD_N_MIN", CONFIG.get("GUARD_N_MIN", 300))),
        "guard_err_budget_pct": float(getattr(T, "GUARD_ERR_BUDGET_PCT", CONFIG.get("GUARD_ERR_BUDGET_PCT", 0.005))),
    }

    # --- Baseline / final core metrics --------------------------------------
    # Baseline: from acc0/per0 and pre_stats (captured once at Phase A setup)
    _baseline_per = {cid: acc for (cid, acc, _) in per0}
    _baseline_channels = reporter.ch0 if hasattr(reporter, "ch0") else {
        spec["conv"]: int(get_conv_module(model, spec["conv"]).out_channels) for spec in layer_specs
    }

    _c_ch0, _c_params0, _l_params0, _c_macs0, _l_macs0, _params_total0 = pre_stats[-1]

    _baseline = {
        "acc_top1": float(acc0),
        "per_class_acc": _baseline_per,
        "channels_per_layer": _baseline_channels,
        "params_total": int(_params_total0),
        "params_conv": int(_c_params0),
        "params_linear1": int(_l_params0),
        "macs_conv_per_image": float(_c_macs0),
        "macs_linear1_per_image": float(_l_macs0),
        "flops_conv_per_image": float(_c_macs0 * 2.0),
        "flops_linear1_per_image": float(_l_macs0 * 2.0),
        "latency_ms_per_sample": float(lat0_ms),
        "eval_time_s": float(timing.get("baseline_eval_s", 0.0)),
    }

    # Final metrics: from acc1/per1 and post-pruning stats
    _final_per = {cid: acc for (cid, acc, _) in per1}

    _channels_after = {
        spec["conv"]: int(get_conv_module(model, spec["conv"]).out_channels)
        for spec in layer_specs
    }

    _baseline_channels_total = int(sum(_baseline_channels.values()))
    _final_channels_total = int(sum(_channels_after.values()))

    _final = {
        "acc_top1": float(acc1),
        "per_class_acc": _final_per,
        "channels_per_layer": _channels_after,
        "params_total": int(params_total1),
        "params_conv": int(c_params1),
        "params_linear1": int(l_params1),
        "macs_conv_per_image": float(c_macs1),
        "macs_linear1_per_image": float(l_macs1),
        "flops_conv_per_image": float(c_macs1 * 2.0),
        "flops_linear1_per_image": float(l_macs1 * 2.0),
        "latency_ms_per_sample": float(lat1_ms),
        "eval_time_s": float(timing.get("post_eval_s", 0.0)),
    }

    # --- Compression summary ------------------------------------------------
    _acc_drop = _baseline["acc_top1"] - _final["acc_top1"]
    _per_class_drops = {
        cid: _baseline_per.get(cid, 0.0) - _final_per.get(cid, 0.0)
        for cid in set(list(_baseline_per.keys()) + list(_final_per.keys()))
    }
    _max_class_drop = max(_per_class_drops.values()) if _per_class_drops else 0.0

    _compression = {
        "acc_drop_overall_pp": float(_acc_drop * 100.0),
        "max_per_class_drop_pp": float(_max_class_drop * 100.0),
        "channels_total_before": _baseline_channels_total,
        "channels_total_after": _final_channels_total,
        "channels_total_pruned": _baseline_channels_total - _final_channels_total,
        "channels_total_pruned_pct": float(
            (_baseline_channels_total - _final_channels_total) / max(1, _baseline_channels_total)
        ),
        "params_total_before": _baseline["params_total"],
        "params_total_after": _final["params_total"],
        "params_total_pruned": _final["params_total"] - _baseline["params_total"],
        "params_total_pruned_pct": float(
            (_baseline["params_total"] - _final["params_total"]) / max(1, _baseline["params_total"])
        ),
        "conv_params_before": _baseline["params_conv"],
        "conv_params_after": _final["params_conv"],
        "conv_params_pruned": _final["params_conv"] - _baseline["params_conv"],
        "linear1_params_before": _baseline["params_linear1"],
        "linear1_params_after": _final["params_linear1"],
        "linear1_params_pruned": _final["params_linear1"] - _baseline["params_linear1"],
        "macs_conv_before": _baseline["macs_conv_per_image"],
        "macs_conv_after": _final["macs_conv_per_image"],
        "macs_linear1_before": _baseline["macs_linear1_per_image"],
        "macs_linear1_after": _final["macs_linear1_per_image"],
    }

    # --- Layer-wise summary -------------------------------------------------
    _layers_summary = {}
    for conv_path in _baseline_channels.keys():
        _b_ch = int(_baseline_channels[conv_path])
        _a_ch = int(_channels_after.get(conv_path, _b_ch))
        _layers_summary[conv_path] = {
            "channels_before": _b_ch,
            "channels_after": _a_ch,
            "channels_pruned": _b_ch - _a_ch,
            "channels_pruned_pct": float((_b_ch - _a_ch) / max(1, _b_ch)),
        }

    # --- Timing & ratios ----------------------------------------------------
    _timing_summary = dict(timing)  # already has baseline_eval_s, post_eval_s, total_s, etc.
    _optimization_overhead = float(
        timing.get("total_s", 0.0) - timing.get("baseline_eval_s", 0.0) - timing.get("post_eval_s", 0.0)
    )

    _ratios = {
        "param_ratio_total": float(_final["params_total"] / max(1, _baseline["params_total"])),
        "param_ratio_conv": float(_final["params_conv"] / max(1, _baseline["params_conv"])),
        "param_ratio_linear1": float(_final["params_linear1"] / max(1, _baseline["params_linear1"])),
        "mac_ratio_conv": float(_final["macs_conv_per_image"] / max(1e-9, _baseline["macs_conv_per_image"])),
        "mac_ratio_linear1": float(_final["macs_linear1_per_image"] / max(1e-9, _baseline["macs_linear1_per_image"])),
        "latency_speedup": float(lat0_ms / lat1_ms) if lat1_ms > 0 else float("inf"),
        "overhead_vs_eval": float(
            _optimization_overhead / max(1e-9, timing.get("baseline_eval_s", 0.0))
        ),
    }

    _notes = {
        "compiled_eval": bool(globals().get("_EVAL_COMPILED", compiled_eval)),
        "gates_stripped": int(stripped),
    }

    GLOBAL_EXPERIMENT_SUMMARY = {
        "meta": _meta,
        "config": _config_summary,
        "guards": _guards_summary,
        "baseline": _baseline,
        "final": _final,
        "compression": _compression,
        "layers": _layers_summary,
        "timing": _timing_summary,
        "ratios": _ratios,
        "notes": _notes,
    }

    _out_dir = CONFIG.get("SAVE_DIR", "./output/phase4")
    _os.makedirs(_out_dir, exist_ok=True)
    _fname = f"phase4_summary_{_meta['approach']}_{_meta['backbone']}_{_meta['dataset']}.json"
    _summary_path = _os.path.join(_out_dir, _fname)
    with open(_summary_path, "w") as _f:
        _json.dump(GLOBAL_EXPERIMENT_SUMMARY, _f, indent=2)
    print(f"💾 Saved Phase-4 summary → {_summary_path}")
except Exception as _e:
    print(f"⚠️ Failed to build/save unified experiment summary: {_e}")

